insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-age:11-20ba746d17','aux-age',11,'El recurso extraordinario de revisión por error de hecho que resulte de los documentos del expediente se interpone en el plazo de:','["4 años desde la notificación de la resolución", "3 meses desde la notificación de la resolución", "1 año desde la notificación de la resolución", "2 meses desde que se tuvo conocimiento del error"]'::jsonb,0,'Art. 125.2 Ley 39/2015','Cuatro años desde la notificación en la causa a); tres meses en las demás causas.',null),
('aux-age:11-2b74392aee','aux-age',11,'Contra la resolución de un recurso de alzada:','["Cabe recurso potestativo de reposición ante el mismo órgano que resolvió la alzada", "Solo cabe el recurso extraordinario de revisión, en los casos del art. 125.1", "Cabe un nuevo recurso de alzada ante el superior jerárquico del que resolvió", "Solo cabe recurso potestativo de reposición ante el mismo órgano, en los casos del art. 125.1"]'::jsonb,1,'Art. 122.3 Ley 39/2015','No cabe ningún otro recurso administrativo, salvo el extraordinario de revisión en los casos previstos.',null),
('aux-age:11-4b4f084e88','aux-age',11,'Los daños causados por el personal al servicio de la Administración:','["Los particulares los reclaman directamente al empleado que los causó", "Los particulares los reclaman directamente a la Administración correspondiente", "Los particulares los reclaman al empleado y, subsidiariamente, a la Administración", "Solo pueden reclamarse por vía penal, como responsabilidad civil derivada del delito"]'::jsonb,1,'Art. 36.1 Ley 40/2015','Los particulares exigen directamente a la Administración las indemnizaciones por los daños causados por sus autoridades y personal.',null),
('aux-age:11-bd714cb784','aux-age',11,'Cuando la Administración ha indemnizado a un particular, exige de oficio a su personal la responsabilidad en que haya incurrido por:','["Cualquier error", "Culpa leve", "Dolo, o culpa o negligencia graves", "Nada: no puede repetir contra su personal"]'::jsonb,2,'Art. 36.2 Ley 40/2015','Exige de oficio, en vía administrativa, la responsabilidad por dolo, o culpa o negligencia graves.',null),
('aux-age:11-f2b766b704','aux-age',11,'¿Cuál es el plazo máximo para resolver que puede fijar una norma reguladora de un procedimiento?','["3 meses, salvo que una norma con rango de ley establezca uno mayor", "6 meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE", "1 año, salvo que una norma con rango de ley o el Derecho de la Unión Europea establezcan uno menor", "6 meses, sin excepción, cualquiera que sea el rango de la norma reguladora"]'::jsonb,1,'Art. 21.2 Ley 39/2015','El plazo no puede exceder de seis meses, salvo que una norma con rango de ley establezca uno mayor o lo prevea el Derecho de la UE.',null),
('aux-age:11-7c5adbd195','aux-age',11,'Si la norma reguladora de un procedimiento no fija plazo máximo para resolver, este será de:','["1 mes", "6 meses", "3 meses", "10 días"]'::jsonb,2,'Art. 21.3 Ley 39/2015','Cuando las normas no fijen el plazo máximo, será de tres meses.',null),
('aux-age:11-0307aa21b1','aux-age',11,'En los procedimientos iniciados a solicitud del interesado, el silencio administrativo es, como regla general:','["Desestimatorio, salvo las excepciones legales", "Causa de caducidad del procedimiento", "Desestimatorio, sin excepción", "Estimatorio, salvo las excepciones legales"]'::jsonb,3,'Art. 24.1 Ley 39/2015','El vencimiento del plazo sin resolución expresa legitima al interesado para entender estimada su solicitud, salvo las excepciones previstas.',null),
('aux-age:11-120f59c470','aux-age',11,'En los procedimientos iniciados de oficio en los que la Administración ejerce potestades sancionadoras o de intervención, el vencimiento del plazo sin resolución produce:','["La caducidad", "La estimación por silencio", "La desestimación por silencio", "La prórroga automática del plazo"]'::jsonb,0,'Art. 25.1 b) Ley 39/2015','En esos procedimientos se produce la caducidad.',null),
('aux-age:11-6af64d068c','aux-age',11,'Cuando los plazos se señalan por días, se entiende que son:','["Naturales, salvo que una ley disponga otro cómputo", "Hábiles, excluyéndose los sábados, los domingos y los festivos", "Hábiles, excluyéndose solo los domingos y los declarados festivos", "Naturales, salvo en el mes de agosto, en que son hábiles"]'::jsonb,1,'Art. 30.2 Ley 39/2015','Los plazos por días son hábiles y se excluyen sábados, domingos y festivos.',null),
('aux-age:11-812cd0d82a','aux-age',11,'Los plazos señalados por horas no pueden tener una duración superior a:','["12 horas", "48 horas", "24 horas", "72 horas"]'::jsonb,2,'Art. 30.1 Ley 39/2015','Son hábiles todas las horas de un día hábil y no pueden superar 24 horas; si no, se expresan en días.',null),
('aux-age:11-06413e1ee5','aux-age',11,'Los plazos fijados en meses o años se computan:','["Por días hábiles, a partir del día siguiente a la notificación o publicación", "Por días naturales, desde el mismo día de la notificación o publicación", "Desde el mismo día de la notificación o publicación del acto", "A partir del día siguiente a la notificación o publicación del acto"]'::jsonb,3,'Art. 30.4 Ley 39/2015','Se computan a partir del día siguiente a la notificación o publicación, de fecha a fecha.',null),
('aux-age:11-6275b37c06','aux-age',11,'La ampliación de los plazos establecidos no puede exceder de:','["La mitad de los mismos", "El doble de los mismos", "Un mes en todo caso", "Tres meses"]'::jsonb,0,'Art. 32.1 Ley 39/2015','La ampliación no puede exceder de la mitad del plazo.',null),
('aux-age:11-76bd825b98','aux-age',11,'¿Cuál de las siguientes NO es una forma de iniciación de oficio del procedimiento?','["Propia iniciativa del órgano", "Orden superior", "Solicitud del interesado", "Petición razonada de otros órganos"]'::jsonb,2,'Art. 58 Ley 39/2015','De oficio se inicia por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia. La solicitud del interesado es la otra vía de inicio.',null),
('aux-age:11-ec1db878eb','aux-age',11,'Si la solicitud no reúne los requisitos exigidos, se requiere al interesado para que la subsane en el plazo de:','["5 días, con indicación de que si no lo hace se archivará sin más trámite", "10 días, con indicación de que si no lo hace se le tendrá por desistido", "15 días, con indicación de que si no lo hace se le tendrá por desistido", "10 días, con indicación de que si no lo hace se declarará la caducidad"]'::jsonb,1,'Art. 68.1 Ley 39/2015','Se le da un plazo de diez días, con apercibimiento de que, si no lo hace, se le tendrá por desistido.',null),
('aux-age:11-bc2835f0da','aux-age',11,'El periodo de prueba en el procedimiento administrativo tiene una duración:','["No superior a 15 días ni inferior a 5", "De 20 días exactos", "No superior a 30 días ni inferior a 10", "No superior a 2 meses"]'::jsonb,2,'Art. 77.2 Ley 39/2015','El periodo de prueba no puede ser superior a treinta días ni inferior a diez.',null),
('aux-age:11-2ed9bb057f','aux-age',11,'Salvo disposición expresa en contrario, los informes son:','["Preceptivos y vinculantes", "Preceptivos y no vinculantes", "Facultativos y vinculantes", "Facultativos y no vinculantes"]'::jsonb,3,'Art. 80.1 Ley 39/2015','Salvo disposición expresa, los informes son facultativos y no vinculantes.',null),
('aux-age:11-db71af32b0','aux-age',11,'Salvo que se fije otro plazo, los informes deben emitirse en:','["10 días", "15 días", "1 mes", "3 días"]'::jsonb,0,'Art. 80.2 Ley 39/2015','Los informes se emiten en el plazo de diez días, salvo que una disposición o el cumplimiento del resto de plazos exija otro.',null),
('aux-age:11-887ec98d14','aux-age',11,'En el trámite de audiencia, los interesados disponen de un plazo:','["No inferior a 5 días ni superior a 10", "No inferior a 10 días ni superior a 15", "De 20 días", "No inferior a 15 días ni superior a 30"]'::jsonb,1,'Art. 82.2 Ley 39/2015','El plazo de audiencia no puede ser inferior a diez días ni superior a quince.',null),
('aux-age:11-16e42cfcff','aux-age',11,'El plazo del trámite de información pública no puede ser inferior a:','["10 días", "15 días", "20 días", "1 mes"]'::jsonb,2,'Art. 83.2 Ley 39/2015','El plazo de información pública no puede ser inferior a veinte días.',null),
('aux-age:11-d139bbfd43','aux-age',11,'¿Cuál de las siguientes NO pone fin al procedimiento administrativo?','["La resolución", "El desistimiento", "La declaración de caducidad", "La interposición de un recurso"]'::jsonb,3,'Art. 84.1 Ley 39/2015','Ponen fin al procedimiento la resolución, el desistimiento, la renuncia y la caducidad, y también la imposibilidad material sobrevenida.',null),
('aux-age:11-0acceb8b8a','aux-age',11,'En un procedimiento iniciado a solicitud que se paraliza por causa del interesado, la Administración le advierte de que se producirá la caducidad pasados:','["3 meses", "1 mes", "6 meses", "10 días"]'::jsonb,0,'Art. 95.1 Ley 39/2015','Transcurridos tres meses tras la advertencia sin que el interesado actúe, se produce la caducidad.',null),
('aux-age:11-7db74bcabc','aux-age',11,'¿Cuál de los siguientes NO es un medio de ejecución forzosa de los actos administrativos?','["El apremio sobre el patrimonio", "La revocación del acto", "La ejecución subsidiaria", "La multa coercitiva"]'::jsonb,1,'Art. 100.1 Ley 39/2015','Los medios son el apremio sobre el patrimonio, la ejecución subsidiaria, la multa coercitiva y la compulsión sobre las personas.',null),
('aux-age:11-490f5a58d5','aux-age',11,'Según el art. 1.1 de la Ley 29/1998, los órganos del orden contencioso-administrativo conocen de las pretensiones relativas a:','["La actuación de las Administraciones sujeta al Derecho Administrativo, las disposiciones de rango inferior a la ley y los Decretos legislativos que excedan la delegación", "La actuación de las Administraciones sujeta al Derecho privado y laboral, así como las leyes de las Cortes Generales y autonómicas que vulneren la Constitución", "Las disposiciones de rango inferior a la ley, pero no los Decretos legislativos, que solo controla el Tribunal Constitucional", "Cualquier conflicto entre particulares y Administraciones, sea cual sea el Derecho aplicable a la relación"]'::jsonb,0,'Art. 1.1 Ley 29/1998','Conocen de la actuación administrativa sujeta al Derecho Administrativo, de las disposiciones generales de rango inferior a la ley y de los Decretos legislativos que excedan los límites de la delegación.',null),
('aux-age:11-b8f382137e','aux-age',11,'¿Cuál de los siguientes NO es un órgano del orden jurisdiccional contencioso-administrativo?','["Los Juzgados Centrales de lo Contencioso-administrativo", "Los Juzgados de lo Social", "La Sala de lo Contencioso-administrativo de la Audiencia Nacional", "Las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia"]'::jsonb,1,'Art. 6 Ley 29/1998','Son órganos de este orden los Juzgados de lo C-A, los Juzgados Centrales de lo C-A, las Salas de lo C-A de los TSJ, la de la Audiencia Nacional y la del Tribunal Supremo.',null),
('aux-age:11-c3c7d02635','aux-age',11,'Los recursos contra los actos de las Entidades locales (salvo los instrumentos de planeamiento urbanístico) corresponden, en única o primera instancia, a:','["La Sala de lo Contencioso-administrativo del Tribunal Superior de Justicia", "La Sala de lo Contencioso-administrativo de la Audiencia Nacional", "Los Juzgados de lo Contencioso-administrativo", "Los Juzgados Centrales de lo Contencioso-administrativo"]'::jsonb,2,'Art. 8.1 Ley 29/1998','Corresponden a los Juzgados de lo Contencioso-administrativo, excluidas las impugnaciones de instrumentos de planeamiento urbanístico.',null),
('aux-age:11-0a52fe0b0e','aux-age',11,'Según el art. 19.1 a), están legitimadas ante el orden contencioso-administrativo:','["Las personas físicas de nacionalidad española que ostenten un derecho subjetivo", "Las personas físicas o jurídicas que hayan sido parte en el procedimiento administrativo", "Las personas jurídicas inscritas en un registro público que acrediten un interés directo", "Las personas físicas o jurídicas que ostenten un derecho o interés legítimo"]'::jsonb,3,'Art. 19.1 a) Ley 29/1998','Están legitimadas las personas físicas o jurídicas que ostenten un derecho o interés legítimo.',null),
('aux-age:11-1b7d0c851a','aux-age',11,'Los funcionarios públicos pueden comparecer por sí mismos, sin abogado ni procurador:','["En defensa de sus derechos estatutarios, en cuestiones de personal que no impliquen separación de empleados inamovibles", "En defensa de sus derechos estatutarios, en cualquier cuestión de personal, incluida la separación de empleados públicos inamovibles", "Solo en los recursos de casación y en los procedimientos de cuantía inferior a 30.000 euros", "En ningún caso, pues en este orden siempre es preceptiva la asistencia de abogado"]'::jsonb,0,'Art. 23.3 Ley 29/1998','Pueden hacerlo en defensa de sus derechos estatutarios, cuando se trate de cuestiones de personal que no impliquen separación de empleados públicos inamovibles.',null),
('aux-age:11-d16420320c','aux-age',11,'El recurso contencioso-administrativo es admisible contra:','["Las disposiciones de carácter general y los actos expresos que pongan fin a la vía administrativa, pero no los presuntos", "Las disposiciones de carácter general y los actos expresos y presuntos que pongan fin a la vía administrativa", "Los actos expresos y presuntos que no pongan fin a la vía administrativa, pero no las disposiciones generales", "Las leyes de las Cortes Generales y los actos expresos de la Administración"]'::jsonb,1,'Art. 25.1 Ley 29/1998','Contra disposiciones de carácter general y actos expresos y presuntos que pongan fin a la vía administrativa, definitivos o de trámite cualificados.',null),
('aux-age:11-235616480f','aux-age',11,'Además de contra actos y disposiciones, el recurso contencioso-administrativo cabe contra:','["Las decisiones del Gobierno en sus relaciones con las Cortes Generales", "La inactividad de la Administración, pero no sus actuaciones materiales", "La inactividad de la Administración y sus actuaciones materiales que constituyan vía de hecho", "Los contratos privados celebrados entre particulares y las actuaciones materiales derivadas de ellos"]'::jsonb,2,'Art. 25.2 Ley 29/1998','También es admisible contra la inactividad de la Administración y contra sus actuaciones materiales constitutivas de vía de hecho.',null),
('aux-age:11-e7971bdd88','aux-age',11,'Con carácter general, el recurso contencioso-administrativo se inicia:','["Por escrito de demanda, con la que se acompañan las pruebas y el expediente administrativo completo remitido por la Administración", "Mediante comparecencia verbal ante el Letrado de la Administración de Justicia del juzgado", "Mediante solicitud previa a la Administración demandada para que remita el expediente al juzgado", "Por escrito que cita el acto o actuación impugnados y solicita que se tenga por interpuesto el recurso"]'::jsonb,3,'Art. 45.1 Ley 29/1998','Se inicia por un escrito reducido a citar lo que se impugna y a pedir que se tenga por interpuesto el recurso.',null),
('aux-age:11-b78ee81259','aux-age',11,'Si el acto que pone fin a la vía administrativa es expreso, el plazo para interponer el recurso contencioso-administrativo es de:','["Dos meses desde el día siguiente a su publicación o notificación", "Un mes desde el día siguiente a su publicación o notificación", "Seis meses desde el día siguiente a su publicación o notificación", "Dos meses desde el mismo día de su publicación o notificación"]'::jsonb,0,'Art. 46.1 Ley 29/1998','Dos meses contados desde el día siguiente a la publicación o notificación del acto.',null),
('aux-age:11-fe55ec1d77','aux-age',11,'Contra una vía de hecho sin requerimiento previo a la Administración, el plazo para recurrir es de:','["Diez días desde que se inició la actuación", "Veinte días desde que se inició la actuación", "Dos meses desde que se inició la actuación", "Un mes desde que terminó la actuación material"]'::jsonb,1,'Art. 46.3 Ley 29/1998','Si no hubo requerimiento, veinte días desde que se inició la actuación. Si lo hubo, diez días desde que terminó el plazo del requerimiento.',null),
('aux-age:11-2292e472e6','aux-age',11,'¿De qué plazo dispone el recurrente para formalizar la demanda?','["Diez días", "Quince días", "Veinte días", "Un mes"]'::jsonb,2,'Art. 52.1 Ley 29/1998','La demanda se deduce en el plazo de veinte días.',null),
('aux-age:11-698187966f','aux-age',11,'¿De qué plazo dispone la Administración demandada para contestar a la demanda?','["Diez días", "Un mes", "Quince días", "Veinte días"]'::jsonb,3,'Art. 54.1 Ley 29/1998','La contestación se presenta en el plazo de veinte días.',null),
('aux-age:11-c00744e736','aux-age',11,'Se sigue el procedimiento abreviado, entre otros casos, en los asuntos cuya cuantía no supere:','["30.000 euros", "6.000 euros", "60.000 euros", "100.000 euros"]'::jsonb,0,'Art. 78.1 Ley 29/1998','Se tramitan por el procedimiento abreviado, entre otros, los asuntos cuya cuantía no supere los 30.000 euros.',null),
('aux-age:11-97bb812505','aux-age',11,'No son apelables las sentencias de los Juzgados dictadas en asuntos cuya cuantía no exceda de:','["6.000 euros", "30.000 euros", "18.000 euros", "600.000 euros"]'::jsonb,1,'Art. 81.1 a) Ley 29/1998','No son apelables cuando la cuantía no excede de 30.000 euros, salvo los supuestos del art. 81.2.',null),
('aux-age:11-e57bbea2f3','aux-age',11,'Las sentencias que declaren la inadmisión del recurso:','["Nunca son apelables", "Solo son apelables si la cuantía supera 30.000 euros", "Son siempre apelables", "Solo admiten recurso de reposición"]'::jsonb,2,'Art. 81.2 a) Ley 29/1998','Las sentencias que declaren la inadmisión del recurso son siempre apelables.',null),
('aux-age:11-1abda018c9','aux-age',11,'El recurso de apelación se interpone dentro de:','["Los diez días siguientes a la notificación de la sentencia", "El mes siguiente", "Los dos meses siguientes", "Los quince días siguientes a la notificación de la sentencia"]'::jsonb,3,'Art. 85.1 Ley 29/1998','Se interpone dentro de los quince días siguientes al de la notificación de la sentencia.',null),
('aux-age:11-713d50dfdb','aux-age',11,'¿Cuándo puede instarse la ejecución forzosa de una sentencia que la Administración no ha cumplido?','["Transcurridos dos meses desde su comunicación, o el plazo fijado para su cumplimiento", "Transcurridos seis meses desde su firmeza, sin que la sentencia pueda fijar otro plazo para su cumplimiento", "Transcurridos tres meses desde su comunicación al órgano obligado, salvo que la sentencia fije otro plazo", "Transcurrido un mes desde su comunicación, o el plazo fijado para su cumplimiento"]'::jsonb,0,'Art. 104.2 Ley 29/1998','Transcurridos dos meses desde la comunicación de la sentencia, o el plazo fijado en ella, cualquiera de las partes y personas afectadas puede instar su ejecución forzosa.',null),
('aux-age:11-4ae227f0b0','aux-age',11,'La tramitación del recurso para la protección de los derechos fundamentales de la persona tiene carácter:','["Ordinario", "Preferente", "Facultativo", "Secreto"]'::jsonb,1,'Art. 114.3 Ley 29/1998','La tramitación de estos recursos tiene carácter preferente.',null),
('aux-age:11-de38b144a2','aux-age',11,'El plazo para interponer el recurso especial de protección de los derechos fundamentales es de:','["Dos meses", "Veinte días", "Diez días", "Un mes"]'::jsonb,2,'Art. 115.1 Ley 29/1998','El plazo es de diez días.',null),
('aux-age:11-9aba4ee134','aux-age',11,'¿Cuándo pueden solicitar los interesados la adopción de medidas cautelares?','["Solo al presentar la demanda", "Solo antes de la vista", "Solo en apelación", "En cualquier estado del proceso"]'::jsonb,3,'Art. 129.1 Ley 29/1998','Pueden solicitarlas en cualquier estado del proceso para asegurar la efectividad de la sentencia.',null),
('aux-age:11-adc2924233','aux-age',11,'Cuando se alegan circunstancias de especial urgencia, el juez puede resolver sobre las medidas cautelares:','["Sin oír a la parte contraria, en el plazo de dos días", "Solo tras oír a todas las partes durante diez días", "Solo tras la sentencia", "Únicamente si lo autoriza la Administración"]'::jsonb,0,'Art. 135.1 Ley 29/1998','Puede decidir sin oír a la parte contraria, en el plazo de dos días.',null),
('aux-age:11-218750c26f','aux-age',11,'En primera o única instancia, las costas se imponen como regla general:','["A la Administración demandada en todo caso, salvo que el recurso sea temerario", "A quien vea rechazadas todas sus pretensiones, salvo que el órgano aprecie y razone serias dudas de hecho o de derecho", "A cada parte las causadas a su instancia y las comunes por mitad, en todo caso y sin que el órgano pueda apreciar temeridad", "Al demandante que vea rechazada cualquiera de sus pretensiones, aunque haya dudas de derecho"]'::jsonb,1,'Art. 139.1 Ley 29/1998','Rige el criterio del vencimiento, salvo que el órgano aprecie y razone que el caso presentaba serias dudas de hecho o de derecho.',null),
('aux-age:7-69fac6eb74','aux-age',7,'La información de publicidad activa debe publicarse:','["En las sedes electrónicas o páginas web, de forma clara y estructurada, preferiblemente en formatos reutilizables", "En el boletín oficial correspondiente y, si el organismo dispone de ella, también en su página web, en formato no reutilizable", "En el tablón de anuncios físico de cada organismo y en su sede electrónica, en formato papel", "En la página web, pero solo a petición del interesado y en el formato que este elija, sin obligación de que sean reutilizables ni de actualizarla periódicamente"]'::jsonb,0,'Art. 5.4 Ley 19/2013','Se publica en las sedes electrónicas o páginas web, de manera clara, estructurada y entendible, y preferiblemente en formatos reutilizables.',null),
('aux-age:7-67a9fb0147','aux-age',7,'El Portal de la Transparencia de la Administración General del Estado depende:','["Del Consejo de Transparencia y Buen Gobierno", "Del Ministerio de la Presidencia", "Del Defensor del Pueblo", "De las Cortes Generales"]'::jsonb,1,'Art. 10.1 Ley 19/2013','El Portal de la Transparencia depende del Ministerio de la Presidencia.',null),
('aux-age:7-b37c989854','aux-age',7,'¿Quién tiene derecho a acceder a la información pública según la Ley 19/2013?','["Los ciudadanos españoles y los extranjeros residentes legalmente en España", "Solo quienes tengan la condición de interesados en un procedimiento administrativo", "Todas las personas, en los términos del art. 105.b) de la Constitución", "Los mayores de edad empadronados en España, en los términos de la Ley 39/2015"]'::jsonb,2,'Art. 12 Ley 19/2013','Todas las personas tienen derecho a acceder a la información pública, en los términos del art. 105.b) de la Constitución.',null),
('aux-age:7-a942524388','aux-age',7,'Según la Ley 19/2013, se entiende por información pública:','["Los documentos publicados en el BOE y en los boletines autonómicos y provinciales", "Los contenidos o documentos en poder de los sujetos obligados, cualquiera que sea su origen, autor o finalidad, incluidos los privados", "Los documentos que los ciudadanos entregan a la Administración en un procedimiento", "Los contenidos o documentos en poder de los sujetos obligados, elaborados o adquiridos en el ejercicio de sus funciones"]'::jsonb,3,'Art. 13 Ley 19/2013','Son los contenidos o documentos, cualquiera que sea su formato o soporte, en poder de los sujetos obligados, elaborados o adquiridos en el ejercicio de sus funciones.',null),
('aux-age:7-917249e18f','aux-age',7,'Al presentar una solicitud de acceso a la información pública, el solicitante:','["No está obligado a motivarla", "Debe motivarla siempre", "Debe acreditar un interés legítimo", "Debe pagar una tasa previa"]'::jsonb,0,'Art. 17.3 Ley 19/2013','El solicitante no está obligado a motivar su solicitud, aunque puede exponer los motivos.',null),
('aux-age:7-0257c5662c','aux-age',7,'¿En qué plazo debe resolverse una solicitud de acceso a la información pública?','["Diez días desde su recepción por el órgano competente, ampliable por otros diez", "Un mes desde su recepción por el órgano competente, ampliable por otro mes", "Tres meses desde su presentación, ampliable por otros tres", "Quince días hábiles desde su presentación, sin posibilidad de ampliación"]'::jsonb,1,'Art. 20.1 Ley 19/2013','El plazo máximo es de un mes desde la recepción por el órgano competente, ampliable por otro mes por el volumen o la complejidad de la información.',null),
('aux-age:7-e2f64a54c4','aux-age',7,'Si no se resuelve en plazo una solicitud de acceso a la información pública, se entiende:','["Estimada", "Caducada", "Desestimada", "Remitida al Consejo de Transparencia"]'::jsonb,2,'Art. 20.4 Ley 19/2013','Transcurrido el plazo sin resolución expresa, la solicitud se entiende desestimada.',null),
('aux-age:7-86e5de6144','aux-age',7,'El acceso a la información pública es:','["De pago, conforme a las tasas que fije cada Administración", "Gratuito sin excepción alguna, incluidas la expedición de copias y la transposición a otro formato", "Gratuito para las personas físicas y de pago para las empresas", "Gratuito, sin perjuicio de las exacciones por expedición de copias o cambio de formato"]'::jsonb,3,'Art. 22.4 Ley 19/2013','El acceso es gratuito, aunque pueden exigirse exacciones por la expedición de copias o la transposición a formatos distintos del original.',null),
('aux-age:7-64707d7f7f','aux-age',7,'La reclamación ante el Consejo de Transparencia y Buen Gobierno:','["Es potestativa y previa a la vía contencioso-administrativa, y se presenta en el plazo de un mes", "Es obligatoria y previa a la vía contencioso-administrativa, y se presenta en el plazo de un mes", "Es potestativa y previa a la vía contencioso-administrativa, y se presenta en el plazo de tres meses", "Sustituye al recurso contencioso-administrativo, y se presenta en el plazo de dos meses"]'::jsonb,0,'Art. 24 Ley 19/2013','Es potestativa y previa a la impugnación en vía contencioso-administrativa. Se presenta en el plazo de un mes.',null),
('aux-age:7-978b54269d','aux-age',7,'¿En qué plazo debe resolver el Consejo de Transparencia y Buen Gobierno una reclamación?','["Un mes; transcurrido ese plazo sin resolución, se entiende estimada", "Tres meses; transcurrido ese plazo, se entiende desestimada", "Seis meses; transcurrido ese plazo, se entiende desestimada", "Tres meses; transcurrido ese plazo sin resolución expresa, se entiende estimada"]'::jsonb,1,'Art. 24.4 Ley 19/2013','El plazo máximo es de tres meses. Transcurrido sin resolución, la reclamación se entiende desestimada.',null),
('aux-age:7-68ee33c627','aux-age',7,'El Presidente del Consejo de Transparencia y Buen Gobierno es nombrado por un periodo de:','["Cuatro años renovables", "Seis años", "Cinco años no renovable", "Tres años renovables una vez"]'::jsonb,2,'Art. 37.1 Ley 19/2013','Es nombrado por un período no renovable de cinco años.',null),
('aux-age:7-10af6a7040','aux-age',7,'¿Cuál de los siguientes es un límite al derecho de acceso a la información pública?','["Que el solicitante no motive su solicitud ni explique para qué la quiere", "Que la información tenga más de cinco años de antigüedad", "Que la información solo esté disponible en formato papel", "Que el acceso suponga un perjuicio para la seguridad nacional"]'::jsonb,3,'Art. 14.1 Ley 19/2013','Entre los límites están la seguridad nacional, la defensa y las relaciones exteriores, entre otros.',null),
('aux-age:7-8ec9097419','aux-age',7,'Según la Ley 19/2013, el Consejo de Transparencia y Buen Gobierno es:','["Un organismo público con personalidad jurídica propia", "Una dirección general del Ministerio de Hacienda", "Un órgano de las Cortes Generales", "Un órgano del Poder Judicial"]'::jsonb,0,'Art. 33 Ley 19/2013','Es un organismo público con personalidad jurídica propia y plena capacidad de obrar.',null),
('aux-age:12-b78a6ac67c','aux-age',12,'La LO 3/2018 de Protección de Datos tiene por objeto:','["Sustituir al Reglamento (UE) 2016/679 y regular los derechos digitales", "Adaptar el ordenamiento español al Reglamento (UE) 2016/679 y garantizar los derechos digitales", "Trasponer la Directiva 95/46/CE y regular la videovigilancia", "Adaptar el ordenamiento al Reglamento (UE) 2016/679, pero sin regular los llamados derechos digitales"]'::jsonb,1,'Art. 1 LO 3/2018','Adapta el ordenamiento al Reglamento (UE) 2016/679 y garantiza los derechos digitales conforme al art. 18.4 de la Constitución.',null),
('aux-age:12-04ab1e033c','aux-age',12,'El deber de confidencialidad de quienes intervienen en el tratamiento de datos:','["Termina al finalizar la relación con el responsable", "Dura un año tras finalizar la relación", "Se mantiene aun cuando haya finalizado la relación", "Solo afecta al responsable del tratamiento"]'::jsonb,2,'Art. 5 LO 3/2018','Afecta a responsables, encargados y demás intervinientes, y se mantiene aun cuando haya finalizado la relación.',null),
('aux-age:12-6fdff52ba9','aux-age',12,'¿Cómo define la LO 3/2018 el consentimiento del afectado?','["Toda manifestación de voluntad libre, informada e inequívoca, aunque sea tácita o derive del silencio", "Toda manifestación de voluntad expresa y por escrito, firmada en papel o electrónicamente", "La aceptación tácita de las condiciones, siempre que se haya informado previamente", "Toda manifestación de voluntad libre, específica, informada e inequívoca"]'::jsonb,3,'Art. 6.1 LO 3/2018','Es toda manifestación de voluntad libre, específica, informada e inequívoca, mediante una declaración o una clara acción afirmativa.',null),
('aux-age:12-3118d8497a','aux-age',12,'El tratamiento de los datos de un menor puede basarse en su propio consentimiento cuando sea mayor de:','["Catorce años", "Dieciséis años", "Doce años", "Dieciocho años"]'::jsonb,0,'Art. 7.1 LO 3/2018','Solo cuando sea mayor de catorce años, salvo que la ley exija la asistencia de los titulares de la patria potestad o tutela.',null),
('aux-age:12-b0df820786','aux-age',12,'¿Basta el consentimiento del afectado para tratar datos cuya finalidad principal sea identificar su ideología o religión?','["Sí, siempre", "No, el solo consentimiento no basta para levantar la prohibición", "Sí, si es por escrito", "Solo si lo autoriza la Agencia Española de Protección de Datos"]'::jsonb,1,'Art. 9.1 LO 3/2018','El solo consentimiento no basta para tratar datos cuya finalidad principal sea identificar ideología, afiliación sindical, religión, orientación sexual, creencias u origen racial o étnico.',null),
('aux-age:12-0f5a62233d','aux-age',12,'Los artículos 13 a 18 de la LO 3/2018 regulan los derechos de:','["Petición, queja, sugerencia, acceso a archivos y registros públicos, y reclamación ante la Agencia", "Acceso a la información pública, rectificación, reclamación y oposición", "Acceso, rectificación, supresión, limitación del tratamiento, portabilidad y oposición", "Rectificación, réplica, supresión y olvido en medios de comunicación"]'::jsonb,2,'Arts. 13 a 18 LO 3/2018','Regulan, en este orden, los derechos de acceso, rectificación, supresión, limitación del tratamiento, portabilidad y oposición.',null),
('aux-age:12-71a279db21','aux-age',12,'¿Cuándo deben designar un delegado de protección de datos los responsables y encargados del tratamiento?','["Solo cuando tengan más de 250 empleados o traten datos de más de 10.000 personas", "En ningún caso es obligatorio, aunque la ley recomienda su designación a las entidades públicas", "Solo cuando lo requiera expresamente la Agencia Española de Protección de Datos", "En los supuestos del art. 37.1 del Reglamento (UE) 2016/679 y en las entidades que enumera la ley"]'::jsonb,3,'Art. 34.1 LO 3/2018','Deben designarlo en los supuestos del art. 37.1 del Reglamento europeo y, en todo caso, en las entidades que enumera el propio artículo.',null),
('aux-age:12-a2e3e12b58','aux-age',12,'La Agencia Española de Protección de Datos es:','["Una autoridad administrativa independiente de ámbito estatal", "Una dirección general adscrita al Ministerio del Interior, sin personalidad jurídica", "Un órgano adscrito al Consejo General del Poder Judicial", "Una agencia de la Unión Europea con sede en España"]'::jsonb,0,'Art. 44.1 LO 3/2018','Es una autoridad administrativa independiente de ámbito estatal.',null),
('aux-age:12-4fe384e490','aux-age',12,'El mandato de la Presidencia de la Agencia Española de Protección de Datos es de:','["Cuatro años, no renovable", "Cinco años, renovable por otro periodo de igual duración", "Seis años, no renovable, contados desde su toma de posesión", "Cuatro años, renovable por otro periodo de igual duración"]'::jsonb,1,'Art. 48.5 LO 3/2018','El mandato es de cinco años y puede renovarse por otro periodo de igual duración.',null),
('aux-age:12-459cbdb65e','aux-age',12,'¿Cuándo prescriben las infracciones leves en materia de protección de datos?','["A los seis meses", "A los dos años", "Al año", "A los tres años"]'::jsonb,2,'Art. 74 LO 3/2018','Las infracciones muy graves prescriben a los tres años (art. 72), las graves a los dos años (art. 73) y las leves al año (art. 74).',null),
('aux-age:12-8a24a63e22','aux-age',12,'Las sanciones de protección de datos de importe superior a 300.000 euros prescriben a:','["Al año", "Los dos años", "Los seis meses", "Los tres años"]'::jsonb,3,'Art. 78.1 LO 3/2018','Hasta 40.000 € prescriben al año; entre 40.001 y 300.000 €, a los dos años; y las superiores a 300.000 €, a los tres años.',null),
('aux-age:12-12c35e36af','aux-age',12,'¿Se aplica el régimen sancionador de la LO 3/2018 al delegado de protección de datos?','["No", "Sí, en todo caso", "Solo por infracciones muy graves", "Solo si es personal laboral"]'::jsonb,0,'Art. 70.2 LO 3/2018','El régimen sancionador de la ley no es de aplicación al delegado de protección de datos.',null),
('aux-age:12-2a6dbab386','aux-age',12,'Los herederos de una persona fallecida, ¿pueden solicitar el acceso, la rectificación o la supresión de sus datos?','["No, salvo que el fallecido lo hubiese autorizado expresamente en vida", "Sí, salvo que el fallecido lo hubiese prohibido expresamente o lo establezca una ley", "Sí, pero solo con autorización judicial y acreditando un interés legítimo", "Sí, durante el primer año tras el fallecimiento, salvo prohibición expresa del fallecido"]'::jsonb,1,'Art. 3.1 LO 3/2018','Pueden hacerlo las personas vinculadas al fallecido por razones familiares o de hecho y sus herederos, salvo prohibición expresa del fallecido o de una ley.',null),
('aux-age:13-c3ec387524','aux-age',13,'Según el art. 8.2 del TREBEP, los empleados públicos se clasifican en:','["Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual", "Funcionarios de carrera, funcionarios interinos, personal laboral, personal eventual y personal directivo profesional", "Funcionarios de carrera, personal laboral, personal eventual y personal directivo", "Funcionarios de carrera, funcionarios interinos y personal laboral fijo o temporal"]'::jsonb,0,'Art. 8.2 TREBEP','Se clasifican en funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido o temporal) y personal eventual.',null),
('aux-age:13-1079ba28ff','aux-age',13,'Las funciones que implican participación directa o indirecta en el ejercicio de potestades públicas corresponden:','["A cualquier empleado público, sea funcionario o laboral", "Exclusivamente a los funcionarios públicos", "Al personal laboral fijo y a los funcionarios de carrera, en los términos que establezca la ley de cada Administración", "Exclusivamente a los funcionarios de carrera, nunca a los interinos"]'::jsonb,1,'Art. 9.2 TREBEP','Corresponden exclusivamente a los funcionarios públicos, en los términos que establezca la ley de desarrollo de cada Administración.',null),
('aux-age:13-59063ab86c','aux-age',13,'Un funcionario interino nombrado para cubrir una plaza vacante puede ocuparla como máximo:','["Un año", "Dos años", "Tres años", "Cinco años"]'::jsonb,2,'Art. 10.1 a) TREBEP','Las plazas vacantes pueden cubrirse por interinos cuando no sea posible su cobertura por funcionarios de carrera, por un máximo de tres años.',null),
('aux-age:13-494e9f6853','aux-age',13,'El nombramiento de interinos por exceso o acumulación de tareas tiene un plazo máximo de:','["Seis meses dentro de un periodo de doce", "Doce meses dentro de un periodo de veinticuatro", "Tres años", "Nueve meses dentro de un periodo de dieciocho"]'::jsonb,3,'Art. 10.1 d) TREBEP','El plazo máximo es de nueve meses dentro de un periodo de dieciocho meses.',null),
('aux-age:13-863c8f7ef2','aux-age',13,'El nombramiento de interinos para ejecutar programas de carácter temporal no puede superar:','["Tres años, ampliable hasta doce meses más por las leyes de Función Pública", "Dos años, ampliable hasta seis meses más por las leyes de Función Pública que se dicten en desarrollo del Estatuto", "Tres años, sin posibilidad de ampliación", "Cuatro años, ampliable hasta doce meses más por las leyes de Función Pública"]'::jsonb,0,'Art. 10.1 c) TREBEP','No puede ser superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública de cada Administración.',null),
('aux-age:13-dbe96b23fb','aux-age',13,'El personal eventual realiza funciones:','["De carácter técnico permanente, previstas en la relación de puestos de trabajo de cada Administración", "Expresamente calificadas como de confianza o asesoramiento especial", "De inspección y control, expresamente calificadas como tales", "De confianza, pero que implican el ejercicio de potestades públicas"]'::jsonb,1,'Art. 12.1 TREBEP','El personal eventual solo realiza funciones expresamente calificadas como de confianza o asesoramiento especial.',null),
('aux-age:13-aef5a63002','aux-age',13,'Haber sido personal eventual, ¿puede constituir mérito para el acceso a la función pública?','["Sí, siempre", "Sí, si se prestaron servicios más de un año", "No", "Solo en la promoción interna"]'::jsonb,2,'Art. 12.4 TREBEP','La condición de personal eventual no puede constituir mérito para el acceso a la Función Pública o para la promoción interna.',null),
('aux-age:14-3b6f4bea39','aux-age',14,'¿Cuál de estos es un derecho individual que se ejerce de forma colectiva?','["La inamovilidad en la condición de funcionario", "La formación continua", "Las vacaciones", "El ejercicio de la huelga"]'::jsonb,3,'Art. 15 TREBEP','Son derechos individuales ejercidos colectivamente la libertad sindical, la negociación colectiva y participación, la huelga, el planteamiento de conflictos colectivos y la reunión.',null),
('aux-age:14-27a9ce63d3','aux-age',14,'¿Cuántos días de permiso por asuntos particulares tienen los funcionarios al año?','["Seis días", "Cuatro días", "Tres días", "Ocho días"]'::jsonb,0,'Art. 48 k) TREBEP','Por asuntos particulares, seis días al año.',null),
('aux-age:14-43d6da4993','aux-age',14,'¿Cuántos días de permiso corresponden por matrimonio o registro de pareja de hecho?','["Diez días", "Quince días", "Veinte días", "Siete días"]'::jsonb,1,'Art. 48 l) TREBEP','Quince días por matrimonio o registro o constitución formalizada por documento público de pareja de hecho.',null),
('aux-age:14-3c77007365','aux-age',14,'¿Qué duración tiene el permiso por nacimiento para la madre biológica según el TREBEP vigente?','["Dieciséis semanas", "Doce semanas", "Diecinueve semanas", "Veinticuatro semanas"]'::jsonb,2,'Art. 49 a) TREBEP','Tras la última reforma son diecinueve semanas (treinta y dos en caso de familia monoparental). Muchos tests antiguos siguen diciendo dieciséis.',null),
('aux-age:14-d7026c8a15','aux-age',14,'¿Cuántos días de vacaciones retribuidas tienen los funcionarios por año completo de servicio?','["Treinta días naturales", "Veinte días hábiles", "Veinticinco días hábiles", "Veintidós días hábiles"]'::jsonb,3,'Art. 50.1 TREBEP','Veintidós días hábiles, o los que correspondan proporcionalmente si el tiempo de servicio fue menor.',null),
('aux-age:13-e1879ba62d','aux-age',13,'¿Qué edad mínima se exige para participar en los procesos selectivos?','["Dieciséis años", "Dieciocho años", "Diecisiete años", "Veintiún años"]'::jsonb,0,'Art. 56.1 c) TREBEP','Tener cumplidos dieciséis años y no exceder, en su caso, la edad máxima de jubilación forzosa.',null),
('aux-age:13-9c058327d2','aux-age',13,'¿Cuáles son los sistemas selectivos de los funcionarios de carrera?','["Concurso y libre designación con convocatoria pública", "Oposición y concurso-oposición; el concurso, solo con carácter excepcional y en virtud de ley", "Oposición y concurso-oposición; el concurso, con carácter ordinario y sin necesidad de previsión en una ley", "Oposición, concurso y entrevista personal, que pueden utilizarse indistintamente según lo que decida cada convocatoria"]'::jsonb,1,'Art. 61.6 TREBEP','Son la oposición y el concurso-oposición. El concurso de valoración de méritos solo cabe excepcionalmente y en virtud de ley.',null),
('aux-age:13-0069550010','aux-age',13,'¿Cuál de los siguientes NO es un requisito para adquirir la condición de funcionario de carrera?','["Superar el proceso selectivo", "Acatar la Constitución", "Haber prestado servicios previos como interino", "Tomar posesión dentro del plazo establecido"]'::jsonb,2,'Art. 62.1 TREBEP','Se requiere superar el proceso selectivo, el nombramiento publicado en el diario oficial, el acatamiento de la Constitución (y Estatuto de Autonomía y resto del ordenamiento) y la toma de posesión.',null),
('aux-age:13-9b27e2cee7','aux-age',13,'¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?','["La renuncia", "La jubilación total", "La pérdida de la nacionalidad", "La excedencia voluntaria"]'::jsonb,3,'Art. 63 TREBEP','Son causas la renuncia, la pérdida de la nacionalidad, la jubilación total, la pena de inhabilitación firme y la sanción firme de separación del servicio. La excedencia es una situación administrativa.',null),
('aux-age:13-5d64ffabb4','aux-age',13,'La jubilación forzosa de los funcionarios se declara al cumplir:','["65 años, pudiendo solicitar la prolongación hasta los 70", "67 años, sin posibilidad de solicitar la prolongación de la permanencia en el servicio activo", "65 años, pudiendo solicitar la prolongación hasta los 72", "60 años, pudiendo solicitar la prolongación hasta los 65"]'::jsonb,0,'Art. 67.3 TREBEP','Se declara a los sesenta y cinco años, aunque el funcionario puede solicitar la prolongación de la permanencia hasta los setenta.',null),
('aux-age:13-a25e6c3198','aux-age',13,'¿Qué titulación se exige para acceder a un cuerpo del subgrupo C2?','["Bachiller o Técnico", "Graduado en Educación Secundaria Obligatoria", "Técnico Superior o equivalente a efectos profesionales", "Certificado de escolaridad o de estudios primarios"]'::jsonb,1,'Art. 76 TREBEP','Para el subgrupo C2 se exige el título de Graduado en ESO; para el C1, Bachiller o Técnico.',null),
('aux-age:13-10b0cfeaee','aux-age',13,'¿Cuál de estas NO es una situación administrativa de los funcionarios de carrera?','["Servicios especiales", "Excedencia", "Comisión de servicios", "Suspensión de funciones"]'::jsonb,2,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones. La comisión de servicios es una forma de provisión de puestos.',null),
('aux-age:13-b1c9b3cd95','aux-age',13,'Para obtener la excedencia voluntaria por interés particular hay que haber prestado servicios efectivos durante un mínimo de:','["Un año inmediatamente anterior a la solicitud", "Dos años inmediatamente anteriores", "Tres años, consecutivos o no, en cualquier Administración", "Cinco años inmediatamente anteriores"]'::jsonb,3,'Art. 89.2 TREBEP','Se exige haber prestado servicios efectivos en cualquier Administración durante un mínimo de cinco años inmediatamente anteriores.',null),
('aux-age:13-56f682a5f9','aux-age',13,'La excedencia por cuidado de cada hijo tiene una duración:','["No superior a tres años", "No superior a un año", "No superior a cinco años", "Sin límite"]'::jsonb,0,'Art. 89.4 TREBEP','El periodo de excedencia por cuidado de cada hijo no puede ser superior a tres años.',null),
('aux-age:13-377178290f','aux-age',13,'La suspensión firme de funciones por sanción disciplinaria no puede exceder de:','["Tres años", "Seis años", "Dos años", "Un año"]'::jsonb,1,'Art. 90.2 TREBEP','No puede exceder de seis años. Si supera seis meses, el funcionario pierde su puesto de trabajo (art. 90.1).',null),
('aux-age:14-71c8486cb5','aux-age',14,'Según el TREBEP, las faltas disciplinarias se clasifican en:','["Graves y leves", "Penales y administrativas", "Muy graves, graves y leves", "Muy graves y graves"]'::jsonb,2,'Art. 95.1 TREBEP','Las faltas disciplinarias pueden ser muy graves, graves y leves.',null),
('aux-age:14-a1bb8b2115','aux-age',14,'¿Cuál de las siguientes sanciones NO aparece expresamente en la lista del art. 96.1 del TREBEP?','["Apercibimiento", "Demérito", "Traslado forzoso", "Multa económica"]'::jsonb,3,'Art. 96.1 TREBEP','Recoge la separación del servicio, el despido disciplinario, la suspensión firme de funciones, el traslado forzoso, el demérito, el apercibimiento y cualquier otra que establezca una ley.',null),
('aux-age:14-d9e6917fab','aux-age',14,'¿Cuándo prescriben las faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres meses"]'::jsonb,0,'Art. 97 TREBEP','Las faltas muy graves prescriben a los tres años, las graves a los dos años y las leves a los seis meses.',null),
('aux-age:14-66f58402aa','aux-age',14,'¿Cuándo prescriben las sanciones impuestas por faltas leves?','["A los seis meses", "Al año", "A los dos años", "A los tres años"]'::jsonb,1,'Art. 97 TREBEP','Las sanciones por faltas muy graves prescriben a los tres años, las graves a los dos años y las leves al año.',null),
('aux-age:14-b9a171f1b1','aux-age',14,'La suspensión provisional como medida cautelar en un expediente disciplinario no puede exceder de:','["Tres meses, salvo paralización del procedimiento imputable al interesado", "Un año, salvo paralización del procedimiento imputable a la Administración que lo tramita", "Seis meses, salvo paralización del procedimiento imputable al interesado", "Seis meses, sin excepción alguna"]'::jsonb,2,'Art. 98.3 TREBEP','No puede exceder de seis meses, salvo en caso de paralización del procedimiento imputable al interesado.',null),
('aux-age:16-c3f8bd6295','aux-age',16,'La Ley Orgánica 3/2007 tiene por objeto:','["Hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres", "Establecer medidas de protección integral contra la violencia de género y de igualdad de oportunidades en el empleo", "Hacer efectivo el derecho de igualdad de trato entre mujeres y hombres, pero solo en el ámbito del empleo público y de la negociación colectiva", "Regular la igualdad de trato y la no discriminación por cualquier circunstancia personal"]'::jsonb,0,'Art. 1.1 LO 3/2007','Su objeto es hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres.',null),
('aux-age:16-6765497459','aux-age',16,'El principio de igualdad de trato entre mujeres y hombres supone:','["La igualdad en el ámbito laboral y en el acceso al empleo", "La ausencia de toda discriminación, directa o indirecta, por razón de sexo", "La ausencia de discriminación directa por razón de sexo, pero no de la indirecta, que se rige por la normativa laboral", "La paridad obligatoria en todos los órganos públicos y privados, con independencia de su composición"]'::jsonb,1,'Art. 3 LO 3/2007','Supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, especialmente por maternidad, obligaciones familiares y estado civil.',null),
('aux-age:16-88e6e8ef9d','aux-age',16,'Se considera discriminación directa por razón de sexo la situación en que una persona:','["Recibe una medida de acción positiva destinada a corregir situaciones de desigualdad", "Es tratada igual que otra persona en una situación distinta", "Es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable", "Sufre una desventaja particular respecto de personas del otro sexo por una disposición, criterio o práctica aparentemente neutros"]'::jsonb,2,'Art. 6.1 LO 3/2007','Es la situación de quien es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable. El trato por disposición aparentemente neutra es la discriminación indirecta.',null),
('aux-age:16-f8c5ca9682','aux-age',16,'El acoso sexual es cualquier comportamiento, verbal o físico, de naturaleza sexual que:','["Se produzca fuera del lugar de trabajo", "Se repita al menos tres veces y lo denuncie la persona afectada o un tercero", "Produzca una lesión física acreditada", "Tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona"]'::jsonb,3,'Art. 7.1 LO 3/2007','Tiene el propósito o produce el efecto de atentar contra la dignidad de una persona, en particular cuando crea un entorno intimidatorio, degradante u ofensivo.',null),
('aux-age:16-13f6409233','aux-age',16,'Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:','["Discriminación directa por razón de sexo", "Discriminación indirecta por razón de sexo, salvo que la empresa acredite una justificación objetiva", "Acoso por razón de sexo", "Una infracción laboral leve"]'::jsonb,0,'Art. 8 LO 3/2007','Constituye discriminación directa por razón de sexo.',null),
('aux-age:16-33f9830858','aux-age',16,'Según la LO 3/2007, el principio de igualdad de trato y oportunidades informará la actuación de todos los Poderes Públicos con carácter:','["Excepcional", "Transversal", "Subsidiario", "Voluntario"]'::jsonb,1,'Art. 15 LO 3/2007','Informará, con carácter transversal, la actuación de todos los Poderes Públicos.',null),
('aux-age:16-13831b573b','aux-age',16,'¿Qué empresas deben elaborar y aplicar un plan de igualdad?','["Todas, cualquiera que sea su plantilla", "Las de más de 250 trabajadores", "Las de cincuenta o más trabajadores", "Solo las empresas públicas y las que contraten con la Administración, cualquiera que sea su plantilla"]'::jsonb,2,'Art. 45.2 LO 3/2007','Las empresas de cincuenta o más trabajadores.',null),
('aux-age:16-ed8434fdd9','aux-age',16,'Según la LO 3/2007, hay composición equilibrada cuando las personas de cada sexo:','["Son exactamente el 50 %", "No superan el 70 % ni son menos del 30 %", "No superan el 55 % ni son menos del 45 %", "No superan el 60 % ni son menos del 40 %"]'::jsonb,3,'Disp. adicional 1.ª LO 3/2007','Las personas de cada sexo no superan el sesenta por ciento ni son menos del cuarenta por ciento.',null),
('aux-age:16-29a0f3cac1','aux-age',16,'La LO 1/2004 actúa contra la violencia que se ejerce sobre las mujeres por parte de quienes sean o hayan sido sus cónyuges o parejas:','["Aun sin convivencia", "Solo si conviven", "Solo si están casados", "Solo si hay hijos en común"]'::jsonb,0,'Art. 1.1 LO 1/2004','Comprende a quienes sean o hayan sido sus cónyuges o hayan estado ligados por relaciones similares de afectividad, aun sin convivencia.',null),
('aux-age:16-cf70da2d5e','aux-age',16,'Según la LO 1/2004, la violencia de género comprende:','["Solo la violencia física que cause lesiones", "Todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad", "Todo acto de violencia física, incluidas las agresiones a la libertad sexual, pero no la violencia psicológica, las amenazas ni las coacciones, que se rigen por el Código Penal", "Solo la violencia física ejercida en el domicilio familiar que cause lesiones acreditadas por un médico, excluidas las amenazas, las coacciones y la violencia psicológica"]'::jsonb,1,'Art. 1.3 LO 1/2004','Comprende todo acto de violencia física y psicológica, incluidas agresiones a la libertad sexual, amenazas, coacciones o privación arbitraria de libertad.',null),
('aux-age:16-fd95a972f9','aux-age',16,'¿Cuál de estos derechos tiene la trabajadora víctima de violencia de género?','["Una indemnización automática a cargo de su empresa", "El ascenso de categoría", "La reducción o reordenación de su tiempo de trabajo, la movilidad geográfica o la suspensión con reserva de puesto", "La reducción de jornada sin disminución proporcional del salario, la movilidad geográfica y el cambio de empresa dentro del grupo"]'::jsonb,2,'Art. 21.1 LO 1/2004','Tiene derecho, entre otros, a la reducción o reordenación de jornada, la movilidad geográfica, el cambio de centro, la suspensión con reserva de puesto y la extinción del contrato.',null),
('aux-age:16-40aede0150','aux-age',16,'Para acreditar la situación de violencia de género y acceder a los derechos laborales sirve, entre otros:','["Una declaración jurada de un vecino o familiar", "El certificado de empadronamiento junto con una declaración jurada de la propia trabajadora", "Un parte de lesiones expedido por una clínica privada sin intervención judicial ni fiscal", "La orden de protección o el informe del Ministerio Fiscal"]'::jsonb,3,'Art. 23 LO 1/2004','Se acredita con sentencia condenatoria, orden de protección, informe del Ministerio Fiscal, informe de los servicios sociales o especializados u otro título previsto.',null),
('aux-age:16-befb79b483','aux-age',16,'La funcionaria víctima de violencia de género tiene derecho, entre otros, a:','["La excedencia, la reducción o reordenación de su tiempo de trabajo y la movilidad geográfica", "El cambio automático de cuerpo o escala", "Un permiso retribuido de un año, la reducción de jornada sin merma de retribuciones y la jubilación anticipada voluntaria", "La jubilación anticipada sin reducción de la pensión y un permiso retribuido de un año completo"]'::jsonb,0,'Art. 24 LO 1/2004','Tiene derecho a la reducción o reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia.',null),
('aux-age:16-03e2b4e054','aux-age',16,'¿Qué órganos judiciales creó la LO 1/2004?','["Las Audiencias de Familia", "Los Juzgados de Violencia sobre la Mujer", "Los Tribunales de Igualdad", "Las Salas de Género del Tribunal Supremo"]'::jsonb,1,'Art. 43 LO 1/2004','Creó los Juzgados de Violencia sobre la Mujer, añadiendo el art. 87 bis a la LOPJ.',null),
('aux-age:16-66647763e3','aux-age',16,'El Fiscal contra la Violencia sobre la Mujer:','["Es elegido por el Congreso por mayoría de tres quintos", "Depende orgánicamente del Ministerio de Igualdad, que lo nombra a propuesta del Consejo de Ministros", "Es nombrado, oído el Consejo Fiscal, como delegado, con categoría de Fiscal de Sala", "Es un fiscal de cada provincia"]'::jsonb,2,'Art. 70 LO 1/2004','Se nombra, oído el Consejo Fiscal, como delegado, con categoría de Fiscal de Sala.',null),
('aux-age:16-472fe1bd9d','aux-age',16,'Según la Ley 4/2023, ¿a partir de qué edad puede una persona solicitar por sí misma la rectificación registral de la mención relativa al sexo?','["Doce años", "Catorce años", "Dieciocho años", "Dieciséis años"]'::jsonb,3,'Art. 43 Ley 4/2023','Las personas de nacionalidad española mayores de dieciséis años pueden solicitarla por sí mismas.',null),
('aux-age:16-3c469bcc39','aux-age',16,'Según la Ley 4/2023, las personas mayores de 14 y menores de 16 años pueden solicitar la rectificación registral del sexo:','["Por sí mismas, asistidas por sus representantes legales", "Por sí mismas, sin necesidad de asistencia de sus representantes legales", "Solo mediante autorización judicial previa", "Solo a través de sus representantes legales, con informe médico"]'::jsonb,0,'Art. 43 Ley 4/2023','Pueden presentar la solicitud por sí mismas, asistidas por sus representantes legales.',null),
('aux-age:16-7d07ed611e','aux-age',16,'Según la Ley 4/2023, las personas mayores de 12 y menores de 14 años:','["Pueden solicitar la rectificación por sí mismas, asistidas por sus representantes legales", "Pueden solicitar la autorización judicial para la modificación", "No pueden solicitar ni la rectificación ni la autorización judicial hasta cumplir los catorce años", "Solo pueden cambiar el nombre"]'::jsonb,1,'Art. 43 Ley 4/2023','Pueden solicitar la autorización judicial para la modificación de la mención registral del sexo.',null),
('aux-age:11-98b8c58cc3','aux-age',11,'¿Qué sistema de identificación electrónica menciona expresamente el art. 9.2 de la Ley 39/2015?','["Los certificados electrónicos cualificados de firma electrónica", "El reconocimiento facial mediante la cámara del dispositivo", "La huella dactilar registrada en el DNI", "El número de teléfono móvil asociado a una cuenta bancaria del interesado"]'::jsonb,0,'Art. 9.2 Ley 39/2015','Menciona los certificados cualificados de firma, los de sello electrónico y cualquier otro sistema que las Administraciones consideren válido.',null),
('aux-age:11-3362868f45','aux-age',11,'Con carácter general, para realizar cualquier actuación en el procedimiento, los interesados deben:','["Firmar electrónicamente todo", "Acreditar previamente su identidad", "Presentarse en persona", "Aportar un certificado de antecedentes"]'::jsonb,1,'Art. 11.1 Ley 39/2015','Basta con que acrediten previamente su identidad.',null),
('aux-age:11-a2d3868dab','aux-age',11,'¿Para cuál de estas actuaciones exige la Ley 39/2015 el uso de la firma?','["Consultar el estado de un expediente", "Pedir información general", "Interponer recursos", "Solicitar cita previa"]'::jsonb,2,'Art. 11.2 Ley 39/2015','Se exige firma para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos.',null),
('aux-age:20-0fc9ddb9a2','aux-age',20,'Las Administraciones deben asistir en el uso de medios electrónicos a:','["Las empresas y demás personas jurídicas", "Los empleados públicos, para los trámites relacionados con su condición de tales", "Las entidades sin personalidad jurídica que carezcan de medios electrónicos propios", "Las personas físicas que no estén obligadas a relacionarse electrónicamente"]'::jsonb,3,'Art. 12.2 Ley 39/2015','Deben asistir a las personas físicas no obligadas, especialmente en identificación y firma, presentación de solicitudes y obtención de copias auténticas.',null),
('aux-age:20-d47a0c4fd9','aux-age',20,'Las personas físicas, ¿pueden elegir si se comunican con las Administraciones por medios electrónicos?','["Sí, en todo momento, salvo que estén obligadas", "No, siempre deben usar medios electrónicos", "No, siempre deben ir en persona", "Solo si son mayores de 65 años"]'::jsonb,0,'Art. 14.1 Ley 39/2015','Pueden elegir en todo momento, salvo que estén obligadas a relacionarse electrónicamente.',null),
('aux-age:20-5a8ea4920c','aux-age',20,'¿Cuál de los siguientes NO está obligado, con carácter general, a relacionarse electrónicamente con las Administraciones?','["Una persona jurídica", "Una persona física que actúa en su propio nombre", "Una entidad sin personalidad jurídica", "Un empleado público en trámites por razón de su condición"]'::jsonb,1,'Art. 14.2 Ley 39/2015','Están obligados las personas jurídicas, las entidades sin personalidad, los profesionales con colegiación obligatoria, los representantes de obligados y los empleados públicos en esos trámites.',null),
('aux-age:20-c03bad457d','aux-age',20,'Las personas tienen derecho a comunicarse con las Administraciones a través de:','["Un número de WhatsApp oficial de cada organismo", "Su correo electrónico personal, que tiene la misma validez que el registro", "Un Punto de Acceso General electrónico", "Los perfiles oficiales en redes sociales"]'::jsonb,2,'Art. 13 a) Ley 39/2015','Tienen derecho a comunicarse a través de un Punto de Acceso General electrónico de la Administración.',null),
('aux-age:20-d2ffe010c1','aux-age',20,'La sede electrónica es:','["Un edificio de la Administración donde se atiende al público", "Un programa informático de gestión", "La dirección de correo electrónico oficial de un organismo público, a través de la cual se presentan escritos con plena validez jurídica", "Una dirección electrónica disponible a través de redes de telecomunicaciones cuya titularidad corresponde a una Administración"]'::jsonb,3,'Art. 38.1 Ley 40/2015','Es una dirección electrónica, disponible para los ciudadanos a través de redes de telecomunicaciones, cuya titularidad corresponde a una Administración u organismo público.',null),
('aux-age:20-296ff0e67e','aux-age',20,'El portal de internet de una Administración es:','["El punto de acceso electrónico que permite acceder a la información publicada y, en su caso, a la sede electrónica", "Lo mismo que la sede electrónica, con la misma responsabilidad sobre la integridad y actualización de la información y los servicios", "Un registro electrónico general en el que se presentan escritos dirigidos a cualquier órgano de esa Administración o de otras", "Un tablón de anuncios físico"]'::jsonb,0,'Art. 39 Ley 40/2015','Es el punto de acceso electrónico de titularidad pública que permite acceder a la información publicada y, en su caso, a la sede electrónica.',null),
('aux-age:20-e9200e17a4','aux-age',20,'Se entiende por actuación administrativa automatizada la realizada íntegramente por medios electrónicos y:','["En la que un empleado público valide y firme cada acto con su certificado personal", "En la que no haya intervenido de forma directa un empleado público", "En la que intervenga un empleado público solo en la fase de notificación", "Que se publique en la sede electrónica"]'::jsonb,1,'Art. 41.1 Ley 40/2015','Es la realizada íntegramente por medios electrónicos en un procedimiento y sin intervención directa de un empleado público.',null),
('aux-age:19-36a81e958c','aux-age',19,'Según la Ley 39/2015, cada Administración dispondrá de:','["Un Registro Electrónico General", "Un registro en papel por cada órgano", "Un registro único estatal", "Ningún registro propio"]'::jsonb,0,'Art. 16.1 Ley 39/2015','Cada Administración dispondrá de un Registro Electrónico General.',null),
('aux-age:19-fd578123a4','aux-age',19,'¿Dónde NO se pueden presentar documentos dirigidos a las Administraciones según el art. 16.4 de la Ley 39/2015?','["En las oficinas de Correos", "En las representaciones diplomáticas u oficinas consulares", "En las oficinas de asistencia en materia de registros", "En cualquier comercio colaborador"]'::jsonb,3,'Art. 16.4 Ley 39/2015','Se pueden presentar en los registros electrónicos, en Correos, en representaciones diplomáticas u oficinas consulares, en las oficinas de asistencia en materia de registros y donde establezcan las disposiciones vigentes.',null),
('aux-age:19-b2788c3a1a','aux-age',19,'Cada Administración debe mantener, para los documentos electrónicos de procedimientos finalizados:','["Un archivo en papel", "Un archivo electrónico único", "Un archivo por cada funcionario", "Copias en el BOE"]'::jsonb,1,'Art. 17.1 Ley 39/2015','Debe mantener un archivo electrónico único de los documentos electrónicos de procedimientos finalizados.',null),
('aux-age:19-8dbe44a3e0','aux-age',19,'¿Cuál es uno de los requisitos de validez de los documentos administrativos electrónicos?','["Estar impresos y llevar el sello del órgano que los emite", "Llevar firma manuscrita escaneada y el sello del órgano emisor en cada página", "Incorporar la fecha de emisión y los metadatos mínimos exigidos", "Incorporar la fecha de emisión y estar disponibles en papel, con la firma original del titular del órgano"]'::jsonb,2,'Art. 26.2 Ley 39/2015','Deben contener información en soporte electrónico, datos de identificación, firmas electrónicas, fecha de emisión y metadatos mínimos.',null),
('aux-age:19-8b4f0e637b','aux-age',19,'Los interesados, ¿están obligados a aportar documentos elaborados por cualquier Administración?','["Sí, siempre", "Sí, si son originales", "Solo en papel", "No"]'::jsonb,3,'Art. 28.2 Ley 39/2015','No están obligados a aportar documentos elaborados por cualquier Administración; esta puede consultarlos salvo oposición del interesado.',null),
('aux-age:11-7db9ce7fa8','aux-age',11,'La presentación de un documento en el registro electrónico en un día inhábil se entiende realizada:','["En la primera hora del primer día hábil siguiente", "En la última hora del último día hábil anterior al de la presentación", "El mismo día inhábil, a la hora en que se presentó", "A las 9 horas del tercer día hábil siguiente"]'::jsonb,0,'Art. 31.2 b) Ley 39/2015','Se entiende realizada en la primera hora del primer día hábil siguiente, salvo que una norma permita la recepción en día inhábil.',null),
('aux-age:11-79358d3590','aux-age',11,'Cuando en una solicitud figuren varios interesados, las actuaciones se efectuarán:','["Con el que elija la Administración en cada trámite, notificando a los demás", "Con todos a la vez, de forma obligatoria y en igualdad de condiciones, salvo renuncia expresa de alguno de ellos por escrito", "Con el de mayor edad, salvo que todos hayan señalado expresamente a otro, y en su defecto con todos los interesados a la vez", "Con el representante o interesado que expresamente hayan señalado y, en su defecto, con el que figure en primer término"]'::jsonb,3,'Art. 7 Ley 39/2015','En defecto de designación, con el que figure en primer término.',null),
('aux-age:11-66423e7841','aux-age',11,'Se podrá prescindir del trámite de audiencia cuando:','["Se trate de un procedimiento sancionador o de responsabilidad patrimonial", "El interesado sea una persona jurídica obligada a relacionarse electrónicamente", "No figuren ni sean tenidos en cuenta otros hechos, alegaciones o pruebas que los aducidos por el interesado", "Lo acuerde motivadamente el instructor por razones de urgencia, aunque se tengan en cuenta hechos nuevos no aportados por el interesado"]'::jsonb,2,'Art. 82.4 Ley 39/2015','Si solo se valora lo aportado por el interesado, la audiencia puede omitirse.',null),
('aux-age:11-2a7a7d652f','aux-age',11,'Si el recurso de alzada se interpone ante el órgano que dictó el acto, este deberá remitirlo al competente:','["En el plazo de un mes, con su informe y una copia completa y ordenada del expediente", "En el plazo de diez días, con su informe y una copia completa y ordenada del expediente", "En el plazo de quince días, sin necesidad de informe", "En el plazo de tres días, con el expediente original"]'::jsonb,1,'Art. 121.2 Ley 39/2015','Debe remitirlo en 10 días con informe y copia del expediente.',null),
('aux-age:1-adafe9ba5f','aux-age',1,'Según el art. 17.1, toda persona tiene derecho a:','["Una vivienda en propiedad", "La asistencia jurídica gratuita en cualquier caso", "La libertad y a la seguridad", "Un trabajo remunerado"]'::jsonb,2,'Art. 17.1 CE','Toda persona tiene derecho a la libertad y a la seguridad.',null),
('aux-age:11-aa84b10d6c','aux-age',11,'A los interesados que no cumplan lo dispuesto en un trámite:','["Se les tendrá por desistidos de su solicitud y se archivará el procedimiento sin más trámite", "Se les podrá declarar decaídos en su derecho al trámite correspondiente", "Se les impondrá una multa coercitiva", "Se declara la caducidad"]'::jsonb,1,'Art. 73.3 Ley 39/2015','Se admitirá su actuación si se produce antes o dentro del día en que se notifique la resolución que tenga por transcurrido el plazo.',null),
('aux-age:11-00a7a0d049','aux-age',11,'Según el art. 98.1, tampoco son inmediatamente ejecutivos los actos:','["Que sean favorables al interesado", "Que necesiten aprobación o autorización superior", "Que pongan fin a la vía administrativa y no hayan sido recurridos", "Que hayan sido notificados con indicación de los recursos procedentes"]'::jsonb,1,'Art. 98.1 d) Ley 39/2015','Tampoco cuando se acuerde su suspensión o una disposición establezca lo contrario.',null),
('aux-age:1-12d00e3f72','aux-age',1,'Según el art. 31.2, la programación y ejecución del gasto público responden a los criterios de:','["Rentabilidad y beneficio", "Discrecionalidad política", "Prioridad territorial", "Eficiencia y economía"]'::jsonb,3,'Art. 31.2 CE','El gasto público realizará una asignación equitativa de los recursos públicos, y su programación y ejecución responderán a los criterios de eficiencia y economía.',null),
('aux-age:11-42454d94cc','aux-age',11,'La estimación por silencio administrativo tiene a todos los efectos la consideración de:','["Acto administrativo finalizador del procedimiento", "Acto de trámite cualificado, recurrible en alzada", "Propuesta de resolución vinculante para el órgano competente", "Mera ficción sin efectos hasta que se dicte resolución expresa"]'::jsonb,0,'Art. 24.2 Ley 39/2015','La desestimación por silencio solo permite interponer el recurso que proceda.',null),
('aux-age:11-029cb824de','aux-age',11,'Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente original, se pondrán de manifiesto a los interesados para alegaciones en un plazo:','["De un mes, prorrogable por otro mes a petición del interesado", "No inferior a diez días ni superior a quince", "No inferior a cinco días ni superior a diez", "De veinte días hábiles, prorrogable por otros diez"]'::jsonb,1,'Art. 118.1 Ley 39/2015','El plazo es de 10 a 15 días.',null),
('aux-age:11-e514d13d74','aux-age',11,'Es un derecho del interesado en el procedimiento:','["Obtener una resolución favorable si la Administración no resuelve en plazo", "Conocer en cualquier momento el estado de la tramitación de los procedimientos en los que sea interesado", "Elegir al instructor del procedimiento", "Conocer en cualquier momento el estado de tramitación de cualquier procedimiento de la Administración, aunque no tenga la condición de interesado"]'::jsonb,1,'Art. 53.1 a) Ley 39/2015','También el sentido del silencio, el órgano competente y obtener copia de los documentos.',null),
('aux-age:11-ad1acfb0fb','aux-age',11,'La declaración responsable es el documento por el que el interesado manifiesta, bajo su responsabilidad:','["Que acepta cualquier sanción que se derive de la falsedad de los datos aportados", "Que cumple los requisitos de la normativa vigente, dispone de la documentación que lo acredita y la pondrá a disposición de la Administración cuando se le requiera", "Que cumple los requisitos de la normativa vigente y aporta en ese momento toda la documentación que lo acredita, sin que la Administración pueda requerírsela después", "Que pone en conocimiento de la Administración sus datos identificativos"]'::jsonb,1,'Art. 69.1 Ley 39/2015','Definición legal de la declaración responsable.',null),
('aux-age:1-79817c1ea5','aux-age',1,'Según el art. 18.4, la ley limitará el uso de:','["El derecho de reunión y manifestación", "Los medios de comunicación social de titularidad pública", "La informática, para garantizar el honor y la intimidad", "Las armas de fuego, para garantizar la seguridad ciudadana"]'::jsonb,2,'Art. 18.4 CE','La ley limitará el uso de la informática para garantizar el honor y la intimidad personal y familiar.',null),
('aux-age:11-08cb26eef6','aux-age',11,'¿Pueden revisarse de oficio las disposiciones administrativas nulas del art. 47.2?','["Sí, en cualquier momento y sin necesidad de dictamen del órgano consultivo", "No, la revisión de oficio solo alcanza a los actos, no a las disposiciones", "Sí, previo dictamen favorable del Consejo de Estado u órgano consultivo autonómico equivalente", "Sí, previo dictamen no vinculante del Consejo de Estado u órgano consultivo equivalente, y a instancia del interesado"]'::jsonb,2,'Art. 106.2 Ley 39/2015','Las Administraciones pueden declarar de oficio la nulidad de disposiciones del art. 47.2 previo dictamen favorable.',null),
('aux-age:11-d956a5ee49','aux-age',11,'En ningún caso podrá imponerse a los administrados una obligación pecuniaria que:','["No se haya notificado con al menos quince días de antelación", "Supere los 3.000 euros sin autorización judicial previa y expresa", "No estuviese establecida con arreglo a una norma de rango legal", "No estuviese establecida en una norma de rango reglamentario aprobada por el Consejo de Gobierno o el Consejo de Ministros"]'::jsonb,2,'Art. 101.2 Ley 39/2015','Las obligaciones pecuniarias requieren base en una norma de rango legal.',null),
('aux-age:11-470a30d468','aux-age',11,'La petición razonada de iniciación:','["No vincula al órgano competente, que deberá comunicar los motivos por los que, en su caso, no inicia", "Equivale a una denuncia y obliga a iniciar el procedimiento", "Solo puede formularla un ciudadano afectado", "Vincula al órgano competente para iniciar, que solo puede rechazarla si concurre una causa de inadmisión prevista en la ley"]'::jsonb,0,'Art. 61.2 Ley 39/2015','No es vinculante, pero hay que comunicar los motivos de no iniciar.',null),
('aux-age:11-0dd83672d9','aux-age',11,'La multa coercitiva:','["Requiere autorización judicial previa en todo caso", "Es independiente de las sanciones que puedan imponerse y compatible con ellas", "Sustituye a la sanción que corresponda", "Es incompatible con las sanciones, de modo que si se impone una multa coercitiva no puede imponerse sanción por los mismos hechos"]'::jsonb,1,'Art. 103.2 Ley 39/2015','La multa coercitiva es independiente de las sanciones y compatible con ellas.',null),
('aux-age:11-3c1b1f3060','aux-age',11,'Son nulas de pleno derecho las disposiciones administrativas que:','["Establezcan la retroactividad de disposiciones sancionadoras no favorables o restrictivas de derechos individuales", "Establezcan la retroactividad de disposiciones favorables o ampliatorias de derechos individuales", "Tengan carácter organizativo y no se hayan sometido previamente al trámite de información pública ni a consulta de los interesados afectados", "Se aprueben por el Consejo de Ministros"]'::jsonb,0,'Art. 47.2 Ley 39/2015','También las que vulneren la Constitución, las leyes o disposiciones de rango superior o regulen materias reservadas a la ley.',null),
('aux-age:11-e2ad00c15e','aux-age',11,'No podrá acordarse la caducidad del procedimiento por la simple inactividad del interesado en la cumplimentación de trámites:','["En ningún caso, cualquiera que sea el trámite omitido", "Siempre que no sean indispensables para dictar resolución", "Si el interesado es persona jurídica obligada a relacionarse electrónicamente", "Aunque sean indispensables para dictar resolución, si ha transcurrido el plazo"]'::jsonb,1,'Art. 95.2 Ley 39/2015','La inactividad en trámites no indispensables no da lugar a caducidad.',null),
('aux-age:11-10c78e0a77','aux-age',11,'También es causa del recurso extraordinario de revisión que la resolución se haya dictado como consecuencia de:','["Prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible declarada en sentencia judicial firme", "Un cambio de criterio de la Administración posterior a la resolución", "Una denuncia de un tercero por prevaricación o cohecho, aunque todavía no haya recaído sentencia judicial firme", "Un error de calificación del recurso"]'::jsonb,0,'Art. 125.1 d) Ley 39/2015','Exige que la conducta se haya declarado en sentencia judicial firme.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-age:1-a8a0176cc8','aux-age',1,'El ejercicio de la libertad de expresión e información:','["Requiere autorización previa en los medios de titularidad pública", "No puede restringirse mediante ningún tipo de censura previa", "Puede someterse a censura previa en estados de alarma, excepción y sitio, por ley orgánica", "Solo se ejerce por periodistas"]'::jsonb,1,'Art. 20.2 CE','El ejercicio de estos derechos no puede restringirse mediante ningún tipo de censura previa.',null),
('aux-age:11-41c4653406','aux-age',11,'Los titulares de las unidades administrativas que tengan a su cargo la resolución o despacho de los asuntos:','["Serán responsables directos de su tramitación y adoptarán las medidas para remover los obstáculos que retrasen el ejercicio de los derechos de los interesados", "No tienen responsabilidad directa sobre la tramitación, que corresponde en exclusiva al titular del órgano superior jerárquico del que dependan", "Responden solo ante los tribunales penales", "Solo son responsables si lo solicita el interesado"]'::jsonb,0,'Art. 20.1 Ley 39/2015','Son responsables directos de la tramitación.',null),
('aux-age:11-03ccd5300e','aux-age',11,'La Administración instructora deberá traducir al castellano:','["Los documentos que deban surtir efecto fuera del territorio de la Comunidad y los dirigidos a interesados que lo soliciten expresamente", "Todos los documentos redactados en lengua cooficial, sin excepción", "Solo los documentos dirigidos a interesados que residan fuera de la Comunidad Autónoma", "Los documentos que deban surtir efecto en la Comunidad, y los dirigidos a interesados que no conozcan la lengua cooficial aunque no lo pidan"]'::jsonb,0,'Art. 15.3 Ley 39/2015','Se traducen los que deban surtir efecto fuera de la Comunidad y los que pidan los interesados.',null),
('aux-age:11-edf5ad817e','aux-age',11,'Tienen la consideración de Administraciones Públicas según el art. 2.3:','["La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local y los organismos públicos y entidades de derecho público del art. 2.2 a)", "La AGE, las Administraciones de las CCAA y las Entidades Locales, pero no los organismos públicos vinculados o dependientes", "La AGE, las Administraciones de las CCAA, las Entidades de la Administración Local, las universidades privadas, los colegios profesionales y todas las empresas con capital público", "Los colegios profesionales en todo caso"]'::jsonb,0,'Art. 2.3 Ley 39/2015','Son AAPP la AGE, las CCAA, las Entidades Locales y los organismos y entidades de derecho público vinculados o dependientes.',null),
('aux-age:11-cc5dd58213','aux-age',11,'Según su art. 1.1, la Ley 39/2015 regula, entre otros aspectos:','["El régimen jurídico de los funcionarios y del personal laboral al servicio de las Administraciones", "La jurisdicción contencioso-administrativa y sus procedimientos, así como el régimen de los recursos judiciales contra los actos de las Administraciones", "Los requisitos de validez y eficacia de los actos administrativos y el procedimiento administrativo común a todas las Administraciones", "La organización interna de la AGE y de su sector público institucional, y el régimen de los órganos colegiados de todas las Administraciones"]'::jsonb,2,'Art. 1.1 Ley 39/2015','Incluye el procedimiento sancionador, el de responsabilidad patrimonial y los principios de iniciativa legislativa y potestad reglamentaria.',null),
('aux-age:11-2c3a257b48','aux-age',11,'En los procedimientos sancionadores, el presunto responsable tiene derecho, además:','["A elegir la sanción entre las previstas para la infracción", "A no declarar contra sí mismo, pero no a la presunción de inocencia, que es exclusiva del proceso penal", "A que se le notifique la sanción", "A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario"]'::jsonb,3,'Art. 53.2 b) Ley 39/2015','Es la presunción de inocencia en el ámbito sancionador.',null),
('aux-age:11-4c23191d9a','aux-age',11,'La comparecencia de las personas ante las oficinas públicas solo será obligatoria cuando:','["El interesado tenga más de 65 años", "Lo establezca una circular o instrucción interna del órgano", "Lo decida motivadamente el instructor del procedimiento", "Así esté previsto en una norma con rango de ley"]'::jsonb,3,'Art. 19.1 Ley 39/2015','Solo es obligatoria si una norma con rango de ley lo prevé.',null),
('aux-age:11-0e944b4f69','aux-age',11,'Podrá prescindirse de los trámites de consulta, audiencia e información públicas en el caso de normas:','["Tributarias o sancionadoras, o cuando concurran razones graves de interés público", "Que afecten a derechos de los ciudadanos, o cuando concurran razones de urgencia", "Sancionadoras y de organización del procedimiento", "Presupuestarias u organizativas, o cuando concurran razones graves de interés público"]'::jsonb,3,'Art. 133.4 Ley 39/2015','Excepción prevista para normas presupuestarias u organizativas o razones graves de interés público.',null),
('aux-age:1-2a22339684','aux-age',1,'El secreto de las comunicaciones puede levantarse:','["Por decisión del Gobierno", "Mediante resolución judicial", "Por orden policial", "Nunca en ningún caso"]'::jsonb,1,'Art. 18.3 CE','Se garantiza el secreto de las comunicaciones, salvo resolución judicial.',null),
('aux-age:11-0d386cfd82','aux-age',11,'Las Administraciones pueden imponer multas coercitivas:','["Solo los Ayuntamientos, en el ejercicio de su potestad sancionadora", "Solo en materia tributaria", "Cuando así lo autoricen las leyes, y en la forma y cuantía que estas determinen", "Cuando lo autorice un reglamento, en la forma y cuantía que determine el órgano que ordena la ejecución"]'::jsonb,2,'Art. 103.1 Ley 39/2015','Requieren autorización legal y se reiteran por lapsos de tiempo suficientes para cumplir lo ordenado.',null),
('aux-age:11-7a2ea0f35c','aux-age',11,'La efectividad de las reducciones por reconocimiento o pago voluntario está condicionada a:','["El desistimiento o renuncia de cualquier acción o recurso en vía administrativa contra la sanción", "Que la sanción sea inferior a 300 euros", "El desistimiento o renuncia de cualquier acción o recurso, tanto en vía administrativa como contencioso-administrativa", "La conformidad de la víctima o del denunciante y la renuncia expresa a la vía contencioso-administrativa"]'::jsonb,0,'Art. 85.3 Ley 39/2015','El infractor debe desistir o renunciar a recursos administrativos.',null),
('aux-age:19-6b61dba53c','aux-age',19,'¿Quién determina los órganos que tienen atribuidas las competencias de expedición de copias auténticas?','["Cada Administración Pública", "El Consejo de Estado", "El Ministerio de Justicia para todas", "Los notarios"]'::jsonb,0,'Art. 27.1 Ley 39/2015','Cada Administración determina los órganos competentes para expedir copias auténticas.',null),
('aux-age:11-baddeb81e5','aux-age',11,'Si para la ejecución forzosa fuese necesario entrar en el domicilio del afectado, se requiere:','["Su consentimiento o, en su defecto, la oportuna autorización judicial", "Basta la resolución administrativa que ordena la ejecución, notificada al afectado", "Autorización del Delegado del Gobierno o, en su defecto, del alcalde", "Su consentimiento o, en su defecto, autorización del órgano superior jerárquico del que ordenó la ejecución"]'::jsonb,0,'Art. 100.3 Ley 39/2015','Se necesita el consentimiento del afectado o autorización judicial.',null),
('aux-age:11-81617ce736','aux-age',11,'La resolución de un recurso será congruente con las peticiones del recurrente:','["Salvo en materia de personal, en que puede agravarse su situación inicial", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Solo si el recurrente lo autoriza expresamente", "Sin que en ningún caso pueda agravarse su situación inicial"]'::jsonb,3,'Art. 119.3 Ley 39/2015','Es la prohibición de la reformatio in peius.',null),
('aux-age:11-bff87d1e25','aux-age',11,'Con carácter previo a la elaboración de un proyecto de ley o reglamento, se sustanciará una consulta pública a través del portal web sobre:','["El coste de la publicación de la norma en el BOE", "La opinión del Consejo de Estado y del órgano proponente", "Los problemas que se pretenden solucionar, la necesidad y oportunidad, los objetivos y las posibles soluciones alternativas", "El texto articulado completo del proyecto, el informe de impacto normativo, la memoria económica y el dictamen del Consejo de Estado"]'::jsonb,2,'Art. 133.1 Ley 39/2015','Son los cuatro aspectos de la consulta pública previa.',null),
('aux-age:11-f116ce53f9','aux-age',11,'Si el acto no es expreso, el recurso de alzada podrá interponerse:','["En el plazo de un mes desde el día siguiente a aquel en que se produzcan los efectos del silencio", "En el plazo de tres meses desde la presentación de la solicitud", "En el plazo de dos meses", "En cualquier momento a partir del día siguiente a aquel en que se produzcan los efectos del silencio"]'::jsonb,3,'Art. 122.1 Ley 39/2015','Contra actos presuntos, en cualquier momento desde que se producen los efectos del silencio.',null),
('aux-age:11-bb5dc1ec6c','aux-age',11,'El registro electrónico de cada Administración permitirá la presentación de documentos:','["Solo en horario de oficina de cada órgano", "Solo de lunes a viernes, a cualquier hora", "Solo en días hábiles, durante las veinticuatro horas", "Todos los días del año durante las veinticuatro horas"]'::jsonb,3,'Art. 31.2 Ley 39/2015','El registro electrónico funciona 24 horas los 365 días.',null),
('aux-age:11-17fa493b79','aux-age',11,'Interpuesto un recurso de reposición, no se podrá interponer recurso contencioso-administrativo hasta que:','["Sea resuelto expresamente o se haya producido su desestimación presunta", "Pasen seis meses desde su interposición, aunque se haya resuelto antes", "Sea resuelto expresamente, sin que baste la desestimación presunta", "Lo autorice el órgano que dictó el acto"]'::jsonb,0,'Art. 123.2 Ley 39/2015','Hay que esperar a la resolución expresa o la desestimación presunta.',null),
('aux-age:11-4e5df2370a','aux-age',11,'El silencio será desestimatorio, entre otros, en los procedimientos relativos a:','["Licencias de obra menor", "Inscripción en registros públicos", "Las solicitudes de subvenciones de concurrencia competitiva, sin excepción", "El ejercicio del derecho de petición del art. 29 de la Constitución"]'::jsonb,3,'Art. 24.1 Ley 39/2015','También en los de dominio o servicio público, medio ambiente, responsabilidad patrimonial, impugnación de actos y revisión de oficio a solicitud.',null),
('aux-age:1-d4ddf403c2','aux-age',1,'Las demás lenguas españolas distintas del castellano:','["Solo son oficiales en el ámbito educativo de cada Comunidad Autónoma", "Son también oficiales en las respectivas Comunidades Autónomas de acuerdo con sus Estatutos", "Son oficiales en todo el territorio nacional, junto al castellano", "Son oficiales en las respectivas Comunidades Autónomas, pero solo cuando lo establezca una ley orgánica estatal"]'::jsonb,1,'Art. 3.2 CE','Son oficiales en sus Comunidades Autónomas de acuerdo con sus Estatutos.',null),
('aux-age:1-05134f9c87','aux-age',1,'Mediante ley podrán regularse los deberes de los ciudadanos en los casos de:','["Cambio de Gobierno o estado de alarma", "Grave riesgo, catástrofe o calamidad pública", "Huelga general", "Crisis económica grave declarada por el Gobierno"]'::jsonb,1,'Art. 30.4 CE','Podrán regularse los deberes de los ciudadanos en los casos de grave riesgo, catástrofe o calamidad pública.',null),
('aux-age:11-7405739fea','aux-age',11,'La representación podrá acreditarse mediante:','["Únicamente escritura notarial de apoderamiento, que deberá presentarse en papel en el registro del órgano competente en cada uno de los procedimientos en que se actúe", "Únicamente comparecencia personal ante el órgano competente", "Cualquier medio válido en Derecho que deje constancia fidedigna, comparecencia personal o electrónica, o inscripción en el registro de apoderamientos", "Cualquier medio, incluida una llamada telefónica o un correo electrónico sin firma, siempre que el funcionario que lo recibe deje constancia escrita en el expediente"]'::jsonb,2,'Art. 5.4 Ley 39/2015','Se admite cualquier medio válido en Derecho que deje constancia fidedigna.',null),
('aux-age:11-29dd9f5b71','aux-age',11,'También pone fin a la vía administrativa:','["El acuerdo de iniciación del procedimiento sancionador o de responsabilidad", "La providencia de apertura del periodo de prueba", "El informe preceptivo y vinculante emitido por un órgano consultivo", "La resolución de los procedimientos de responsabilidad patrimonial"]'::jsonb,3,'Art. 114.1 e) Ley 39/2015','Las resoluciones en materia de responsabilidad patrimonial ponen fin a la vía administrativa, cualquiera que sea el tipo de relación.',null),
('aux-age:11-2469752914','aux-age',11,'En la AGE, son competentes para la revisión de oficio de sus propios actos y de los dictados por los Ministros:','["El Consejo de Estado", "Los Subsecretarios", "El Presidente del Gobierno en solitario", "El Consejo de Ministros"]'::jsonb,3,'Art. 111 a) Ley 39/2015','El Consejo de Ministros revisa sus propios actos y disposiciones y los de los Ministros.',null),
('aux-age:11-943dac30cd','aux-age',11,'Los interesados podrán firmar a través de cualquier medio que permita acreditar:','["La fecha del documento y su número de registro", "Su identidad, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, pero no la integridad del documento", "La autenticidad de la expresión de su voluntad y consentimiento, y la integridad e inalterabilidad del documento"]'::jsonb,3,'Art. 10.1 Ley 39/2015','La firma debe acreditar autenticidad de la voluntad y la integridad del documento.',null),
('aux-age:1-f736590ee5','aux-age',1,'La libertad ideológica, religiosa y de culto tiene como única limitación en sus manifestaciones:','["La moral pública y las buenas costumbres, según determine la ley", "La autorización gubernativa previa", "La que fije cada confesión religiosa", "La necesaria para el mantenimiento del orden público protegido por la ley"]'::jsonb,3,'Art. 16.1 CE','Sin más limitación, en sus manifestaciones, que la necesaria para el mantenimiento del orden público protegido por la ley.',null),
('aux-age:11-24b92c5ecc','aux-age',11,'Los procedimientos caducados:','["Impiden iniciar uno nuevo", "Interrumpen la prescripción", "No interrumpirán el plazo de prescripción", "Producen por sí solos la prescripción de las acciones"]'::jsonb,2,'Art. 95.3 Ley 39/2015','La caducidad no produce por sí sola la prescripción, pero el procedimiento caducado no la interrumpe.',null),
('aux-age:1-79f3d640f0','aux-age',1,'Según el art. 16.3, ¿alguna confesión tendrá carácter estatal?','["Sí, las que reconozca una ley orgánica", "No, ninguna confesión tendrá carácter estatal", "Sí, la católica", "Las que tengan más de un millón de fieles"]'::jsonb,1,'Art. 16.3 CE','Ninguna confesión tendrá carácter estatal, aunque los poderes públicos mantendrán relaciones de cooperación con la Iglesia Católica y las demás confesiones.',null),
('aux-age:11-e7d3ea3eb3','aux-age',11,'Si el interesado actúa por medio de representante:','["Se requiere poder notarial en todo caso", "Las actuaciones se entienden siempre con el interesado, y solo se comunican al representante a título informativo", "Solo puede actuar como representante un abogado colegiado", "Las actuaciones se entenderán con el representante, salvo manifestación expresa en contrario del interesado"]'::jsonb,3,'Art. 5.1 Ley 39/2015','Se entienden con el representante salvo manifestación expresa en contrario.',null),
('aux-age:11-8d2c7da008','aux-age',11,'En los procedimientos iniciados de oficio, si el procedimiento se paraliza por causa imputable al interesado:','["Se produce la caducidad inmediata del procedimiento", "Se interrumpirá el cómputo del plazo para resolver y notificar la resolución", "Se suspenderá el cómputo del plazo, pero solo si así lo acuerda el órgano por resolución motivada notificada al interesado", "Se archiva sin más trámite y se declara la caducidad del procedimiento de forma automática"]'::jsonb,1,'Art. 25.2 Ley 39/2015','La paralización imputable al interesado interrumpe el cómputo del plazo.',null),
('aux-age:11-5b0cef05d4','aux-age',11,'En los procedimientos de responsabilidad patrimonial es preceptivo solicitar informe al servicio cuyo funcionamiento haya ocasionado la presunta lesión, que deberá emitirse en un plazo máximo de:','["Dos meses", "Quince días", "Un mes", "Diez días"]'::jsonb,3,'Art. 81.1 Ley 39/2015','El informe del servicio no puede exceder de diez días.',null),
('aux-age:11-1698d09b40','aux-age',11,'En los procedimientos sancionadores, los hechos declarados probados por resoluciones judiciales penales firmes:','["No vinculan a la Administración, que debe valorarlos libremente", "Solo vinculan si el interesado lo solicita expresamente en sus alegaciones al acuerdo de iniciación", "Vincularán a las Administraciones Públicas en los procedimientos sancionadores que substancien", "Vincularán a las Administraciones solo si la sentencia penal es condenatoria y se dictó antes de iniciarse el procedimiento"]'::jsonb,2,'Art. 77.4 Ley 39/2015','Los hechos probados en sentencia penal firme vinculan a la Administración.',null),
('aux-age:11-26431f07d2','aux-age',11,'Cuando el último día del plazo sea inhábil:','["Se entenderá vencido el último día hábil anterior", "Se entenderá prorrogado al primer día hábil siguiente", "Se entenderá prorrogado al tercer día hábil siguiente", "El plazo vence ese mismo día"]'::jsonb,1,'Art. 30.5 Ley 39/2015','Se prorroga al primer día hábil siguiente.',null),
('aux-age:11-8e5d6eea57','aux-age',11,'Cuando la condición de interesado deriva de una relación jurídica transmisible, el derecho-habiente:','["No sucede, debiendo iniciar un nuevo procedimiento en el plazo de diez días", "Solo sucede si todavía no se ha abierto la fase de instrucción", "Sucederá en tal condición cualquiera que sea el estado del procedimiento", "Sucederá en tal condición solo si el procedimiento no ha concluido la fase de audiencia a los interesados"]'::jsonb,2,'Art. 4.3 Ley 39/2015','Sucede en la condición de interesado en cualquier estado del procedimiento.',null),
('aux-age:11-a46eec5937','aux-age',11,'Una notificación que contenga el texto íntegro del acto pero omita otro requisito surte efecto:','["A los seis meses de su práctica, si el interesado no ha reclamado", "Desde que el interesado realice actuaciones que supongan el conocimiento del contenido o interponga el recurso procedente", "Inmediatamente desde su envío, aunque el interesado no haya realizado ninguna actuación ni interpuesto recurso", "Nunca"]'::jsonb,1,'Art. 40.3 Ley 39/2015','Surte efecto desde que el interesado realiza actuaciones que suponen conocer su contenido e alcance o interpone recurso.',null),
('aux-age:11-4618e0dc60','aux-age',11,'Las asociaciones y organizaciones representativas de intereses económicos y sociales son titulares de:','["Intereses individuales de cada uno de sus asociados", "Intereses legítimos colectivos en los términos que la ley reconozca", "Derechos fundamentales propios en todo procedimiento administrativo que afecte a sus asociados o al sector", "Ningún interés"]'::jsonb,1,'Art. 4.2 Ley 39/2015','Son titulares de intereses legítimos colectivos.',null),
('aux-age:1-e4706a3f1d','aux-age',1,'Los principios del Capítulo III del Título I (principios rectores de la política social y económica):','["Son directamente exigibles ante el Tribunal Constitucional en recurso de amparo", "Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos", "Informarán la legislación positiva, pero no la práctica judicial ni la actuación de la Administración", "Solo vinculan al Parlamento, y son directamente exigibles ante los tribunales ordinarios por cualquier ciudadano"]'::jsonb,1,'Art. 53.3 CE','Informarán la legislación positiva, la práctica judicial y la actuación de los poderes públicos; solo podrán alegarse ante la jurisdicción ordinaria según las leyes que los desarrollen.',null),
('aux-age:1-9c512014e5','aux-age',1,'El derecho a comunicar o recibir información, según el art. 20.1 d), se refiere a información:','["Veraz", "Oficial", "Gratuita", "Autorizada"]'::jsonb,0,'Art. 20.1 d) CE','Se reconoce el derecho a comunicar o recibir libremente información veraz por cualquier medio de difusión.',null),
('aux-age:11-53f2e72107','aux-age',11,'La resolución del procedimiento se dictará:','["Por escrito en papel, firmado por el titular del órgano", "Electrónicamente, garantizando la identidad del órgano competente y la autenticidad e integridad del documento", "Electrónicamente o en papel, a elección del órgano, garantizando solo la identidad del firmante y no la integridad del documento", "Verbalmente, con constancia en acta"]'::jsonb,1,'Art. 88.4 Ley 39/2015','La resolución se dicta electrónicamente.',null),
('aux-age:1-9f6abcee9c','aux-age',1,'Los poderes públicos garantizan el derecho de los padres a que sus hijos reciban:','["Educación en su lengua materna en todo caso", "La formación religiosa y moral que esté de acuerdo con sus propias convicciones", "La formación religiosa y moral de la confesión mayoritaria, salvo renuncia expresa de los padres o tutores", "Educación exclusivamente pública"]'::jsonb,1,'Art. 27.3 CE','Garantizan que los hijos reciban la formación religiosa y moral acorde con las convicciones de sus padres.',null),
('aux-age:11-78481d02f2','aux-age',11,'¿Quién puede acordar un período de información pública?','["El órgano al que corresponda la resolución del procedimiento, cuando su naturaleza lo requiera", "El instructor del procedimiento, a petición de cualquier interesado y siempre que lo autorice el órgano superior jerárquico", "Cualquier interesado, comunicándolo al órgano instructor, siempre que lo considere útil para su defensa", "El órgano que inició el procedimiento, solo en los procedimientos sancionadores"]'::jsonb,0,'Art. 83.1 Ley 39/2015','Lo acuerda el órgano competente para resolver.',null),
('aux-age:1-636e237c5a','aux-age',1,'El principio de legalidad del art. 25.1 establece que nadie puede ser condenado o sancionado por acciones u omisiones que:','["En el momento de dictarse la resolución no constituyan delito, falta o infracción administrativa", "En el momento de producirse no constituyan delito, falta o infracción administrativa, según la legislación vigente", "En el momento de producirse no constituyan delito según la ley penal, aunque sí infracción según un reglamento", "Sean contrarias a la moral o hayan causado alarma social"]'::jsonb,1,'Art. 25.1 CE','Nadie puede ser condenado o sancionado por acciones u omisiones que, cuando se produjeron, no constituían delito, falta o infracción administrativa.',null),
('aux-age:11-390d291bfe','aux-age',11,'Contra las disposiciones administrativas de carácter general:','["No cabe recurso en vía administrativa", "Cabe recurso de alzada", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión"]'::jsonb,0,'Art. 112.3 Ley 39/2015','Contra las disposiciones de carácter general no cabe recurso administrativo.',null),
('aux-age:19-140a1d2bef','aux-age',19,'Los documentos presentados de manera presencial ante las Administraciones deberán ser:','["Archivados en papel sin digitalizar en la oficina que los recibió", "Digitalizados por la oficina de registro, conservándose los originales en el expediente", "Enviados por correo postal al órgano competente para su digitalización en destino, junto con el resto del expediente", "Digitalizados por la oficina de asistencia en materia de registros, devolviéndose los originales al interesado"]'::jsonb,3,'Art. 16.5 Ley 39/2015','Se digitalizan y se devuelven los originales, salvo que la norma determine la custodia obligatoria.',null),
('aux-age:11-44c73190ec','aux-age',11,'Excepcionalmente, cuando al iniciar el procedimiento sancionador no existan elementos suficientes para la calificación inicial de los hechos, esta podrá realizarse en una fase posterior mediante:','["Una propuesta de resolución que deberá notificarse a los interesados", "La elaboración de un Pliego de cargos, que deberá ser notificado a los interesados", "La elaboración de un Pliego de cargos, que no se notifica a los interesados hasta la propuesta de resolución definitiva del instructor", "Un nuevo acuerdo de iniciación"]'::jsonb,1,'Art. 64.3 Ley 39/2015','Se elabora un Pliego de cargos que se notifica a los interesados.',null),
('aux-age:1-aab629c844','aux-age',1,'Según el art. 14, los españoles son iguales ante la ley sin que pueda prevalecer discriminación por razón de:','["Nacimiento, raza, sexo, religión u opinión, sin incluir otras circunstancias", "Sexo, raza, nacionalidad, ideología y orientación sexual, pero no por cualquier otra condición o circunstancia personal o social", "Nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social", "Nacimiento, raza, sexo, religión, opinión o cualquier otra condición, salvo las circunstancias económicas y sociales, que regulan las leyes"]'::jsonb,2,'Art. 14 CE','No puede prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.',null),
('aux-age:11-e53bd9bafd','aux-age',11,'NO será inmediatamente ejecutiva la resolución:','["De un procedimiento sancionador contra la que quepa algún recurso en vía administrativa, incluido el potestativo de reposición", "De un procedimiento sancionador contra la que quepa recurso de alzada, pero no si solo cabe el potestativo de reposición", "De una solicitud de licencia que haya sido estimada", "De un recurso de alzada"]'::jsonb,0,'Art. 98.1 b) Ley 39/2015','Las sanciones no son ejecutivas mientras quepa recurso administrativo.',null),
('aux-age:11-70a26d968c','aux-age',11,'Iniciado un procedimiento sancionador, si el infractor reconoce su responsabilidad:','["Se reduce la sanción a la mitad de forma automática", "Se archiva el procedimiento sin imponer sanción, si el infractor paga voluntariamente", "Se podrá resolver el procedimiento con la imposición de la sanción que proceda", "Se podrá resolver el procedimiento sin imponer sanción, salvo que la infracción sea muy grave o el infractor sea reincidente"]'::jsonb,2,'Art. 85.1 Ley 39/2015','El reconocimiento permite resolver con la sanción procedente.',null),
('aux-age:11-a19a5b77d7','aux-age',11,'La AGE, las CCAA y las Entidades Locales dispondrán de:','["Un registro electrónico general de apoderamientos", "Un registro de representantes en papel", "Un registro notarial propio", "Un registro único estatal compartido obligatoriamente"]'::jsonb,0,'Art. 6.1 Ley 39/2015','Cada una dispone de un registro electrónico general de apoderamientos.',null),
('aux-age:11-89cce09e11','aux-age',11,'La ejecución subsidiaria procede respecto de actos que:','["Impongan obligaciones de no hacer o de soportar, previo apercibimiento al obligado", "Impongan al obligado el pago de cantidades líquidas", "Sean personalísimos de hacer y el obligado se niegue a realizarlos en el plazo fijado", "Por no ser personalísimos puedan ser realizados por sujeto distinto del obligado"]'::jsonb,3,'Art. 102.1 Ley 39/2015','Cabe cuando el acto no es personalísimo y otro sujeto puede realizarlo.',null),
('aux-age:11-49e74889b2','aux-age',11,'Si antes del vencimiento del plazo de audiencia los interesados manifiestan su decisión de no efectuar alegaciones:','["Se tendrá por decaído su derecho y se archivará el procedimiento", "Se tendrá por realizado el trámite", "Se ampliará de oficio el plazo para que puedan reconsiderar su decisión, que no será vinculante hasta su vencimiento", "Se suspenderá el procedimiento"]'::jsonb,1,'Art. 82.3 Ley 39/2015','El trámite se tiene por realizado.',null),
('aux-age:11-4771108339','aux-age',11,'Los actos administrativos serán objeto de publicación cuando:','["Lo pida cualquier ciudadano interesado en conocerlos", "Lo establezcan las normas reguladoras de cada procedimiento o lo aconsejen razones de interés público", "Sean desfavorables para el interesado, aunque la norma reguladora no lo prevea", "Lo establezcan las normas reguladoras de cada procedimiento, pero nunca por razones de interés público apreciadas por el órgano"]'::jsonb,1,'Art. 45.1 Ley 39/2015','Se publican cuando lo establezcan sus normas reguladoras o lo aconsejen razones de interés público apreciadas por el órgano competente.',null),
('aux-age:1-9e2a6ff3ef','aux-age',1,'Son ilegales las asociaciones que:','["Reciban subvenciones públicas sin haberse inscrito previamente en el registro", "Persigan fines o utilicen medios tipificados como delito", "Tengan menos de diez socios fundadores", "No estén inscritas en un registro"]'::jsonb,1,'Art. 22.2 CE','Las asociaciones que persigan fines o utilicen medios tipificados como delito son ilegales.',null),
('aux-age:11-06e1d61bd3','aux-age',11,'Si el procedimiento de revisión de oficio se inició de oficio y transcurren seis meses sin resolución, se produce:','["La estimación por silencio", "La caducidad del mismo", "La prórroga automática del plazo", "La nulidad automática del acto"]'::jsonb,1,'Art. 106.5 Ley 39/2015','Iniciado de oficio: caducidad. Iniciado a solicitud: se podrá entender desestimada.',null),
('aux-age:11-117dead0bb','aux-age',11,'Las notificaciones se practicarán preferentemente:','["Mediante anuncio en el BOE, salvo que el interesado señale un domicilio", "En papel en el domicilio del interesado, salvo que este solicite la notificación electrónica", "Por medios electrónicos o en papel, a elección del órgano que dicte el acto", "Por medios electrónicos y, en todo caso, cuando el interesado esté obligado a recibirlas por esta vía"]'::jsonb,3,'Art. 41.1 Ley 39/2015','Se practicarán preferentemente por medios electrónicos.',null),
('aux-age:11-c49ccf20d1','aux-age',11,'Transcurrido el plazo de seis meses desde la iniciación del procedimiento de lesividad sin que se haya declarado, se produce:','["La declaración automática de lesividad", "La nulidad del acto", "La estimación del interesado por silencio", "La caducidad del procedimiento"]'::jsonb,3,'Art. 107.3 Ley 39/2015','Pasados seis meses sin declaración de lesividad, el procedimiento caduca.',null),
('aux-age:11-b624491826','aux-age',11,'En los casos de estimación por silencio, la resolución expresa posterior:','["Podrá ser desestimatoria si así lo aconseja el interés público", "Deberá someterse a dictamen previo del Consejo de Estado", "Solo podrá dictarse de ser confirmatoria del mismo", "Podrá ser confirmatoria o desestimatoria, según el resultado de la instrucción y las alegaciones de los interesados"]'::jsonb,2,'Art. 24.3 a) Ley 39/2015','La resolución expresa posterior a la estimación por silencio solo puede confirmarla.',null),
('aux-age:1-b03e0af2eb','aux-age',1,'La nacionalidad española se adquiere, se conserva y se pierde:','["Solo por nacimiento o por residencia legal continuada", "Según lo que establezca cada Comunidad Autónoma en su Estatuto", "De acuerdo con lo establecido por la ley", "Por decisión del Gobierno, mediante real decreto acordado en Consejo de Ministros"]'::jsonb,2,'Art. 11.1 CE','Se adquiere, conserva y pierde de acuerdo con lo establecido por la ley.',null),
('aux-age:1-925adfbf32','aux-age',1,'El art. 40.2 encomienda a los poderes públicos garantizar el descanso necesario mediante:','["La jubilación anticipada y la reducción de la edad de jubilación", "La semana laboral de cuatro días y la jornada continua", "La limitación de la jornada laboral y las vacaciones periódicas retribuidas", "La limitación de la jornada laboral y los permisos retribuidos que fije cada convenio colectivo"]'::jsonb,2,'Art. 40.2 CE','Mediante la limitación de la jornada laboral, las vacaciones periódicas retribuidas y la promoción de centros adecuados.',null),
('aux-age:11-af14d409c1','aux-age',11,'Si el órgano competente para resolver considera que la infracción o la sanción revisten mayor gravedad que la propuesta, se notificará al inculpado para alegaciones en un plazo de:','["Quince días", "Diez días", "Cinco días", "Un mes"]'::jsonb,0,'Art. 90.2 Ley 39/2015','El inculpado dispone de quince días para alegar.',null),
('aux-age:11-8a65140e66','aux-age',11,'Iniciado un procedimiento de revisión de oficio o de lesividad, el órgano competente podrá suspender la ejecución del acto cuando:','["El acto sea favorable al interesado y este lo solicite antes de que se dicte la resolución", "Esta pudiera causar perjuicios de imposible o difícil reparación", "Lo solicite cualquier tercero, aunque no acredite la condición de interesado ni perjuicio alguno", "Hayan transcurrido seis meses desde que se dictó el acto"]'::jsonb,1,'Art. 108 Ley 39/2015','Puede suspenderse si la ejecución causaría perjuicios de imposible o difícil reparación.',null),
('aux-age:11-e37a0bdd58','aux-age',11,'Son interesados en el procedimiento, según el art. 4.1 a):','["Cualquier ciudadano, sin necesidad de acreditar interés alguno", "Quienes lo promuevan como titulares de derechos subjetivos, pero no de intereses legítimos colectivos", "Quienes tengan derechos que puedan resultar afectados por la decisión, aunque no se hayan personado", "Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos"]'::jsonb,3,'Art. 4.1 a) Ley 39/2015','También los que tengan derechos que puedan resultar afectados y los titulares de intereses legítimos que se personen antes de la resolución definitiva.',null),
('aux-age:11-8118acf7f6','aux-age',11,'¿Ante quién se interpone el recurso extraordinario de revisión?','["Ante el Tribunal Superior de Justicia competente", "Ante el superior jerárquico del órgano que dictó el acto, que es competente para resolverlo", "Ante el órgano administrativo que dictó el acto, que también es competente para resolverlo", "Ante el superior jerárquico del órgano que dictó el acto, previo dictamen del Consejo de Estado"]'::jsonb,2,'Art. 125.1 Ley 39/2015','Se interpone y resuelve por el mismo órgano que dictó el acto.',null),
('aux-age:1-2bf96c764d','aux-age',1,'El derecho de reunión pacífica y sin armas:','["No necesita autorización previa", "Requiere autorización judicial", "Requiere autorización del Delegado del Gobierno", "Solo se ejerce en locales cerrados"]'::jsonb,0,'Art. 21.1 CE','Se reconoce el derecho de reunión pacífica y sin armas, cuyo ejercicio no necesita autorización previa.',null),
('aux-age:11-6e94dc1360','aux-age',11,'Contra el acuerdo que resuelva sobre la ampliación del plazo máximo de resolución:','["Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "No cabrá recurso alguno", "Cabe recurso de alzada"]'::jsonb,2,'Art. 23.2 Ley 39/2015','Ese acuerdo no es recurrible.',null),
('aux-age:11-70b1ccdd00','aux-age',11,'La ampliación excepcional del plazo máximo de resolución no podrá ser superior:','["A la mitad del plazo establecido para la tramitación del procedimiento", "Al plazo establecido para la tramitación del procedimiento", "A diez días hábiles", "A un año, cualquiera que sea el plazo inicial"]'::jsonb,1,'Art. 23.1 Ley 39/2015','Contra el acuerdo de ampliación no cabe recurso.',null),
('aux-age:11-3669d6d380','aux-age',11,'Si concurren varios interesados en un procedimiento de la AGE y existe discrepancia en cuanto a la lengua:','["Se tramitará en la lengua cooficial", "Lo decide el interesado que figure en primer lugar", "Se tramitará en ambas lenguas", "El procedimiento se tramitará en castellano"]'::jsonb,3,'Art. 15.1 Ley 39/2015','En caso de discrepancia, se tramita en castellano.',null),
('aux-age:11-cd7bed9d65','aux-age',11,'Los trámites que deban ser cumplimentados por los interesados se realizarán, salvo plazo distinto, en el plazo de:','["Diez días a partir del siguiente al de la notificación del correspondiente acto", "Cinco días a partir del siguiente al de la notificación", "Quince días a partir del siguiente al de la notificación del correspondiente acto", "Diez días a partir del mismo día de la notificación"]'::jsonb,0,'Art. 73.1 Ley 39/2015','El plazo general es de diez días.',null),
('aux-age:11-6cd483116f','aux-age',11,'La ejecución forzosa de los actos administrativos se efectuará:','["Solo con autorización judicial previa", "Siempre mediante compulsión sobre las personas", "Respetando siempre el principio de proporcionalidad y por los medios menos restrictivos de la libertad individual", "Respetando el principio de eficacia, por el medio más rápido disponible aunque no sea el menos restrictivo de la libertad individual"]'::jsonb,2,'Art. 99 Ley 39/2015','La ejecución forzosa respeta la proporcionalidad y elige el medio menos restrictivo.',null),
('aux-age:11-c73ef43a7e','aux-age',11,'La ampliación de un plazo y su solicitud deberán producirse:','["Solo el último día del plazo de que se trate", "En todo caso antes del vencimiento del plazo de que se trate", "Hasta diez días después del vencimiento del plazo, si se justifica la causa", "En cualquier momento"]'::jsonb,1,'Art. 32.3 Ley 39/2015','En ningún caso podrá ampliarse un plazo ya vencido.',null),
('aux-age:1-093b9c16b0','aux-age',1,'Según el art. 10.1, son fundamento del orden político y de la paz social:','["La monarquía parlamentaria, la soberanía nacional y la unidad de la Nación española", "La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás", "La dignidad de la persona, la soberanía popular, la economía social de mercado, la unidad de la Nación española y la solidaridad entre sus nacionalidades y regiones", "La unidad de mercado y la libertad de empresa"]'::jsonb,1,'Art. 10.1 CE','Lo son la dignidad de la persona, sus derechos inviolables, el libre desarrollo de la personalidad y el respeto a la ley y a los derechos de los demás.',null),
('aux-age:11-d076dab7c7','aux-age',11,'Según el art. 54, los procedimientos podrán iniciarse:','["De oficio o a solicitud del interesado", "Solo de oficio, por propia iniciativa del órgano", "De oficio, a solicitud del interesado o por orden judicial", "Solo a solicitud"]'::jsonb,0,'Art. 54 Ley 39/2015','Las dos clases de iniciación son de oficio y a solicitud del interesado.',null),
('aux-age:11-d0bdfc0716','aux-age',11,'La Administración puede abstenerse de resolver alegando silencio, oscuridad o insuficiencia de los preceptos legales:','["En ningún caso", "Sí, si lo autoriza el superior", "Sí, cuando la ley sea oscura", "Sí, en los procedimientos de oficio"]'::jsonb,0,'Art. 88.5 Ley 39/2015','Nunca puede abstenerse por esos motivos, aunque puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento.',null),
('aux-age:11-a502ef1f41','aux-age',11,'En el procedimiento sancionador se podrá adoptar la tramitación simplificada cuando:','["El infractor sea reincidente y reconozca su responsabilidad", "Existan elementos de juicio suficientes para calificar la infracción como leve", "Existan elementos de juicio suficientes para calificar la infracción como leve o grave", "La infracción sea muy grave y urgente, o lo solicite expresamente el denunciante"]'::jsonb,1,'Art. 96.5 Ley 39/2015','Procede si la infracción se califica como leve.',null),
('aux-age:11-c8daae24bb','aux-age',11,'Las actuaciones complementarias deberán practicarse en un plazo no superior a:','["Un mes", "Quince días", "Siete días", "Tres meses"]'::jsonb,1,'Art. 87 Ley 39/2015','El plazo para resolver queda suspendido hasta su terminación.',null),
('aux-age:11-3faba8927d','aux-age',11,'A efectos de entender cumplida la obligación de notificar dentro del plazo máximo, basta:','["Con firmar la resolución dentro del plazo máximo, aunque su notificación se intente después de vencido ese plazo legal", "Con remitir un aviso por SMS o correo electrónico", "La notificación que contenga el texto íntegro de la resolución y el intento de notificación debidamente acreditado", "Con publicar un anuncio en el tablón de edictos de la sede electrónica, aunque no se haya intentado la notificación personal"]'::jsonb,2,'Art. 40.4 Ley 39/2015','Es suficiente la notificación con el texto íntegro y el intento de notificación debidamente acreditado.',null),
('aux-age:1-4d18e946f3','aux-age',1,'La estructura interna y el funcionamiento de los Colegios Profesionales deberán ser:','["Fijados por el Gobierno", "Secretos", "Democráticos", "Jerárquicos"]'::jsonb,2,'Art. 36 CE','La ley regulará los Colegios Profesionales, cuya estructura interna y funcionamiento deberán ser democráticos.',null),
('aux-age:1-7b4e7d997b','aux-age',1,'Según el art. 7, los sindicatos de trabajadores y las asociaciones empresariales deben tener:','["Una estructura interna y un funcionamiento democráticos", "Un número mínimo de afiliados que fije la ley orgánica correspondiente", "Autorización administrativa previa", "Inscripción en el Registro de Partidos Políticos"]'::jsonb,0,'Art. 7 CE','Su estructura interna y funcionamiento deberán ser democráticos.',null),
('aux-age:11-89f40be67b','aux-age',11,'El apremio sobre el patrimonio procede cuando, en virtud del acto, haya de satisfacerse:','["Una obligación de no hacer", "Una cantidad líquida", "Una obligación de soportar", "Una obligación personalísima"]'::jsonb,1,'Art. 101.1 Ley 39/2015','Si hay que satisfacer cantidad líquida se sigue el procedimiento de apremio.',null),
('aux-age:1-a9a8c69876','aux-age',1,'La riqueza de las distintas modalidades lingüísticas de España es, según la Constitución:','["Un asunto de las Comunidades sin protección constitucional", "Un límite a la libertad de expresión", "Un patrimonio cultural objeto de especial respeto y protección", "Una competencia exclusiva del Estado"]'::jsonb,2,'Art. 3.3 CE','Es un patrimonio cultural que será objeto de especial respeto y protección.',null),
('aux-age:11-e55e370c47','aux-age',11,'También producirá la terminación del procedimiento:','["La falta de crédito presupuestario adecuado y suficiente", "La imposibilidad material de continuarlo por causas sobrevenidas, mediante resolución motivada", "La imposibilidad material de continuarlo, que se produce automáticamente sin necesidad de resolución", "El cambio del funcionario instructor, o la falta de crédito presupuestario adecuado para continuarlo"]'::jsonb,1,'Art. 84.2 Ley 39/2015','La resolución que se dicte deberá ser motivada en todo caso.',null),
('aux-age:1-285144f016','aux-age',1,'La ley garantiza el derecho a la negociación colectiva laboral y:','["La prohibición de los convenios de empresa", "El arbitraje obligatorio", "La aprobación de los convenios por el Gobierno", "La fuerza vinculante de los convenios"]'::jsonb,3,'Art. 37.1 CE','La ley garantizará el derecho a la negociación colectiva laboral, así como la fuerza vinculante de los convenios.',null),
('aux-age:11-16b374ac80','aux-age',11,'Los actos de instrucción necesarios para determinar, conocer y comprobar los hechos se realizarán:','["Solo a instancia de los interesados y en papel, que deben proponer las actuaciones necesarias, sin que el órgano que tramite el procedimiento pueda acordarlas de oficio", "Por el órgano que tramite el procedimiento, en papel y sin uso de medios electrónicos, sin que los interesados puedan proponer actuaciones complementarias", "Por el instructor, a propuesta del Consejo de Estado", "De oficio y por medios electrónicos por el órgano que tramite el procedimiento, sin perjuicio del derecho de los interesados a proponer actuaciones"]'::jsonb,3,'Art. 75.1 Ley 39/2015','La instrucción se hace de oficio.',null),
('aux-age:11-56a81a6bcd','aux-age',11,'Según el art. 35.1 i), deben motivarse también:','["Las comunicaciones internas entre órganos", "Los actos reglados, sin excepción, aunque no limiten derechos ni intereses", "Los actos que se dicten en el ejercicio de potestades discrecionales", "Los actos de trámite que no decidan el fondo ni produzcan indefensión"]'::jsonb,2,'Art. 35.1 i) Ley 39/2015','Se motivan los actos dictados en ejercicio de potestades discrecionales y los que deban serlo por disposición legal.',null),
('aux-age:11-e4f44a376b','aux-age',11,'En las Entidades Locales, la declaración de lesividad corresponde a:','["El Pleno de la Corporación o, en su defecto, el órgano colegiado superior de la entidad", "La Junta de Gobierno Local en todo caso, previo dictamen del órgano consultivo autonómico", "El Alcalde, dando cuenta al Pleno", "El Alcalde o, en su defecto, el Secretario municipal, previo informe preceptivo del Interventor"]'::jsonb,0,'Art. 107.5 Ley 39/2015','La adopta el Pleno o, en su defecto, el órgano colegiado superior.',null),
('aux-age:11-0948a3ef70','aux-age',11,'En los procedimientos de responsabilidad patrimonial, el acuerdo alcanzado entre el interesado y el órgano competente deberá fijar:','["La culpa del funcionario causante del daño", "La sanción disciplinaria del empleado público responsable", "La cuantía de la indemnización, pero no el modo, que fija después el órgano competente", "La cuantía y el modo de indemnización"]'::jsonb,3,'Art. 86.5 Ley 39/2015','El acuerdo fija la cuantía y el modo de indemnización.',null),
('aux-age:11-c25be20191','aux-age',11,'En los procedimientos iniciados de oficio, la Administración podrá desistir:','["Libremente y sin necesidad de motivación", "Motivadamente, en los supuestos y con los requisitos previstos en las leyes", "Solo con autorización judicial", "Motivadamente, en cualquier supuesto, sin necesidad de previsión legal"]'::jsonb,1,'Art. 93 Ley 39/2015','El desistimiento de la Administración debe ser motivado y legalmente previsto.',null),
('aux-age:11-d56bebd2e8','aux-age',11,'Las Administraciones podrán celebrar acuerdos, pactos, convenios o contratos que pongan fin al procedimiento siempre que:','["El interesado sea una persona jurídica y el acuerdo se refiera a materias de contenido económico o patrimonial", "No sean contrarios al ordenamiento jurídico ni versen sobre materias no susceptibles de transacción", "Se refieran a sanciones de cuantía inferior a 3.000 euros", "Lo autorice un juez"]'::jsonb,1,'Art. 86.1 Ley 39/2015','Es la terminación convencional.',null),
('aux-age:1-2b9351051e','aux-age',1,'Los extranjeros gozan en España de las libertades públicas del Título I:','["En ningún caso, salvo los derechos inherentes a la dignidad humana", "En igualdad absoluta con los españoles, incluido el derecho de sufragio en todas las elecciones", "Solo si residen legalmente más de cinco años", "En los términos que establezcan los tratados y la ley"]'::jsonb,3,'Art. 13.1 CE','Gozarán de las libertades públicas que garantiza el Título I en los términos que establezcan los tratados y la ley.',null),
('aux-age:1-e691153099','aux-age',1,'Las libertades del art. 20 tienen su límite, especialmente, en:','["La opinión mayoritaria de la sociedad, los intereses económicos del Estado y las instrucciones del Gobierno sobre la información pública", "Las instrucciones del Gobierno en materia de comunicación", "La seguridad nacional, el orden público, los intereses económicos del Estado y las instrucciones del Gobierno en materia de comunicación", "El derecho al honor, a la intimidad, a la propia imagen y la protección de la juventud y de la infancia"]'::jsonb,3,'Art. 20.4 CE','Tienen su límite en los demás derechos del Título I y, especialmente, en el honor, la intimidad, la propia imagen y la protección de la juventud y la infancia.',null),
('aux-age:11-8c91f321aa','aux-age',11,'El órgano que declare la nulidad o anule las actuaciones dispondrá siempre la conservación de:','["Aquellos actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción", "Ningún acto del procedimiento", "Los actos de trámite anteriores a la infracción, aunque su contenido hubiera variado de no cometerse esta", "Solo la resolución final y los actos de trámite posteriores a la infracción, aunque su contenido hubiera variado"]'::jsonb,0,'Art. 51 Ley 39/2015','Es el principio de conservación de actos y trámites.',null),
('aux-age:11-06cbd51c63','aux-age',11,'Las Administraciones no iniciarán ninguna actuación material de ejecución que limite derechos de los particulares:','["Sin informe favorable del Consejo de Estado u órgano consultivo equivalente", "Sin el consentimiento expreso y por escrito del particular afectado por la actuación", "Sin que previamente haya sido adoptada la resolución que le sirva de fundamento jurídico", "Sin autorización judicial en todo caso"]'::jsonb,2,'Art. 97.1 Ley 39/2015','Es necesario un título previo: la resolución que sirve de fundamento jurídico.',null),
('aux-age:11-75daf9b662','aux-age',11,'Cuando razones de interés público lo aconsejen, podrá acordarse la tramitación de urgencia, que supone:','["Reducir todos los plazos a cinco días, incluidos los de recursos", "Suprimir los recursos administrativos", "Reducir a la mitad todos los plazos del procedimiento, incluidos los de presentación de solicitudes y recursos", "Reducir a la mitad los plazos del procedimiento ordinario, salvo los relativos a la presentación de solicitudes y recursos"]'::jsonb,3,'Art. 33.1 Ley 39/2015','Se reducen los plazos a la mitad, salvo los de solicitudes y recursos.',null),
('aux-age:11-f444c54b06','aux-age',11,'Solicitado el certificado acreditativo del silencio, este deberá emitirse en el plazo máximo de:','["Tres meses", "Diez días", "Un mes", "Quince días"]'::jsonb,3,'Art. 24.4 Ley 39/2015','El certificado del silencio se emite en un máximo de quince días.',null),
('aux-age:11-2c615da130','aux-age',11,'El instructor solo podrá rechazar las pruebas propuestas por los interesados cuando:','["Sean costosas para la Administración, aunque sean pertinentes y necesarias, mediante resolución motivada", "Sean manifiestamente improcedentes o innecesarias, mediante resolución motivada", "Sean improcedentes a su juicio, sin necesidad de motivar el rechazo ni notificarlo a los interesados", "Se propongan fuera del plazo de diez días"]'::jsonb,1,'Art. 77.3 Ley 39/2015','El rechazo de pruebas debe ser motivado y basarse en su improcedencia o innecesariedad manifiesta.',null),
('aux-age:11-605f84b83e','aux-age',11,'Si un plazo fijado en meses vence en un mes en el que no hay día equivalente al de la notificación:','["El plazo expira el último día del mes", "El plazo se amplía 10 días", "El plazo expira el primer día del mes siguiente", "El plazo se considera vencido el día 28"]'::jsonb,0,'Art. 30.4 Ley 39/2015','Si no hay día equivalente, el plazo expira el último día del mes.',null),
('aux-age:11-1020652d86','aux-age',11,'Ponen fin a la vía administrativa:','["Los actos de trámite simples", "Las propuestas de resolución", "Las resoluciones de los recursos de alzada", "Los actos de órganos con superior jerárquico, como regla general"]'::jsonb,2,'Art. 114.1 a) Ley 39/2015','Las resoluciones de alzada ponen fin a la vía administrativa.',null),
('aux-age:11-7c15a9b09d','aux-age',11,'El procedimiento está sometido al principio de:','["Rogación exclusiva del interesado, que lo impulsa en todos sus trámites mediante escritos sucesivos", "Celeridad, y se impulsará de oficio en todos sus trámites y a través de medios electrónicos", "Secreto de las actuaciones", "Oralidad, y se impulsará a instancia de los interesados en cada uno de sus trámites, en papel"]'::jsonb,1,'Art. 71.1 Ley 39/2015','El impulso es de oficio, con respeto a la transparencia y la publicidad.',null),
('aux-age:11-34b5b74a96','aux-age',11,'En la petición de un informe se concretará:','["El plazo de tres meses para su emisión y el sentido del informe", "El extremo o extremos acerca de los que se solicita", "El sentido que debe tener el informe y el plazo para emitirlo", "El nombre del funcionario que debe emitirlo"]'::jsonb,1,'Art. 79.2 Ley 39/2015','Hay que concretar los extremos sobre los que se pide el informe.',null),
('aux-age:11-4cb9a0a019','aux-age',11,'Si durante la instrucción de un procedimiento no publicado se advierte la existencia de personas titulares de derechos o intereses legítimos que puedan resultar afectados:','["Se comunicará a dichas personas la tramitación del procedimiento", "No se les comunica nada hasta la resolución, que se les notifica", "Se suspenderá el procedimiento hasta que soliciten personarse", "Se archivará el procedimiento"]'::jsonb,0,'Art. 8 Ley 39/2015','Se les comunica la tramitación.',null),
('aux-age:11-16c5d42091','aux-age',11,'El órgano que resuelva el recurso podrá suspender la ejecución del acto impugnado cuando:','["La impugnación se fundamente en alguna de las causas de nulidad de pleno derecho del art. 47.1", "La impugnación se fundamente en cualquier causa de anulabilidad, aunque la ejecución no cause perjuicios", "Lo pida un tercero no interesado en el procedimiento", "El acto sea favorable"]'::jsonb,0,'Art. 117.2 b) Ley 39/2015','También cuando la ejecución pueda causar perjuicios de imposible o difícil reparación.',null),
('aux-age:11-c76963a2de','aux-age',11,'La Administración está obligada a dictar resolución expresa y a notificarla:','["Solo en los procedimientos sancionadores", "En todos los procedimientos, cualquiera que sea su forma de iniciación", "Solo en los procedimientos iniciados a solicitud del interesado", "En todos los procedimientos, salvo en los iniciados de oficio, en que basta la caducidad"]'::jsonb,1,'Art. 21.1 Ley 39/2015','La obligación de resolver alcanza a todos los procedimientos, salvo las excepciones legales.',null),
('aux-age:11-e3aecd94bb','aux-age',11,'Si un día es hábil en el municipio del interesado e inhábil en la sede del órgano administrativo, o a la inversa:','["Se aplica el calendario del órgano", "Se aplica el calendario del interesado", "Se considerará inhábil en todo caso", "Se considerará hábil en todo caso"]'::jsonb,2,'Art. 30.6 Ley 39/2015','En caso de discrepancia, se considera inhábil.',null),
('aux-age:11-e19500f4e8','aux-age',11,'La acumulación de procedimientos exige, entre otros requisitos, que:','["Lo soliciten todos los interesados por escrito", "Sea el mismo órgano quien deba tramitar y resolver el procedimiento", "Estén en la misma fase de tramitación y se refieran al mismo interesado o a interesados distintos", "Los interesados sean los mismos y los procedimientos estén en la misma fase"]'::jsonb,1,'Art. 57 Ley 39/2015','Se acumulan los que guarden identidad sustancial o íntima conexión y los tramite y resuelva el mismo órgano.',null),
('aux-age:11-40ecc83b84','aux-age',11,'La falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte o subsane en el plazo de:','["Cinco días improrrogables desde el requerimiento, sin que el órgano pueda establecer otro plazo", "Quince días hábiles", "Un mes desde el requerimiento", "Diez días, o el plazo superior que establezca el órgano cuando las circunstancias lo requieran"]'::jsonb,3,'Art. 5.6 Ley 39/2015','El plazo para subsanar es de diez días.',null),
('aux-age:1-78afb33fe8','aux-age',1,'Las penas privativas de libertad y las medidas de seguridad están orientadas a:','["El trabajo obligatorio en beneficio de la comunidad y la compensación económica a la víctima del delito", "La compensación económica a la víctima y a la sociedad", "La reeducación y la reinserción social, y no pueden consistir en trabajos forzados", "La reeducación y la reinserción social, y pueden incluir trabajos forzados en los casos que prevea la ley"]'::jsonb,2,'Art. 25.2 CE','Están orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados.',null),
('aux-age:11-e0e507c8c1','aux-age',11,'Según el art. 53.1 d), los interesados pueden formular alegaciones y aportar documentos:','["Solo en la solicitud inicial", "Solo en el período de prueba", "En cualquier fase del procedimiento anterior al trámite de audiencia", "En cualquier fase del procedimiento, incluso después de dictarse la resolución"]'::jsonb,2,'Art. 53.1 d) Ley 39/2015','Hasta el trámite de audiencia, que deberán ser tenidos en cuenta al redactar la propuesta de resolución.',null),
('aux-age:11-770539a9fb','aux-age',11,'Contra la resolución de un recurso de reposición:','["Cabe recurso de alzada", "No puede interponerse de nuevo dicho recurso", "Cabe un segundo recurso de reposición", "Cabe recurso de reposición ante el superior"]'::jsonb,1,'Art. 124.3 Ley 39/2015','No cabe reiterar la reposición.',null),
('aux-age:11-76c71512af','aux-age',11,'Los interesados que conozcan datos que permitan identificar a otros interesados que no hayan comparecido en el procedimiento:','["Tienen prohibido comunicarlos por razones de protección de datos", "Pueden comunicarlos voluntariamente, sin estar obligados a ello", "Tienen el deber de proporcionárselos a la Administración actuante", "Solo deben comunicarlos ante un juez"]'::jsonb,2,'Art. 18.2 Ley 39/2015','Existe el deber de proporcionar esos datos a la Administración.',null),
('aux-age:11-af53a58f26','aux-age',11,'La publicación sustituye a la notificación, entre otros casos, cuando el acto:','["Se dicte en un procedimiento iniciado de oficio que afecte a varios interesados identificados", "Afecte a un único interesado identificado", "Tenga por destinatario a una pluralidad indeterminada de personas", "Sea una sanción leve impuesta a un interesado identificado y con domicilio conocido"]'::jsonb,2,'Art. 45.1 a) Ley 39/2015','También en los actos de procedimientos selectivos o de concurrencia competitiva.',null),
('aux-age:1-ae6ada7fd4','aux-age',1,'Las Fuerzas Armadas están constituidas, según la Constitución, por:','["El Ejército de Tierra y la Policía Nacional", "El Ejército de Tierra, la Armada y el Ejército del Aire", "Las Fuerzas y Cuerpos de Seguridad del Estado", "El Ejército de Tierra, la Guardia Civil y la Armada"]'::jsonb,1,'Art. 8.1 CE','Las constituyen el Ejército de Tierra, la Armada y el Ejército del Aire.',null),
('aux-age:1-083414aa7d','aux-age',1,'Según el art. 33.3, nadie podrá ser privado de sus bienes y derechos sino:','["Por deudas con particulares reconocidas en sentencia firme", "Por orden del alcalde", "Por causa justificada de utilidad pública o interés social, sin indemnización cuando así lo decida el Gobierno mediante real decreto", "Por causa justificada de utilidad pública o interés social, mediante la correspondiente indemnización y de conformidad con la ley"]'::jsonb,3,'Art. 33.3 CE','Solo por causa justificada de utilidad pública o interés social, con indemnización y conforme a la ley.',null),
('aux-age:11-94c9703d84','aux-age',11,'Las Administraciones están obligadas a verificar la identidad de los interesados mediante la comprobación de:','["Su huella dactilar o cualquier otro dato biométrico que conste en el DNI o en el documento identificativo equivalente", "Su nombre y apellidos o denominación o razón social, que consten en el DNI o documento identificativo equivalente", "Su dirección de correo electrónico", "Su número de teléfono móvil"]'::jsonb,1,'Art. 9.1 Ley 39/2015','Se verifica con el nombre y apellidos o razón social del DNI o documento equivalente.',null),
('aux-age:11-10b179beab','aux-age',11,'Si nadie se hace cargo de la notificación en papel en el domicilio, se repetirá:','["Dos veces en la misma semana, en horas distintas", "No se repite, y se publica directamente en el BOE", "Una sola vez y en una hora distinta dentro de los tres días siguientes", "Una sola vez y en la misma hora dentro de los cinco días siguientes"]'::jsonb,2,'Art. 42.2 Ley 39/2015','Se repite por una sola vez y en hora distinta dentro de los tres días siguientes.',null),
('aux-age:11-9cd83ed1e7','aux-age',11,'El incumplimiento de la obligación de dictar resolución expresa en plazo dará lugar a:','["La nulidad de pleno derecho del procedimiento", "Una sanción al interesado", "La estimación automática de la solicitud en todo caso, sin ninguna otra consecuencia para el órgano o para el personal responsable", "La exigencia de responsabilidad disciplinaria, sin perjuicio de la que hubiere lugar de acuerdo con la normativa aplicable"]'::jsonb,3,'Art. 21.6 Ley 39/2015','El personal y los titulares de órganos son responsables directos y responden disciplinariamente.',null),
('aux-age:11-7bc5cb2a1b','aux-age',11,'Deben ser motivados, con sucinta referencia de hechos y fundamentos de derecho:','["Solo las disposiciones de carácter general y los actos que pongan fin a la vía administrativa", "Los actos que limiten derechos subjetivos o intereses legítimos", "Solo los actos favorables al interesado", "Todos los actos de trámite, aunque no limiten derechos ni decidan el fondo"]'::jsonb,1,'Art. 35.1 a) Ley 39/2015','El art. 35.1 a) exige motivar los actos que limiten derechos subjetivos o intereses legítimos.',null),
('aux-age:11-8621d95f22','aux-age',11,'Los interesados podrán aducir alegaciones y aportar documentos:','["En cualquier momento del procedimiento anterior al trámite de audiencia", "En cualquier momento, incluso tras la resolución", "Solo tras la propuesta de resolución", "Solo en los diez primeros días desde el inicio del procedimiento"]'::jsonb,0,'Art. 76.1 Ley 39/2015','Serán tenidos en cuenta al redactar la propuesta de resolución.',null),
('aux-age:11-ccd6b6efee','aux-age',11,'Deberá acreditarse la representación para:','["Formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar a derechos", "Pedir información general sobre los procedimientos", "Consultar el estado del expediente", "Cualquier acto de mero trámite, incluida la consulta del expediente, la obtención de copias y la petición de información general"]'::jsonb,0,'Art. 5.3 Ley 39/2015','Para los actos de mero trámite la representación se presume.',null),
('aux-age:1-088dece880','aux-age',1,'Según el art. 30.3, podrá establecerse:','["Un servicio civil para el cumplimiento de fines de interés general", "Un impuesto especial para la defensa nacional y la protección civil", "Un servicio militar universitario", "Una milicia en cada Comunidad Autónoma"]'::jsonb,0,'Art. 30.3 CE','Podrá establecerse un servicio civil para el cumplimiento de fines de interés general.',null),
('aux-age:11-07afaaf972','aux-age',11,'Si en un procedimiento simplificado el dictamen preceptivo del Consejo de Estado se manifiesta en contra del fondo de la propuesta de resolución:','["El órgano competente acordará continuar el procedimiento con arreglo a la tramitación ordinaria", "Se archiva el procedimiento", "Se resuelve igualmente según la propuesta de resolución", "El órgano competente acordará un nuevo trámite de audiencia y resolverá por la tramitación simplificada"]'::jsonb,0,'Art. 96.7 Ley 39/2015','Se pasa a la tramitación ordinaria.',null),
('aux-age:1-14709f2651','aux-age',1,'Según el art. 43.3, los poderes públicos fomentarán:','["El deporte profesional y de alto rendimiento, exclusivamente", "La medicina preventiva privada mediante conciertos con las mutuas sanitarias", "La educación sanitaria, la educación física y el deporte", "La educación física y el deporte escolar, pero no la educación sanitaria"]'::jsonb,2,'Art. 43.3 CE','Fomentarán la educación sanitaria, la educación física y el deporte, y facilitarán la adecuada utilización del ocio.',null),
('aux-age:1-224a2d2c8d','aux-age',1,'Según el art. 33.1, se reconoce el derecho:','["A la herencia, pero solo entre cónyuges y descendientes", "A la propiedad privada y a la herencia", "A la propiedad privada y a una vivienda en propiedad para cada familia", "A una renta mínima garantizada"]'::jsonb,1,'Art. 33.1 CE','Se reconoce el derecho a la propiedad privada y a la herencia.',null),
('aux-age:19-df43510888','aux-age',19,'Las copias auténticas de documentos realizadas por los órganos competentes:','["Solo tienen validez dentro del mismo procedimiento en el que se expidieron", "Caducan a los seis meses de su expedición", "Tienen menos valor probatorio que el original, salvo que se compulsen ante notario", "Tendrán la misma validez y eficacia que los documentos originales"]'::jsonb,3,'Art. 27.2 Ley 39/2015','Las copias auténticas tienen la misma validez y eficacia que los originales.',null),
('aux-age:11-339e85053d','aux-age',11,'¿Cuál de los siguientes es un sistema de identificación electrónica previsto en el art. 9.2?','["Un mensaje desde un número de teléfono previamente comunicado", "El envío de una fotocopia escaneada del DNI por correo electrónico, junto con la solicitud firmada a mano", "Los sistemas basados en certificados electrónicos cualificados de firma electrónica", "Una llamada telefónica grabada"]'::jsonb,2,'Art. 9.2 Ley 39/2015','También los certificados cualificados de sello electrónico y otros sistemas que las AAPP consideren válidos.',null),
('aux-age:11-51da42d780','aux-age',11,'Cuando la sanción tenga únicamente carácter pecuniario, el reconocimiento de responsabilidad y el pago voluntario dan lugar a reducciones de:','["Exactamente el 50 % del importe de la sanción propuesta, no acumulables", "El 30 % solo por pronto pago", "El 10 %, no acumulable", "Al menos el 20 % sobre el importe de la sanción propuesta, acumulables entre sí"]'::jsonb,3,'Art. 85.3 Ley 39/2015','Las reducciones son de al menos el 20 % cada una, acumulables, y pueden incrementarse reglamentariamente.',null),
('aux-age:11-2b2c4fb061','aux-age',11,'Según el art. 38, los actos de las Administraciones sujetos al Derecho Administrativo son:','["Ejecutivos solo tras su confirmación judicial", "Ejecutivos con arreglo a lo dispuesto en la Ley", "Ejecutivos solo cuando sean firmes en vía administrativa y no se haya interpuesto recurso contencioso-administrativo", "Meramente declarativos hasta que se confirmen judicialmente"]'::jsonb,1,'Art. 38 Ley 39/2015','Los actos sujetos al Derecho Administrativo serán ejecutivos con arreglo a lo dispuesto en la Ley.',null),
('aux-age:11-479aa57807','aux-age',11,'Las cuestiones incidentales que se susciten en el procedimiento, incluso las que se refieran a la nulidad de actuaciones:','["Suspenden la tramitación, salvo la abstención", "Determinan el archivo provisional del procedimiento hasta su resolución por el órgano superior", "No suspenderán la tramitación del procedimiento, salvo la recusación", "Suspenden siempre la tramitación"]'::jsonb,2,'Art. 74 Ley 39/2015','Solo la recusación suspende el procedimiento.',null),
('aux-age:1-374dbc2e6b','aux-age',1,'Según el art. 38, se reconoce la libertad de empresa en el marco de:','["La economía de mercado", "La economía cooperativa exclusivamente", "La planificación central obligatoria", "El monopolio estatal"]'::jsonb,0,'Art. 38 CE','Se reconoce la libertad de empresa en el marco de la economía de mercado.',null),
('aux-age:11-cc8bb106be','aux-age',11,'¿Cuál de las siguientes es una tipología de apoderamiento inscribible en el registro electrónico de apoderamientos?','["Un poder otorgado verbalmente ante el funcionario", "Un poder general para que el apoderado actúe en nombre del poderdante en cualquier actuación ante cualquier Administración", "Un poder especial para actuar ante los juzgados y tribunales penales en nombre del poderdante, en cualquier procedimiento", "Un poder sin identificar al apoderado"]'::jsonb,1,'Art. 6 Ley 39/2015','Las tipologías son: poder general, poder ante una Administración u Organismo concreto y poder para trámites específicos.',null),
('aux-age:11-f9f0a56d34','aux-age',11,'Según el principio de simplificación administrativa, se acordarán en un solo acto:','["Todos los recursos de un mismo interesado frente a actos distintos", "La iniciación, la instrucción y la resolución, cuando el procedimiento se tramite por la vía simplificada y lo solicite el interesado", "Todos los trámites de un mismo interesado, aunque sea obligado su cumplimiento sucesivo", "Todos los trámites que, por su naturaleza, admitan un impulso simultáneo y no sea obligado su cumplimiento sucesivo"]'::jsonb,3,'Art. 72.1 Ley 39/2015','Concentración de trámites.',null),
('aux-age:11-69adc28aaa','aux-age',11,'Al declarar la nulidad de una disposición o acto, las Administraciones podrán:','["Establecer en la misma resolución las indemnizaciones que proceda reconocer a los interesados", "Exigir a los interesados el reintegro de lo percibido sin necesidad de procedimiento ni audiencia previa", "Imponer sanciones a los interesados que se beneficiaron del acto nulo, sin necesidad de procedimiento", "Dejar sin efecto las sentencias dictadas sobre el acto"]'::jsonb,0,'Art. 106.4 Ley 39/2015','Pueden fijar indemnizaciones si concurren los requisitos de responsabilidad patrimonial.',null),
('aux-age:1-8809367404','aux-age',1,'Según el art. 35.1, todos los españoles tienen:','["Solo el derecho al trabajo", "El deber de trabajar y el derecho al trabajo", "Derecho a no trabajar sin consecuencias", "Derecho a un empleo público"]'::jsonb,1,'Art. 35.1 CE','Tienen el deber de trabajar y el derecho al trabajo, a la libre elección de profesión u oficio y a una remuneración suficiente.',null),
('aux-age:19-171b607bc7','aux-age',19,'Se entiende por documentos públicos administrativos:','["Los documentos privados presentados en un registro público", "Los documentos autorizados por notario, exclusivamente", "Los válidamente emitidos por los órganos de las Administraciones Públicas", "Cualquier documento firmado electrónicamente por un ciudadano y presentado en la sede electrónica de una Administración"]'::jsonb,2,'Art. 26.1 Ley 39/2015','Se emiten por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma.',null),
('aux-age:1-8d67d19905','aux-age',1,'Según el art. 28.1, respecto a la libertad sindical:','["La afiliación es obligatoria para los funcionarios", "Nadie podrá ser obligado a afiliarse a un sindicato", "Solo pueden sindicarse los trabajadores fijos", "Los jueces pueden sindicarse sin límites"]'::jsonb,1,'Art. 28.1 CE','Todos tienen derecho a sindicarse libremente y nadie podrá ser obligado a afiliarse a un sindicato.',null),
('aux-age:1-48db972541','aux-age',1,'El derecho de petición, según el art. 29.1:','["Solo pueden ejercerlo las asociaciones", "Requiere abogado", "Es individual y colectivo, por escrito", "Solo es individual y verbal"]'::jsonb,2,'Art. 29.1 CE','Todos los españoles tienen el derecho de petición individual y colectiva, por escrito.',null),
('aux-age:11-8ecb7b550a','aux-age',11,'La ampliación de plazos por el tiempo máximo permitido se aplicará en todo caso a los procedimientos tramitados por:','["Las Comunidades Autónomas cuando afecten a varias provincias", "Los órganos colegiados de cualquier Administración, y los que exijan algún trámite en otra Comunidad Autónoma", "Las misiones diplomáticas y oficinas consulares, y los que exijan algún trámite en el extranjero", "Los Ayuntamientos de municipios de gran población, y los que exijan algún trámite en otra Comunidad Autónoma"]'::jsonb,2,'Art. 32.2 Ley 39/2015','Se aplica a misiones diplomáticas, oficinas consulares y trámites en el extranjero o con interesados residentes fuera de España.',null),
('aux-age:19-4b01ab3270','aux-age',19,'Las Administraciones no exigirán a los interesados la presentación de documentos originales:','["Salvo en los procedimientos iniciados de oficio", "Salvo que, con carácter excepcional, la normativa reguladora aplicable establezca lo contrario", "En ningún caso, sin excepciones", "Salvo que el funcionario que tramite el procedimiento lo considere oportuno para comprobar su autenticidad"]'::jsonb,1,'Art. 28.3 Ley 39/2015','La regla es no exigir originales; solo excepcionalmente por normativa.',null),
('aux-age:11-dfe7b92773','aux-age',11,'Es causa de inadmisión de un recurso:','["Que se presente en una oficina de Correos sin sello de fechas", "Que el recurrente no esté asistido de abogado", "Haber transcurrido el plazo para su interposición", "Que el recurrente haya calificado erróneamente el recurso, aunque se deduzca su verdadero carácter"]'::jsonb,2,'Art. 116 d) Ley 39/2015','Otras causas: incompetencia, falta de legitimación, acto no recurrible y carecer manifiestamente de fundamento.',null),
('aux-age:11-305888f042','aux-age',11,'La compulsión sobre las personas procede, en los casos que la ley expresamente lo autorice, para:','["Obligaciones no personalísimas de hacer que puedan cumplirse por otro", "Cobrar cantidades líquidas", "Cualquier acto, a elección de la Administración", "Actos que impongan una obligación personalísima de no hacer o soportar"]'::jsonb,3,'Art. 104.1 Ley 39/2015','Se aplica a obligaciones personalísimas de no hacer o soportar, respetando la dignidad y los derechos constitucionales.',null),
('aux-age:11-ff1b16231e','aux-age',11,'Si la resolución va a pronunciarse sobre cuestiones conexas no planteadas por los interesados, el órgano competente debe ponerlo de manifiesto a estos por un plazo:','["De tres días", "De un mes", "No superior a quince días", "No inferior a veinte días"]'::jsonb,2,'Art. 88.1 Ley 39/2015','Se da audiencia por plazo no superior a quince días.',null),
('aux-age:1-0e351b461d','aux-age',1,'El art. 43 reconoce el derecho a:','["La asistencia sanitaria privada gratuita", "La protección de la salud", "La elección libre de médico en todo caso", "Un seguro de vida"]'::jsonb,1,'Art. 43.1 CE','Se reconoce el derecho a la protección de la salud.',null),
('aux-age:11-48c728688e','aux-age',11,'En los procedimientos sancionadores, la fase instructora y la sancionadora:','["Corresponderán al mismo órgano, salvo que la ley disponga otra cosa", "Las realiza el denunciante y el órgano competente, respectivamente", "Se tramitan como una sola fase", "Se encomendarán a órganos distintos"]'::jsonb,3,'Art. 63.1 Ley 39/2015','Los procedimientos sancionadores se inician siempre de oficio y separan instrucción y resolución.',null),
('aux-age:1-1afe412d9c','aux-age',1,'El art. 47 reconoce a todos los españoles el derecho a:','["Una ayuda pública al alquiler en todo caso, de cuantía fija", "Una vivienda en propiedad a precio tasado", "Disfrutar de una vivienda digna y adecuada", "Disfrutar de una vivienda digna, que los poderes públicos deben adjudicar directamente a quien la solicite"]'::jsonb,2,'Art. 47 CE','Todos los españoles tienen derecho a disfrutar de una vivienda digna y adecuada.',null),
('aux-age:1-02068caaf5','aux-age',1,'Los poderes públicos garantizarán la conservación y promoverán el enriquecimiento de:','["Las empresas públicas y su patrimonio", "El patrimonio histórico, cultural y artístico de los pueblos de España", "El patrimonio histórico, cultural y artístico de titularidad pública, pero no el de titularidad privada", "Los bienes de la Corona"]'::jsonb,1,'Art. 46 CE','Garantizarán la conservación y promoverán el enriquecimiento del patrimonio histórico, cultural y artístico.',null),
('aux-age:11-1d35e95e58','aux-age',11,'Para que entren en vigor y produzcan efectos jurídicos, las normas con rango de ley, los reglamentos y disposiciones administrativas habrán de:','["Publicarse en el diario oficial correspondiente", "Firmarse por el Rey y comunicarse a las Cortes Generales", "Comunicarse a todos los Ayuntamientos y Diputaciones afectados", "Aprobarse por referéndum"]'::jsonb,0,'Art. 131 Ley 39/2015','La publicación en el diario oficial es requisito de entrada en vigor.',null),
('aux-age:11-d6317deea8','aux-age',11,'En la notificación de la práctica de una prueba se consignará el lugar, fecha y hora, con la advertencia de que el interesado:','["Puede nombrar técnicos para que le asistan", "Debe comparecer acompañado de notario o de abogado colegiado", "No puede asistir a su práctica", "Debe abonar en todo caso los gastos de la prueba"]'::jsonb,0,'Art. 78.2 Ley 39/2015','Se le advierte que puede nombrar técnicos que le asistan.',null),
('aux-age:11-fcfbd01e2c','aux-age',11,'Excepcionalmente, se podrá otorgar eficacia retroactiva a los actos cuando:','["Sean sanciones más favorables que las anteriores", "Se trate de actos de gravamen que restrinjan derechos individuales y así lo prevea expresamente una norma reglamentaria", "Lo solicite cualquier tercero afectado y el acto restrinja derechos individuales del destinatario", "Se dicten en sustitución de actos anulados o produzcan efectos favorables al interesado"]'::jsonb,3,'Art. 39.3 Ley 39/2015','Cabe retroactividad cuando se dicten en sustitución de actos anulados o produzcan efectos favorables, si los supuestos de hecho existían y no se lesionan derechos de terceros.',null),
('aux-age:11-76cb3b1ca9','aux-age',11,'En los procedimientos sancionadores, la orden superior de iniciación expresará, en la medida de lo posible:','["El sentido de la resolución que deba dictarse", "La sanción que corresponda imponer, el órgano competente para resolver, el instructor designado y el plazo máximo para dictar resolución", "El nombre del abogado defensor del presunto responsable y la sanción que corresponde imponerle según la tipificación", "La persona o personas presuntamente responsables, las conductas o hechos, su tipificación y el lugar y fecha"]'::jsonb,3,'Art. 60.2 Ley 39/2015','La orden superior debe concretar responsables, hechos, tipificación, lugar y fecha.',null),
('aux-age:11-29f1ca030e','aux-age',11,'En la ejecución subsidiaria, el importe de los gastos podrá liquidarse:','["De forma provisional y realizarse antes de la ejecución, a reserva de la liquidación definitiva", "Por el doble de su coste, en concepto de sanción", "Nunca, porque los gastos los asume siempre la Administración que ejecuta", "Solo tras la ejecución, de forma definitiva y sin posibilidad de liquidación provisional"]'::jsonb,0,'Art. 102.4 Ley 39/2015','Cabe liquidación provisional previa a reserva de la definitiva; los gastos corren a cargo del obligado.',null),
('aux-age:11-699ec685a1','aux-age',11,'Requerirán en todo caso la aprobación expresa del Consejo de Ministros u órgano equivalente de las CCAA:','["Todos los acuerdos convencionales que pongan fin a cualquier procedimiento", "Los acuerdos de los Ayuntamientos", "Los acuerdos que versen sobre materias de la competencia directa de dicho órgano", "Los acuerdos de cuantía superior a 6.000 €"]'::jsonb,2,'Art. 86.3 Ley 39/2015','Solo los que versen sobre materias de su competencia directa.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-age:1-aad38d74e2','aux-age',1,'Según el art. 24.1, todas las personas tienen derecho a obtener la tutela efectiva de los jueces y tribunales:','["Sin que, en ningún caso, pueda producirse indefensión", "Solo en asuntos penales y contencioso-administrativos", "Solo si están asistidas de abogado y procurador", "Previo pago de las tasas judiciales correspondientes"]'::jsonb,0,'Art. 24.1 CE','Tienen derecho a la tutela judicial efectiva sin que, en ningún caso, pueda producirse indefensión.',null),
('aux-age:11-56a8f7f68c','aux-age',11,'En la AGE, los procedimientos de responsabilidad patrimonial se resolverán, como regla general, por:','["El Ministro respectivo", "El Subsecretario", "El Presidente del Gobierno", "El Delegado del Gobierno"]'::jsonb,0,'Art. 92 Ley 39/2015','Por el Consejo de Ministros en los casos del art. 32.3 LRJSP o cuando una ley lo disponga.',null),
('aux-age:11-06499852e7','aux-age',11,'Cuando se soliciten informes preceptivos a un órgano, el plazo máximo para resolver puede suspenderse por el tiempo que medie entre la petición y la recepción del informe, sin que pueda exceder de:','["Tres meses", "Seis meses", "Un mes", "Diez días"]'::jsonb,0,'Art. 22.1 d) Ley 39/2015','Esta suspensión no puede exceder en ningún caso de tres meses.',null),
('aux-age:11-ca01f8ee3e','aux-age',11,'Los titulares de intereses legítimos que puedan resultar afectados por la resolución son interesados si:','["Se personan en el procedimiento en tanto no haya recaído resolución definitiva", "Lo solicitan antes del inicio del procedimiento", "Se personan en cualquier momento, incluso después de la resolución definitiva", "Lo autoriza el instructor"]'::jsonb,0,'Art. 4.1 c) Ley 39/2015','Deben personarse antes de la resolución definitiva.',null),
('aux-age:1-b4862aa7a7','aux-age',1,'¿Qué prohíbe el art. 26 de la Constitución?','["Los colegios profesionales con adscripción obligatoria", "Los jurados populares en el ámbito penal", "Los tribunales militares en tiempo de guerra y en los supuestos de estado de sitio declarados por el Congreso", "Los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales"]'::jsonb,3,'Art. 26 CE','Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.',null),
('aux-age:11-af18333f3a','aux-age',11,'Transcurridos tres meses desde la interposición del recurso extraordinario de revisión sin resolución:','["Caducará el procedimiento", "Se entenderá desestimado, quedando expedita la vía contencioso-administrativa", "Se entenderá estimado, salvo que el recurso se base en un error de hecho resultante de los documentos del expediente", "Se prorrogará otros tres meses"]'::jsonb,1,'Art. 126.3 Ley 39/2015','El silencio en el recurso extraordinario de revisión es desestimatorio.',null),
('aux-age:11-326a986e1b','aux-age',11,'En ningún caso se podrá imponer una sanción:','["Sin que se haya tramitado el oportuno procedimiento", "A una persona jurídica", "Superior a 600 euros sin autorización judicial", "Sin que el infractor esté asistido de abogado"]'::jsonb,0,'Art. 63.2 Ley 39/2015','La sanción exige siempre procedimiento previo.',null),
('aux-age:11-b7c83f5ce6','aux-age',11,'La nulidad o anulabilidad de un acto:','["Implica siempre la nulidad de todo el procedimiento", "No implica la de los sucesivos en el procedimiento que sean independientes del primero", "Implica la de todos los actos posteriores del procedimiento, aunque sean independientes del primero", "Solo afecta a actos favorables"]'::jsonb,1,'Art. 49.1 Ley 39/2015','No se extiende a los actos sucesivos que sean independientes del primero.',null),
('aux-age:11-3cd7ee9c71','aux-age',11,'En caso de desestimación por silencio, la resolución expresa posterior:','["No puede dictarse", "Se adoptará por la Administración sin vinculación alguna al sentido del silencio", "Debe ser necesariamente desestimatoria, en coherencia con el sentido del silencio producido", "Solo puede ser confirmatoria"]'::jsonb,1,'Art. 24.3 b) Ley 39/2015','En la estimación por silencio, en cambio, la resolución posterior solo puede ser confirmatoria.',null),
('aux-age:1-727b2ada73','aux-age',1,'El art. 18.1 garantiza el derecho:','["Al honor, a la intimidad personal y familiar y a la propia imagen", "A la propiedad privada y a la herencia", "A la libertad de empresa en el marco de la economía de mercado", "Al secreto de las comunicaciones"]'::jsonb,0,'Art. 18.1 CE','Garantiza el derecho al honor, a la intimidad personal y familiar y a la propia imagen.',null),
('aux-age:1-1d4c08f55f','aux-age',1,'El derecho de fundación se reconoce:','["Para fines de interés general, con arreglo a la ley", "Solo a las empresas y sociedades mercantiles", "Solo para fines religiosos o benéficos", "Para cualquier fin, incluido el lucrativo, con arreglo a la ley"]'::jsonb,0,'Art. 34.1 CE','Se reconoce el derecho de fundación para fines de interés general, con arreglo a la ley.',null),
('aux-age:11-737187d9ef','aux-age',11,'El error o la ausencia de calificación del recurso por parte del recurrente:','["No será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter", "Obliga a presentarlo de nuevo", "Solo puede subsanarse si el recurrente está asistido de abogado", "Determina su inadmisión, salvo que el recurrente lo subsane en el plazo de diez días desde el requerimiento"]'::jsonb,0,'Art. 115.2 Ley 39/2015','Lo importante es que se deduzca el verdadero carácter del recurso.',null),
('aux-age:11-cfa6d2abc2','aux-age',11,'Los vicios y defectos que hagan anulable un acto:','["Solo pueden alegarse en vía judicial", "No podrán ser alegados por quienes los hubieren causado", "Determinan siempre la nulidad de pleno derecho del acto, aunque no causen indefensión", "Pueden alegarse por cualquier persona, incluidos quienes los hubieran causado"]'::jsonb,1,'Art. 115.3 Ley 39/2015','Quien causó el vicio no puede alegarlo.',null),
('aux-age:11-036b222a16','aux-age',11,'El acuerdo de realización de actuaciones complementarias se notificará a los interesados, concediéndoles un plazo para alegaciones tras su finalización de:','["Siete días", "Cinco días", "Quince días", "Diez días"]'::jsonb,0,'Art. 87 Ley 39/2015','Plazo de siete días para alegaciones; las actuaciones se practican en un máximo de quince días y el plazo para resolver queda suspendido.',null),
('aux-age:11-a2ee2137b8','aux-age',11,'Tienen capacidad de obrar ante las Administraciones Públicas:','["Solo los españoles mayores de edad", "Las personas físicas o jurídicas que la ostenten con arreglo a las normas civiles", "Solo los mayores de 21 años y las personas jurídicas inscritas en un registro público", "Las personas físicas o jurídicas con certificado digital, aunque no tengan capacidad conforme a las normas civiles"]'::jsonb,1,'Art. 3 a) Ley 39/2015','Tienen capacidad las personas que la tengan según las normas civiles.',null),
('aux-age:1-ae0ddd1aa2','aux-age',1,'Según el art. 9.1, están sujetos a la Constitución y al resto del ordenamiento jurídico:','["Solo los ciudadanos españoles", "Solo los funcionarios y los poderes públicos", "Solo los poderes públicos y los funcionarios", "Los ciudadanos y los poderes públicos"]'::jsonb,3,'Art. 9.1 CE','Los ciudadanos y los poderes públicos están sujetos a la Constitución y al resto del ordenamiento jurídico.',null),
('aux-age:11-f1a2cc9379','aux-age',11,'En los procedimientos iniciados de oficio de los que pudiera derivarse el reconocimiento de derechos o situaciones favorables, el vencimiento del plazo sin resolución permite a los interesados:','["Entender desestimadas sus pretensiones por silencio administrativo", "Entender estimadas sus pretensiones por silencio administrativo positivo", "Solicitar que se declare la caducidad del procedimiento", "Exigir una indemnización automática"]'::jsonb,0,'Art. 25.1 a) Ley 39/2015','En estos procedimientos el silencio es desestimatorio.',null),
('aux-age:11-08b9d8e810','aux-age',11,'La comparecencia en el trámite de información pública:','["Solo pueden hacerla los vecinos del municipio afectado", "Es obligatoria para poder recurrir después la resolución", "Convierte en interesado al compareciente", "No otorga, por sí misma, la condición de interesado"]'::jsonb,3,'Art. 83.3 Ley 39/2015','La incomparecencia tampoco impide a los interesados recurrir la resolución.',null),
('aux-age:1-8c39e8787a','aux-age',1,'Las prestaciones personales o patrimoniales de carácter público solo pueden establecerse:','["Con arreglo a la ley", "Por reglamento", "Por orden ministerial", "Por acuerdo municipal"]'::jsonb,0,'Art. 31.3 CE','Solo podrán establecerse prestaciones personales o patrimoniales de carácter público con arreglo a la ley.',null),
('aux-age:11-a242f5cf40','aux-age',11,'Contra el acuerdo de acumulación de procedimientos:','["No procederá recurso alguno", "Cabe recurso de reposición", "Cabe recurso extraordinario de revisión", "Cabe recurso de alzada"]'::jsonb,0,'Art. 57 Ley 39/2015','La acumulación procede si hay identidad sustancial o íntima conexión y el mismo órgano tramita y resuelve.',null),
('aux-age:11-391500b000','aux-age',11,'Si la Administración acuerda de oficio la tramitación simplificada y algún interesado manifiesta su oposición expresa:','["Se mantiene la tramitación simplificada si el órgano lo motiva por razones de interés público", "Se mantiene la tramitación simplificada", "Se mantiene la tramitación simplificada si el órgano lo motiva", "La Administración deberá seguir la tramitación ordinaria"]'::jsonb,3,'Art. 96.2 Ley 39/2015','La oposición expresa de un interesado obliga a la tramitación ordinaria.',null),
('aux-age:11-f5f80d10b6','aux-age',11,'La resolución que ponga fin al procedimiento sancionador será ejecutiva cuando:','["Lo decida motivadamente el instructor del procedimiento", "No quepa contra ella ningún recurso ordinario en vía administrativa", "Se notifique al interesado, aunque quepa contra ella recurso de alzada", "Se dicte por el órgano competente, aunque quepa contra ella recurso de alzada"]'::jsonb,1,'Art. 90.3 Ley 39/2015','Puede suspenderse cautelarmente si el interesado manifiesta que interpondrá recurso contencioso-administrativo.',null),
('aux-age:11-2f070987fb','aux-age',11,'Si la cuestión suscitada entrañase interés general, la Administración ante un desistimiento o renuncia:','["Podrá limitar sus efectos al interesado y seguirá el procedimiento", "Deberá aceptarlo de plano y declarar concluso el procedimiento para todos los interesados", "Deberá archivar el procedimiento", "Deberá pedir dictamen al Consejo de Estado"]'::jsonb,0,'Art. 94.5 Ley 39/2015','El procedimiento continúa por el interés general.',null),
('aux-age:1-55a5889ea2','aux-age',1,'Según el art. 44.2, los poderes públicos promoverán:','["La investigación militar y de defensa, y la cooperación científica con las Fuerzas Armadas aliadas", "Solo la investigación sanitaria y farmacéutica", "La investigación privada exclusivamente, mediante incentivos fiscales a las empresas", "La ciencia y la investigación científica y técnica en beneficio del interés general"]'::jsonb,3,'Art. 44.2 CE','Promoverán la ciencia y la investigación científica y técnica en beneficio del interés general.',null),
('aux-age:11-e8cf46aaf7','aux-age',11,'Si un informe preceptivo no se emite en plazo:','["Se entiende desfavorable a la pretensión del interesado y se continúa el procedimiento hasta su resolución", "Se entiende favorable", "Se podrá suspender el transcurso del plazo máximo legal para resolver el procedimiento", "Se archiva el procedimiento"]'::jsonb,2,'Art. 80.3 Ley 39/2015','Si no es preceptivo, se pueden proseguir las actuaciones.',null),
('aux-age:11-3c3c9e7fc2','aux-age',11,'Según el art. 3 c), los grupos de afectados y las entidades sin personalidad jurídica tienen capacidad de obrar:','["Siempre, cualquiera que sea su número de miembros", "Cuando tengan más de 20 miembros", "Cuando la ley así lo declare expresamente", "Cuando se inscriban en el registro correspondiente de la Administración ante la que actúen"]'::jsonb,2,'Art. 3 c) Ley 39/2015','Grupos de afectados, uniones y entidades sin personalidad y patrimonios independientes tienen capacidad cuando la ley lo declare expresamente.',null),
('aux-age:11-d2f48f173c','aux-age',11,'¿Cuáles son los principios de buena regulación del art. 129 de la Ley 39/2015?','["Eficacia, jerarquía, descentralización, desconcentración y coordinación", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia", "Igualdad, mérito, capacidad y publicidad", "Necesidad, eficacia, proporcionalidad, seguridad jurídica, publicidad y jerarquía"]'::jsonb,1,'Art. 129.1 Ley 39/2015','Son seis principios de buena regulación.',null),
('aux-age:11-61e124094a','aux-age',11,'Si un interesado solicita la tramitación simplificada y el órgano considera que no procede, podrá desestimarla en el plazo de:','["Cinco días desde su presentación, sin posibilidad de recurso", "Un mes desde su presentación, con recurso de alzada", "Diez días desde su presentación, con recurso de alzada", "Cinco días desde su presentación, con recurso potestativo de reposición"]'::jsonb,0,'Art. 96.3 Ley 39/2015','Transcurrido el plazo sin resolver, se entiende desestimada.',null),
('aux-age:1-bfc24cac29','aux-age',1,'¿Quién establece los términos en que extranjeros y apátridas pueden gozar del derecho de asilo?','["Los tratados exclusivamente", "La ley", "El Defensor del Pueblo", "El Ministerio del Interior por orden"]'::jsonb,1,'Art. 13.4 CE','La ley establecerá los términos en que los ciudadanos de otros países y los apátridas podrán gozar del derecho de asilo.',null),
('aux-age:1-19db9e4b02','aux-age',1,'¿Qué regula la ley según el art. 20.3?','["La censura previa de los medios de comunicación privados", "Las tarifas publicitarias y el régimen de concesión de licencias de los medios de comunicación privados de ámbito estatal", "El control parlamentario de los medios de comunicación social dependientes del Estado o de cualquier ente público", "El control gubernamental de todos los medios de comunicación social, públicos y privados, a través de una autoridad independiente"]'::jsonb,2,'Art. 20.3 CE','La ley regulará la organización y el control parlamentario de los medios dependientes del Estado o de cualquier ente público.',null),
('aux-age:11-40b6b985da','aux-age',11,'Los reglamentos y disposiciones administrativas NO podrán:','["Desarrollar una ley", "Publicarse en el BOE", "Regular la organización interna de la Administración ni el funcionamiento de sus órganos colegiados y unidades administrativas", "Tipificar delitos, faltas o infracciones administrativas, establecer penas o sanciones, ni tributos"]'::jsonb,3,'Art. 128.2 Ley 39/2015','Tampoco vulnerar la Constitución o las leyes ni regular materias reservadas a las Cortes o a las Asambleas autonómicas.',null),
('aux-age:1-e39b5750e0','aux-age',1,'Respecto a la extradición, la Constitución establece que:','["No se consideran delitos políticos los actos de terrorismo", "Solo la concede el Gobierno, sin intervención judicial", "Se concede sin necesidad de tratado ni de ley, por reciprocidad", "Está prohibida en todo caso respecto de los nacionales"]'::jsonb,0,'Art. 13.3 CE','La extradición se concede en cumplimiento de un tratado o de la ley, atendiendo a la reciprocidad; los actos de terrorismo no se consideran delitos políticos.',null),
('aux-age:11-350680f8ab','aux-age',11,'Según la Ley 39/2015, el Gobierno de la Nación ejercerá la iniciativa legislativa en los términos de la Constitución mediante:','["La iniciativa legislativa popular", "Las proposiciones de ley del Senado", "La elaboración y aprobación de los anteproyectos de ley y la remisión de los proyectos de ley a las Cortes Generales", "La elaboración de proposiciones de ley que remite a las Cortes Generales a través del Consejo de Estado"]'::jsonb,2,'Art. 127 Ley 39/2015','También podrá aprobar reales decretos-leyes y reales decretos legislativos.',null),
('aux-age:11-4e96fd27d7','aux-age',11,'Si el vicio de un acto consiste en incompetencia no determinante de nulidad, la convalidación podrá realizarse por:','["El interesado afectado, mediante escrito en el que manifieste su conformidad con el acto viciado", "El órgano competente, cuando sea superior jerárquico del que dictó el acto viciado", "El propio órgano que dictó el acto, mediante una resolución posterior que subsane el vicio de incompetencia", "El Defensor del Pueblo"]'::jsonb,1,'Art. 52.3 Ley 39/2015','La incompetencia no determinante de nulidad se convalida por el órgano competente superior jerárquico.',null),
('aux-age:11-04f531107a','aux-age',11,'Las Administraciones podrán practicar notificaciones por medios no electrónicos cuando:','["Para asegurar la eficacia de la actuación sea necesario practicarla por entrega directa de un empleado público", "Sea fin de semana", "La notificación sea favorable al interesado", "El interesado esté obligado a relacionarse electrónicamente con la Administración y no haya accedido a la notificación"]'::jsonb,0,'Art. 41.2 b) Ley 39/2015','También cuando el interesado comparezca espontáneamente en una oficina de asistencia y solicite la comunicación personal.',null),
('aux-age:1-1bb95ef982','aux-age',1,'Toda persona detenida debe ser informada:','["Solo si lo solicita su abogado o un familiar", "En el plazo máximo de 72 horas, una vez puesta a disposición judicial y en presencia de su abogado", "Solo cuando sea puesta a disposición judicial, en presencia de su abogado y en el plazo de setenta y dos horas", "De forma inmediata y comprensible de sus derechos y de las razones de su detención"]'::jsonb,3,'Art. 17.3 CE','Debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención.',null),
('aux-age:11-4c9361727a','aux-age',11,'El recurso de alzada se interpone ante:','["El Tribunal Superior de Justicia de la Comunidad Autónoma", "El Consejo de Estado", "El órgano superior jerárquico del que dictó el acto, pudiendo presentarse ante el que lo dictó o ante el competente para resolver", "El mismo órgano que dictó el acto, que lo resuelve en el plazo de un mes, sin que pueda presentarse ante el superior jerárquico ni ante otro órgano"]'::jsonb,2,'Art. 121.1 Ley 39/2015','Lo resuelve el superior jerárquico; puede presentarse ante cualquiera de los dos.',null),
('aux-age:11-23fc1ba1fb','aux-age',11,'Si el órgano aprecia que la publicación íntegra de un acto lesiona derechos o intereses legítimos:','["Se publicará íntegramente igualmente, sin perjuicio de la responsabilidad patrimonial que proceda por los daños causados a los interesados afectados", "No se publicará ni notificará el acto, y el órgano se limitará a comunicar a los interesados que existe una resolución que les afecta", "Se enviará al Defensor del Pueblo", "Se limitará a publicar una somera indicación del contenido y del lugar donde los interesados pueden comparecer para conocerlo"]'::jsonb,3,'Art. 46 Ley 39/2015','Se publica una somera indicación del contenido y del lugar donde comparecer en el plazo que se establezca.',null),
('aux-age:11-070418eb2e','aux-age',11,'Los expedientes tendrán formato electrónico y se formarán mediante la agregación ordenada de documentos, con:','["Un sello en papel en cada documento", "Un resumen elaborado por el instructor con la relación de los interesados y de los trámites realizados", "La firma de todos los interesados en cada uno de los documentos que contenga", "Un índice numerado de todos los documentos que contenga cuando se remita"]'::jsonb,3,'Art. 70.2 Ley 39/2015','Deben incluir un índice numerado de todos los documentos.',null),
('aux-age:1-9eb205d070','aux-age',1,'Según la Constitución, ¿puede alguien ser obligado a declarar sobre su ideología, religión o creencias?','["No", "Sí, ante un juez", "Sí, en los censos oficiales", "Solo los funcionarios"]'::jsonb,0,'Art. 16.2 CE','Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.',null),
('aux-age:11-4004fdb426','aux-age',11,'Las notificaciones por medios electrónicos se entienden practicadas:','["Al día siguiente de su emisión", "Cuando el interesado contesta", "Cuando se envía al interesado el aviso de puesta a disposición por correo electrónico o SMS", "En el momento en que se produzca el acceso a su contenido"]'::jsonb,3,'Art. 43.2 Ley 39/2015','Se entienden practicadas en el momento del acceso a su contenido.',null),
('aux-age:1-7d0c43d43f','aux-age',1,'Respecto al medio ambiente, el art. 45.1 reconoce:','["El derecho a disfrutar de un medio ambiente adecuado y el deber de conservarlo", "El derecho a disfrutar de un medio ambiente adecuado, sin establecer ningún deber de conservarlo", "El derecho a explotarlo libremente", "El deber de conservarlo, pero no el derecho a disfrutarlo, que se regula en los Estatutos"]'::jsonb,0,'Art. 45.1 CE','Todos tienen el derecho a disfrutar de un medio ambiente adecuado para el desarrollo de la persona, así como el deber de conservarlo.',null),
('aux-age:11-d3416e6a09','aux-age',11,'Según el principio de eficiencia del art. 129.6, la iniciativa normativa debe:','["Aumentar los trámites para garantizar el control", "Aprobarse sin consulta pública previa ni trámite de audiencia, para reducir la duración del procedimiento normativo", "Evitar cargas administrativas innecesarias o accesorias y racionalizar la gestión de los recursos públicos", "Evitar cargas administrativas innecesarias, aunque suponga aumentar el gasto público y crear nuevos órganos"]'::jsonb,2,'Art. 129.6 Ley 39/2015','Eficiencia: evitar cargas innecesarias o accesorias.',null),
('aux-age:19-6dc3412beb','aux-age',19,'En el asiento de registro debe constar, entre otros datos:','["La firma del superior jerárquico del órgano destinatario y el sello de la oficina que lo recibe", "Un número, epígrafe expresivo de su naturaleza, fecha y hora de presentación, identificación del interesado y referencia al contenido", "Un número, fecha de presentación, identificación del interesado y del órgano destinatario, pero no la hora de presentación ni ninguna referencia a su contenido", "El sentido previsible de la resolución"]'::jsonb,1,'Art. 16.2 Ley 39/2015','Se emite recibo con copia autenticada del documento, fecha y hora de presentación y número de entrada.',null),
('aux-age:1-150ce89932','aux-age',1,'Las banderas propias de las Comunidades Autónomas:','["Las aprueba el Gobierno de la Nación a propuesta de cada Comunidad", "Están prohibidas en los edificios públicos del Estado", "Sustituyen a la bandera de España en los edificios y actos oficiales de su territorio, si así lo dispone su Estatuto", "Pueden ser reconocidas por los Estatutos y se utilizan junto a la bandera de España en sus edificios y actos oficiales"]'::jsonb,3,'Art. 4.2 CE','Los Estatutos pueden reconocerlas; se usan junto a la bandera de España en sus edificios públicos y actos oficiales.',null),
('aux-age:20-5a6b442ed9','aux-age',20,'Es un derecho de las personas en sus relaciones con las AAPP según el art. 13:','["Elegir al funcionario que tramite su expediente", "Obtener una resolución favorable si la Administración incumple el plazo máximo para resolver", "Ser tratados con respeto y deferencia por las autoridades y empleados públicos", "Ser atendidos en la lengua que elijan, cualquiera que sea la Administración"]'::jsonb,2,'Art. 13 e) Ley 39/2015','Otros: comunicarse por el Punto de Acceso General electrónico, ser asistidos en el uso de medios electrónicos, usar lenguas cooficiales, acceso a información pública…',null),
('aux-age:11-a60489e57f','aux-age',11,'La resolución en un procedimiento de responsabilidad patrimonial deberá pronunciarse sobre:','["La responsabilidad penal del empleado público que causó el daño y la sanción disciplinaria que le corresponda imponer", "La sanción disciplinaria al funcionario responsable y la cuantía de la indemnización", "La existencia o no de relación de causalidad, la valoración del daño y la cuantía y modo de indemnización", "La existencia de culpa o dolo del empleado, que es requisito para que nazca la responsabilidad de la Administración"]'::jsonb,2,'Art. 91.2 Ley 39/2015','Son los extremos obligatorios de la resolución.',null),
('aux-age:11-8d7e74843b','aux-age',11,'No se podrán adoptar medidas provisionales que:','["Sean proporcionadas al objetivo que se pretende garantizar, aunque se adopten antes del inicio del procedimiento en casos de urgencia", "Se adopten una vez iniciado el procedimiento, sin audiencia previa del interesado", "Afecten a la actividad económica del interesado o a su patrimonio, aunque no le causen ningún perjuicio de difícil o imposible reparación ni vulneren sus derechos", "Puedan causar perjuicio de difícil o imposible reparación a los interesados o impliquen violación de derechos amparados por las leyes"]'::jsonb,3,'Art. 56.4 Ley 39/2015','Las medidas provisionales tienen ese límite.',null),
('aux-age:11-a6080a8b19','aux-age',11,'En la tramitación simplificada, el trámite de audiencia solo se realiza cuando:','["Nunca, porque la tramitación simplificada lo suprime en todo caso", "Siempre, como en la tramitación ordinaria", "Lo pida cualquier tercero que no sea interesado", "La resolución vaya a ser desfavorable para el interesado"]'::jsonb,3,'Art. 96.6 d) Ley 39/2015','Las alegaciones al inicio se formulan en cinco días.',null),
('aux-age:11-4d8bd216e5','aux-age',11,'Los términos y plazos establecidos en las leyes obligan:','["Solo a la Administración, que debe resolver en el plazo máximo", "Solo a los interesados, que pierden su derecho si no los cumplen", "A las autoridades y personal al servicio de las Administraciones competentes para la tramitación, así como a los interesados", "A las autoridades y personal de la Administración, pero no a los interesados, que pueden cumplir los trámites en cualquier momento"]'::jsonb,2,'Art. 29 Ley 39/2015','Los plazos obligan tanto a la Administración como a los interesados.',null),
('aux-age:11-4972471e27','aux-age',11,'La eficacia de un acto quedará demorada cuando:','["Se haya dictado en el mes de agosto o en un periodo vacacional, salvo que el interesado solicite su eficacia inmediata", "El interesado lo solicite verbalmente", "Así lo exija su contenido o esté supeditada a su notificación, publicación o aprobación superior", "Así lo decida el funcionario instructor, aunque su contenido no lo exija ni dependa de notificación o aprobación"]'::jsonb,2,'Art. 39.2 Ley 39/2015','La eficacia se demora cuando lo exija el contenido del acto o esté supeditada a notificación, publicación o aprobación superior.',null),
('aux-age:19-9d5d457ad3','aux-age',19,'No se tendrán por presentados en el registro:','["Aquellos documentos e información cuyo régimen especial establezca otra forma de presentación", "Los presentados por un representante cuya representación no esté inscrita", "Los presentados en día inhábil, que se tendrán por no presentados hasta el siguiente hábil", "Los presentados en las oficinas de Correos sin sello de fechas"]'::jsonb,0,'Art. 16.8 Ley 39/2015','No se tienen por presentados los que tengan un régimen especial con otra forma de presentación.',null),
('aux-age:11-73bda7043d','aux-age',11,'Como regla general, los actos administrativos se producirán:','["En papel con firma manuscrita del titular del órgano", "De la forma que elija el interesado en su solicitud, por escrito o verbalmente, en papel o electrónicamente", "Por escrito en papel, salvo que el interesado esté obligado a relacionarse electrónicamente", "Por escrito a través de medios electrónicos, salvo que su naturaleza exija otra forma"]'::jsonb,3,'Art. 36.1 Ley 39/2015','Se producen por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada.',null),
('aux-age:11-f4e1b4609a','aux-age',11,'Cuando la Administración establezca expresamente modelos específicos de presentación de solicitudes en un procedimiento concreto, estos serán:','["De uso obligatorio por los interesados", "Solo orientativos", "Exclusivos para personas jurídicas", "De uso voluntario"]'::jsonb,0,'Art. 66.6 Ley 39/2015','Los modelos específicos establecidos expresamente son de uso obligatorio.',null),
('aux-age:11-05cd9488aa','aux-age',11,'Las resoluciones administrativas de carácter particular no podrán vulnerar una disposición de carácter general:','["Aunque procedan de un órgano de igual o superior jerarquía al que dictó la disposición", "Salvo que lo autorice expresamente el Consejo de Ministros", "Salvo que procedan de un órgano de jerarquía superior al que dictó la disposición", "Salvo que sean favorables al interesado"]'::jsonb,0,'Art. 37.1 Ley 39/2015','Es el principio de inderogabilidad singular de los reglamentos.',null),
('aux-age:11-ce38a5eca4','aux-age',11,'Los plazos expresados en días se contarán:','["Desde que el interesado tenga conocimiento efectivo del acto", "Desde el mismo día de la notificación o publicación del acto", "Desde el día en que se dictó el acto, aunque se notifique o publique con posterioridad a esa fecha", "A partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto"]'::jsonb,3,'Art. 30.3 Ley 39/2015','Se cuentan desde el día siguiente a la notificación o publicación.',null),
('aux-age:1-e8e4c9b64b','aux-age',1,'Las asociaciones solo pueden ser disueltas o suspendidas en sus actividades:','["Por orden del Ministerio del Interior", "Por acuerdo del Consejo de Ministros", "En virtud de resolución judicial motivada", "Por decisión de la Delegación del Gobierno"]'::jsonb,2,'Art. 22.4 CE','Solo podrán ser disueltas o suspendidas en virtud de resolución judicial motivada.',null),
('aux-age:11-de88d01ef8','aux-age',11,'Según el art. 34.1 de la Ley 39/2015, los actos administrativos se producirán:','["Por el órgano competente, ajustándose a los requisitos y al procedimiento establecido", "Por el funcionario que tramite el expediente, con el visto bueno del titular del órgano", "Por cualquier órgano de la misma Administración", "Por el órgano competente, aunque no se ajusten al procedimiento establecido si el contenido es conforme a Derecho"]'::jsonb,0,'Art. 34.1 Ley 39/2015','Los actos se producen por el órgano competente ajustándose a los requisitos y al procedimiento establecido.',null),
('aux-age:11-443515e822','aux-age',11,'La obligación de notificar en plazo se entiende cumplida, en las notificaciones electrónicas, con:','["La puesta a disposición de la notificación en la sede electrónica o en la dirección electrónica habilitada única", "La publicación de un anuncio en el BOE", "El envío del aviso al correo electrónico del interesado, aunque no se ponga a disposición la notificación", "El acceso efectivo del interesado"]'::jsonb,0,'Art. 43.3 Ley 39/2015','Se entiende cumplida con la puesta a disposición en la sede electrónica o la dirección electrónica habilitada única.',null),
('aux-age:11-8b48cad815','aux-age',11,'¿A quién debe notificar el órgano que dicte una resolución?','["A los interesados cuyos derechos e intereses sean afectados por ella", "A todos los vecinos del municipio afectado", "Solo al solicitante, aunque haya otros interesados afectados", "Al superior jerárquico, que da traslado a los interesados"]'::jsonb,0,'Art. 40.1 Ley 39/2015','Se notifica a los interesados cuyos derechos e intereses sean afectados por las resoluciones y actos.',null),
('aux-age:11-3b2328d255','aux-age',11,'La nulidad en parte de un acto no implica la de las partes independientes, salvo que:','["Se haya notificado conjuntamente y en un mismo documento a todos los interesados afectados", "Sea un acto favorable al interesado", "La parte viciada sea de tal importancia que sin ella el acto no se habría dictado", "Lo solicite el interesado en el recurso que interponga contra el acto, justificando su conexión"]'::jsonb,2,'Art. 49.2 Ley 39/2015','Las partes independientes se mantienen, salvo que la parte viciada fuera esencial.',null),
('aux-age:1-d028682efd','aux-age',1,'Según el art. 27.2, la educación tiene por objeto:','["El pleno desarrollo de la personalidad humana en el respeto a los principios democráticos y a los derechos fundamentales", "Preparar para el acceso al empleo y a la función pública", "La formación profesional exclusivamente", "El pleno desarrollo de la personalidad humana en el respeto a la religión mayoritaria y a las tradiciones de cada Comunidad Autónoma"]'::jsonb,0,'Art. 27.2 CE','Tiene por objeto el pleno desarrollo de la personalidad humana en el respeto a los principios democráticos de convivencia y a los derechos y libertades fundamentales.',null),
('aux-age:11-2103a23c21','aux-age',11,'En los procedimientos tramitados por la AGE, la lengua será:','["Siempre la lengua cooficial del territorio donde tenga su sede el órgano", "El castellano, sin que los interesados puedan utilizar ninguna otra lengua, aunque se dirijan a órganos con sede en una Comunidad Autónoma con lengua cooficial", "El castellano, aunque los interesados que se dirijan a órganos con sede en una Comunidad con lengua cooficial podrán utilizar también esta", "La que elija el funcionario que tramite el procedimiento, castellano o lengua cooficial, sin que el interesado pueda solicitar que se utilice otra"]'::jsonb,2,'Art. 15.1 Ley 39/2015','La lengua de la AGE es el castellano, con posibilidad de usar la cooficial ante órganos con sede en esa Comunidad.',null),
('aux-age:11-15a3627f07','aux-age',11,'El Plan Anual Normativo que deben aprobar las Administraciones contiene:','["Los presupuestos y las normas fiscales del año siguiente", "Las iniciativas legales o reglamentarias que vayan a ser elevadas para su aprobación en el año siguiente", "Las iniciativas reglamentarias, pero no las legales, que se aprobarán en los cuatro años siguientes", "Las normas derogadas el año anterior"]'::jsonb,1,'Art. 132.1 Ley 39/2015','Se aprueba anualmente y se publica en el Portal de la Transparencia.',null),
('aux-age:11-79a168ea1e','aux-age',11,'Según el art. 47.1 f), son nulos los actos expresos o presuntos contrarios al ordenamiento por los que se adquieren facultades o derechos:','["Cuando no haya terceros afectados por la adquisición", "Cuando sean favorables al interesado y no haya terceros afectados por ellos", "Cuando se hayan publicado en el boletín oficial sin haberse notificado a los interesados", "Cuando se carezca de los requisitos esenciales para su adquisición"]'::jsonb,3,'Art. 47.1 f) Ley 39/2015','Son nulos si se adquieren facultades o derechos careciendo de los requisitos esenciales.',null),
('aux-age:11-ff48ae42ff','aux-age',11,'Si fueran varios los medios de ejecución admisibles, se elegirá:','["El más rápido para la Administración", "El que elija el interesado de entre los admisibles", "El más económico para la Administración actuante", "El menos restrictivo de la libertad individual"]'::jsonb,3,'Art. 100.2 Ley 39/2015','Se elige el menos restrictivo de la libertad individual.',null),
('aux-age:11-5a70804a8e','aux-age',11,'Los poderes inscritos en el registro electrónico de apoderamientos tendrán una validez máxima de:','["Diez años a contar desde la fecha de inscripción", "Un año, renovable por periodos iguales", "Cinco años a contar desde la fecha de inscripción", "Indefinida, hasta su revocación"]'::jsonb,2,'Art. 6.6 Ley 39/2015','Validez máxima de cinco años; pueden revocarse o prorrogarse, la prórroga por un máximo de cinco años.',null),
('aux-age:11-a492136710','aux-age',11,'Según el art. 105, no se admitirán a trámite contra las actuaciones de los órganos administrativos realizadas en materia de su competencia y de acuerdo con el procedimiento legal:','["Los recursos contencioso-administrativos", "Las acciones posesorias", "Los recursos de alzada", "Las reclamaciones de responsabilidad"]'::jsonb,1,'Art. 105 Ley 39/2015','No se admiten acciones posesorias contra esas actuaciones.',null),
('aux-age:11-6941a1fc1f','aux-age',11,'De las solicitudes y escritos que presenten los interesados, estos podrán exigir:','["Una copia firmada por el titular del órgano destinatario", "La devolución de las tasas abonadas", "Una resolución inmediata sobre la admisión de la solicitud presentada", "El correspondiente recibo que acredite la fecha y hora de presentación"]'::jsonb,3,'Art. 66.3 Ley 39/2015','Pueden exigir recibo con fecha y hora de presentación.',null),
('aux-age:1-073e70d29e','aux-age',1,'Según el art. 2, la Constitución se fundamenta en:','["La indisoluble unidad de la Nación española, y reconoce el derecho a la autonomía de las nacionalidades y regiones", "La voluntad del Jefe del Estado", "La soberanía compartida del Estado y de las Comunidades Autónomas, y reconoce su derecho a la autodeterminación", "El pacto entre los territorios históricos"]'::jsonb,0,'Art. 2 CE','Se fundamenta en la indisoluble unidad de la Nación española y reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones y la solidaridad entre todas ellas.',null),
('aux-age:1-5f63a44cc0','aux-age',1,'¿Quién inspecciona y homologa el sistema educativo?','["Los poderes públicos", "Las universidades", "Los colegios profesionales", "Las asociaciones de padres"]'::jsonb,0,'Art. 27.8 CE','Los poderes públicos inspeccionarán y homologarán el sistema educativo para garantizar el cumplimiento de las leyes.',null),
('aux-age:11-56c7a2b884','aux-age',11,'La Administración aceptará de plano el desistimiento o la renuncia, salvo que terceros interesados personados insten la continuación en el plazo de:','["Cinco días desde que fueron notificados", "Un mes desde que fueron notificados", "Quince días desde que fueron notificados", "Diez días desde que fueron notificados"]'::jsonb,3,'Art. 94.4 Ley 39/2015','Los terceros tienen diez días para pedir la continuación.',null),
('aux-age:11-0a11fcbe98','aux-age',11,'Es nulo de pleno derecho el acto que:','["Lesione los derechos y libertades susceptibles de amparo constitucional", "Se dicte fuera del plazo establecido", "Tenga un defecto de forma que no produzca indefensión", "Incurra en desviación de poder o en cualquier otra infracción del ordenamiento"]'::jsonb,0,'Art. 47.1 a) Ley 39/2015','La lesión de derechos susceptibles de amparo es causa de nulidad de pleno derecho.',null),
('aux-age:11-a724b5ca18','aux-age',11,'Si se trata de obligaciones personalísimas de hacer y no se realiza la prestación, el obligado deberá:','["Resarcir los daños y perjuicios, a cuya liquidación y cobro se procederá en vía administrativa", "Ser objeto de compulsión sobre su persona hasta que realice la prestación, sin resarcimiento alguno", "Nada, la obligación se extingue", "Resarcir los daños y perjuicios, cuya liquidación y cobro solo pueden exigirse en vía judicial civil"]'::jsonb,0,'Art. 104.2 Ley 39/2015','El obligado debe resarcir daños y perjuicios.',null),
('aux-age:11-8eb3b63f50','aux-age',11,'Contra el acuerdo que declare la tramitación de urgencia:','["No cabrá recurso alguno, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento", "Cabe recurso contencioso-administrativo inmediato", "Cabe recurso de alzada", "Cabe recurso potestativo de reposición en el plazo de un mes desde su notificación, que no suspende la tramitación"]'::jsonb,0,'Art. 33.2 Ley 39/2015','El acuerdo de urgencia no es recurrible.',null),
('aux-age:11-07adb03211','aux-age',11,'Con anterioridad al inicio del procedimiento, el órgano competente podrá abrir:','["El período de prueba", "Un período de información o actuaciones previas para conocer las circunstancias del caso y la conveniencia de iniciar", "El trámite de audiencia a los posibles interesados para que aleguen sobre la conveniencia de iniciar el procedimiento", "El trámite de información pública"]'::jsonb,1,'Art. 55.1 Ley 39/2015','Las actuaciones previas sirven para valorar si procede iniciar el procedimiento.',null),
('aux-age:11-69970641b9','aux-age',11,'El órgano competente podrá inadmitir sin dictamen las solicitudes de revisión de oficio formuladas por interesados cuando:','["Se refieran a actos favorables", "Sean formuladas por personas jurídicas", "Se presenten en papel", "Carezcan manifiestamente de fundamento"]'::jsonb,3,'Art. 106.3 Ley 39/2015','También cuando no se basen en causas de nulidad o se hayan desestimado en cuanto al fondo otras sustancialmente iguales.',null),
('aux-age:1-2edddb75be','aux-age',1,'Según el art. 41, los poderes públicos mantendrán:','["Mutualidades profesionales obligatorias", "Un seguro médico solo para los trabajadores por cuenta ajena", "Un sistema privado de pensiones obligatorio", "Un régimen público de Seguridad Social para todos los ciudadanos"]'::jsonb,3,'Art. 41 CE','Mantendrán un régimen público de Seguridad Social para todos los ciudadanos.',null),
('aux-age:11-10f9f83ce3','aux-age',11,'Si en la notificación en papel en el domicilio el interesado no está presente, podrá hacerse cargo de ella:','["Solo un familiar mayor de 18 años", "Cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad", "Cualquier persona mayor de 16 años que se encuentre en el domicilio, sin necesidad de hacer constar su identidad", "Únicamente el interesado"]'::jsonb,1,'Art. 42.2 Ley 39/2015','Puede recogerla cualquier persona mayor de catorce años que esté en el domicilio y haga constar su identidad.',null),
('aux-age:1-e7c5dcb757','aux-age',1,'Según el art. 39.1, los poderes públicos aseguran:','["Una vivienda digna a cada familia", "La protección social, económica y jurídica de la familia", "La protección social, económica y jurídica de la familia, pero solo de la fundada en el matrimonio", "La educación obligatoria hasta los 25 años"]'::jsonb,1,'Art. 39.1 CE','Los poderes públicos aseguran la protección social, económica y jurídica de la familia.',null),
('aux-age:11-6178ad7c8f','aux-age',11,'¿Cuál de las siguientes NO es causa de inadmisión del art. 116?','["Tratarse de un acto no susceptible de recurso", "Carecer de legitimación el recurrente", "Carecer el recurso manifiestamente de fundamento", "Que el recurso se haya calificado erróneamente"]'::jsonb,3,'Art. 116 Ley 39/2015','El error en la calificación no impide la tramitación (art. 115.2).',null),
('aux-age:1-ad0240dc2d','aux-age',1,'Según el art. 50, los poderes públicos garantizarán a los ciudadanos durante la tercera edad:','["Una plaza en una residencia pública", "La gratuidad del transporte público", "Una pensión igual para todos, independientemente de lo cotizado", "Pensiones adecuadas y periódicamente actualizadas"]'::jsonb,3,'Art. 50 CE','Garantizarán, mediante pensiones adecuadas y periódicamente actualizadas, la suficiencia económica en la tercera edad.',null),
('aux-age:11-1307b78b39','aux-age',11,'Las facultades de revisión no podrán ejercerse cuando:','["Lo solicite el propio interesado", "El acto sea nulo de pleno derecho", "Por prescripción de acciones, tiempo transcurrido u otras circunstancias, su ejercicio resulte contrario a la equidad, la buena fe, el derecho de los particulares o las leyes", "Haya transcurrido un año desde la notificación del acto, cualquiera que sea el vicio que lo afecte y aunque su ejercicio no resulte contrario a la equidad, la buena fe ni el derecho de los particulares"]'::jsonb,2,'Art. 110 Ley 39/2015','Son los límites de la revisión.',null),
('aux-age:11-df48e9dad1','aux-age',11,'Según el art. 128.3 de la Ley 39/2015, las disposiciones administrativas:','["Se ajustarán al orden de jerarquía y ninguna podrá vulnerar los preceptos de otra de rango superior", "Tienen todas el mismo rango, y prevalece la posterior", "Prevalecen sobre las leyes", "Se ajustarán al orden de jerarquía, salvo que la de rango inferior sea posterior en el tiempo y regule una materia más específica"]'::jsonb,0,'Art. 128.3 Ley 39/2015','Principio de jerarquía normativa.',null),
('aux-age:1-663424558c','aux-age',1,'El sistema tributario, según el art. 31.1, debe ser justo, inspirado en la igualdad y la progresividad, y:','["Proporcional a la renta en todo caso", "Igual para todos los contribuyentes, con independencia de su renta", "En ningún caso tendrá alcance confiscatorio", "Exclusivamente estatal"]'::jsonb,2,'Art. 31.1 CE','Se basa en la igualdad y la progresividad, y en ningún caso tendrá alcance confiscatorio.',null),
('aux-age:1-889aa2d680','aux-age',1,'Se reconoce a las personas físicas y jurídicas la libertad de:','["Expedir títulos oficiales sin necesidad de homologación", "Fijar libremente los planes de estudio oficiales", "Creación de centros docentes, dentro del respeto a los principios constitucionales", "Creación de centros docentes, que solo podrán impartir enseñanzas no regladas"]'::jsonb,2,'Art. 27.6 CE','Se reconoce la libertad de creación de centros docentes, dentro del respeto a los principios constitucionales.',null),
('aux-age:11-d9ce5d27e9','aux-age',11,'En el procedimiento sancionador, el órgano instructor resolverá la finalización con archivo de actuaciones, sin formular propuesta de resolución, cuando:','["La sanción que corresponda sea muy grave", "El denunciante lo solicite expresamente y retire la denuncia antes de la propuesta de resolución", "Los hechos probados no constituyan, de modo manifiesto, infracción administrativa", "El presunto infractor reconozca su responsabilidad y pague voluntariamente la sanción"]'::jsonb,2,'Art. 89.1 c) Ley 39/2015','También por inexistencia de los hechos, falta de prueba, falta de responsable o prescripción de la infracción.',null),
('aux-age:11-9cb973c723','aux-age',11,'Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este. Esto se denomina:','["Revocación", "Conservación de actos y trámites", "Convalidación", "Conversión de actos viciados"]'::jsonb,3,'Art. 50 Ley 39/2015','Es la conversión de actos viciados.',null),
('aux-age:11-53bb70997e','aux-age',11,'Las Administraciones deben publicar y mantener actualizadas en el portal web:','["Las nóminas de todos sus empleados", "Las resoluciones judiciales que les afecten", "Las relaciones de procedimientos de su competencia, con indicación de los plazos máximos de duración y de los efectos del silencio administrativo", "Las relaciones de procedimientos de su competencia, con los datos de los interesados y el estado de tramitación de cada expediente"]'::jsonb,2,'Art. 21.4 Ley 39/2015','Deben publicar los procedimientos, sus plazos máximos y los efectos del silencio.',null),
('aux-age:11-0e59b13400','aux-age',11,'Transcurridos seis meses desde el inicio de un procedimiento de responsabilidad patrimonial sin resolución ni acuerdo:','["El procedimiento caduca y se archivan las actuaciones sin pronunciamiento sobre la indemnización", "Se entiende estimada la reclamación", "Se paga automáticamente la indemnización", "Podrá entenderse que la resolución es contraria a la indemnización del particular"]'::jsonb,3,'Art. 91.3 Ley 39/2015','El silencio en responsabilidad patrimonial es desestimatorio.',null),
('aux-age:11-dbb3051a5e','aux-age',11,'Las medidas provisionales adoptadas antes de iniciar el procedimiento deberán ser confirmadas, modificadas o levantadas en el acuerdo de iniciación, que deberá efectuarse:','["Dentro del mes siguiente a su adopción", "Dentro de los tres meses siguientes", "Dentro de los quince días siguientes a su adopción", "Dentro de los diez días siguientes a su adopción"]'::jsonb,2,'Art. 56.2 Ley 39/2015','Si no se inicia en ese plazo o el acuerdo no se pronuncia, las medidas quedan sin efecto.',null),
('aux-age:11-3751fb315a','aux-age',11,'Los documentos formalizados por funcionarios con la condición de autoridad en los que se recojan hechos constatados por ellos:','["Tienen valor absoluto e irrebatible", "Solo tienen valor probatorio si los ratifica un juez o el instructor del procedimiento", "No tienen valor probatorio", "Harán prueba de estos salvo que se acredite lo contrario"]'::jsonb,3,'Art. 77.5 Ley 39/2015','Gozan de presunción de veracidad salvo prueba en contrario.',null),
('aux-age:11-04f33e37c2','aux-age',11,'Salvo que reste menos para su tramitación ordinaria, los procedimientos de tramitación simplificada deberán resolverse en:','["Tres meses desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Seis meses desde el inicio del procedimiento", "Treinta días desde el siguiente al que se notifique el acuerdo de tramitación simplificada", "Quince días desde el siguiente al que se notifique el acuerdo de tramitación simplificada"]'::jsonb,2,'Art. 96.6 Ley 39/2015','El plazo es de treinta días.',null),
('aux-age:11-4e761e4f54','aux-age',11,'Se entiende por propia iniciativa:','["La petición de un órgano sin competencia de iniciación", "La denuncia de un particular que pone los hechos en conocimiento del órgano competente para iniciar, sin que este tenga conocimiento directo de las circunstancias", "La actuación derivada del conocimiento directo o indirecto de las circunstancias o hechos por el órgano que tiene la competencia de iniciación", "La orden emitida por un órgano superior jerárquico del competente para iniciar, tras conocer los hechos por una denuncia o por una petición razonada de otro órgano"]'::jsonb,2,'Art. 59 Ley 39/2015','Es el conocimiento directo o indirecto por el propio órgano competente.',null),
('aux-age:11-281447f4bf','aux-age',11,'En la resolución del procedimiento sancionador no se podrán aceptar hechos distintos de los determinados en el curso del procedimiento:','["Salvo que resulten más graves, en cuyo caso se notificarán al inculpado para que formule alegaciones", "Salvo en las infracciones leves, en las que sí pueden aceptarse", "Salvo que lo pida el denunciante", "Con independencia de su diferente valoración jurídica"]'::jsonb,3,'Art. 90.2 Ley 39/2015','Se protege el derecho de defensa del inculpado.',null),
('aux-age:1-8a9fd79e3d','aux-age',1,'Según el art. 9.2, corresponde a los poderes públicos:','["Promover las condiciones para que la libertad y la igualdad sean reales y efectivas, y remover los obstáculos que lo impidan", "Regular la vida privada de los ciudadanos", "Limitar la participación política", "Garantizar la igualdad de resultados económicos entre todos los ciudadanos y territorios, y suprimir las diferencias de renta que lo impidan"]'::jsonb,0,'Art. 9.2 CE','Deben promover esas condiciones, remover los obstáculos y facilitar la participación de todos los ciudadanos.',null),
('aux-age:11-8a1c0f231f','aux-age',11,'En el procedimiento de responsabilidad patrimonial iniciado de oficio, el acuerdo de iniciación se notificará a los presuntos lesionados, concediéndoles un plazo para alegaciones y pruebas de:','["Un mes", "Cinco días", "Diez días", "Quince días"]'::jsonb,2,'Art. 65.2 Ley 39/2015','Se les concede diez días para aportar alegaciones, documentos o información y proponer pruebas.',null),
('aux-age:1-dfae23e383','aux-age',1,'¿Qué regula la ley según el art. 30.2?','["El servicio militar obligatorio, su duración y las causas de exención", "El ejército profesional exclusivamente", "La participación de España en organizaciones internacionales de defensa", "Las obligaciones militares de los españoles y la objeción de conciencia"]'::jsonb,3,'Art. 30.2 CE','La ley fijará las obligaciones militares de los españoles y regulará la objeción de conciencia.',null),
('aux-age:11-c6ac3b4f6f','aux-age',11,'Según el art. 1.2, solo podrán incluirse trámites adicionales o distintos de los de la Ley 39/2015:','["Mediante circular o instrucción interna", "Por decisión del órgano instructor", "Mediante reglamento, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento", "Mediante ley, cuando resulte eficaz, proporcionado y necesario para la consecución de los fines del procedimiento"]'::jsonb,3,'Art. 1.2 Ley 39/2015','Solo mediante ley y de forma motivada.',null),
('aux-age:11-4caa6d5a54','aux-age',11,'Es nulo de pleno derecho el acto:','["Que incurra en cualquier infracción del ordenamiento jurídico, incluida la desviación de poder", "Cuyo defecto de forma no produzca indefensión", "Que sea constitutivo de infracción penal o se dicte como consecuencia de esta", "Dictado un día inhábil"]'::jsonb,2,'Art. 47.1 d) Ley 39/2015','Los actos constitutivos de infracción penal o dictados como consecuencia de esta son nulos.',null),
('aux-age:1-9865e10d60','aux-age',1,'Según el art. 42, el Estado orientará su política hacia el retorno de:','["Los trabajadores españoles en el extranjero", "Los capitales invertidos fuera", "Los funcionarios destinados en el exterior", "Los estudiantes de Erasmus"]'::jsonb,0,'Art. 42 CE','El Estado velará por los derechos de los trabajadores españoles en el extranjero y orientará su política hacia su retorno.',null),
('aux-age:11-e2da5bf5b1','aux-age',11,'En los procedimientos tramitados a solicitud del interesado, la resolución será congruente con las peticiones formuladas:','["Solo si el instructor lo propone y el interesado no se opone", "Pudiendo agravar su situación inicial si así lo exige el interés público", "Salvo que sea una persona jurídica", "Sin que en ningún caso pueda agravar su situación inicial"]'::jsonb,3,'Art. 88.2 Ley 39/2015','Sin perjuicio de la potestad de incoar de oficio un nuevo procedimiento.',null),
('aux-age:11-327c61147f','aux-age',11,'La presentación de una denuncia:','["Convierte al denunciante en interesado en el procedimiento sancionador que se inicie", "Obliga a iniciar el procedimiento y a sancionar", "No confiere, por sí sola, la condición de interesado en el procedimiento", "Requiere asistencia de abogado"]'::jsonb,2,'Art. 62.5 Ley 39/2015','El denunciante no es interesado por el solo hecho de denunciar.',null),
('aux-age:11-07129aa189','aux-age',11,'Según el art. 62.1, se entiende por denuncia:','["La solicitud de un interesado para que se inicie un procedimiento en su favor", "El acto por el que cualquier persona, en cumplimiento o no de una obligación legal, pone en conocimiento de un órgano administrativo un hecho que pudiera justificar la iniciación de oficio", "La propuesta de iniciación formulada por un órgano administrativo sin competencia para iniciar, que tiene conocimiento de los hechos por razón de sus funciones de inspección, averiguación o investigación", "La orden de un superior"]'::jsonb,1,'Art. 62.1 Ley 39/2015','Definición legal de la denuncia.',null),
('aux-age:11-cd7e00a1c2','aux-age',11,'Si existe vicio de forma y no se estima procedente resolver sobre el fondo, el órgano que resuelve el recurso:','["Dictará resolución favorable", "Inadmitirá el recurso", "Ordenará la retroacción del procedimiento al momento en que el vicio fue cometido", "Anulará todo el expediente y ordenará iniciar uno nuevo desde el principio"]'::jsonb,2,'Art. 119.2 Ley 39/2015','Se ordena retrotraer el procedimiento al momento del vicio.',null),
('aux-age:11-79374ff05b','aux-age',11,'En los procedimientos de responsabilidad patrimonial ante la AGE, es preceptivo el dictamen del Consejo de Estado cuando la indemnización reclamada sea de cuantía igual o superior a:','["50.000 euros", "6.000 euros", "100.000 euros", "30.000 euros"]'::jsonb,0,'Art. 81.2 Ley 39/2015','Desde 50.000 € (o la cuantía fijada por la legislación autonómica) es preceptivo el dictamen.',null),
('aux-age:11-85f4bb4946','aux-age',11,'Cuando deban resolverse una pluralidad de recursos derivados de un mismo acto y se haya interpuesto recurso judicial contra una resolución administrativa o contra el correspondiente acto presunto:','["El órgano administrativo podrá acordar la suspensión del plazo para resolver hasta que recaiga pronunciamiento judicial", "Deberá inadmitir todos los recursos pendientes", "Deberá estimar todos los recursos", "Deberá resolver todos los recursos en el plazo ordinario, sin esperar al pronunciamiento judicial, para no perjudicar a los interesados que no han acudido a los tribunales"]'::jsonb,0,'Art. 120.1 Ley 39/2015','El órgano puede suspender el plazo hasta que haya pronunciamiento judicial.',null),
('aux-age:11-f74b18ba08','aux-age',11,'En el despacho de los expedientes se guardará:','["El orden que prefiera el funcionario responsable", "El orden alfabético de los interesados, salvo orden motivada en contrario del superior jerárquico del instructor", "El orden riguroso de incoación en asuntos de homogénea naturaleza, salvo orden motivada en contrario", "El orden de prioridad que fije cada interesado en su solicitud, o el que indique el superior jerárquico en cada caso concreto"]'::jsonb,2,'Art. 71.2 Ley 39/2015','Su incumplimiento puede dar lugar a responsabilidad disciplinaria.',null),
('aux-age:11-40d588e50b','aux-age',11,'El órgano que ordene un acto de ejecución material de resoluciones está obligado a:','["Publicarlo en el BOE y en el boletín autonómico antes de iniciar la actuación material, sin necesidad de notificación personal", "Solicitar autorización judicial", "Esperar a que el acto sea firme en vía administrativa y solicitar autorización judicial para ejecutarlo", "Notificar al particular interesado la resolución que autorice la actuación administrativa"]'::jsonb,3,'Art. 97.2 Ley 39/2015','Debe notificar al particular la resolución que autorice la actuación.',null),
('aux-age:1-58573a3faf','aux-age',1,'El contenido del derecho de propiedad y de herencia lo delimita:','["Las ordenanzas fiscales de cada municipio", "La voluntad del propietario", "Su función social, de acuerdo con las leyes", "El Registro de la Propiedad"]'::jsonb,2,'Art. 33.2 CE','La función social de estos derechos delimitará su contenido, de acuerdo con las leyes.',null),
('aux-age:11-c2d2e0a64c','aux-age',11,'El recurso extraordinario de revisión se interpone contra:','["Los actos que no ponen fin a la vía administrativa, en cualquier momento", "Los actos firmes en vía administrativa, cuando concurra alguna de las circunstancias del art. 125.1", "Cualquier acto de trámite", "Las disposiciones de carácter general, cuando concurra alguna de las circunstancias del art. 125.1"]'::jsonb,1,'Art. 113 Ley 39/2015','Procede contra actos firmes en vía administrativa en los casos del art. 125.1.',null),
('aux-age:11-e633537e9b','aux-age',11,'NO forma parte del expediente administrativo:','["La información auxiliar o de apoyo, como notas, borradores u opiniones, salvo los informes solicitados antes de la resolución", "Las notificaciones practicadas", "Las pruebas practicadas", "Los informes preceptivos, que se incorporan a un expediente auxiliar distinto del principal y no se remiten al juzgado"]'::jsonb,0,'Art. 70.4 Ley 39/2015','Notas, borradores, opiniones, resúmenes y comunicaciones internas no forman parte del expediente.',null),
('aux-age:1-bf9d2f0964','aux-age',1,'Según el art. 23.1, los ciudadanos participan en los asuntos públicos:','["Solo por medio de los partidos políticos con representación parlamentaria", "Directamente o por medio de representantes elegidos en elecciones periódicas por sufragio censitario", "Por medio de representantes designados por las Cortes Generales y por los Parlamentos autonómicos", "Directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal"]'::jsonb,3,'Art. 23.1 CE','Participan directamente o por medio de representantes libremente elegidos en elecciones periódicas por sufragio universal.',null),
('aux-age:11-2b17b59b5a','aux-age',11,'Las declaraciones responsables y las comunicaciones permiten el reconocimiento o ejercicio de un derecho o el inicio de una actividad:','["Tras la resolución expresa que reconozca el derecho, que deberá dictarse en un mes", "A los tres meses de su presentación si la Administración no se opone", "Desde el día de su presentación, sin perjuicio de las facultades de comprobación de la Administración", "Desde el día de su presentación, sin que la Administración pueda comprobar después lo declarado"]'::jsonb,2,'Art. 69.3 Ley 39/2015','Producen efectos desde su presentación.',null),
('aux-age:1-ded29f55a1','aux-age',1,'Las bases de la organización militar se regulan mediante:','["Un real decreto", "Una ley ordinaria", "Una ley orgánica", "Una orden del Ministerio de Defensa"]'::jsonb,2,'Art. 8.2 CE','Una ley orgánica regulará las bases de la organización militar.',null),
('aux-age:1-ee12b3116e','aux-age',1,'Según el art. 51.1, los poderes públicos garantizarán la defensa de:','["Los consumidores y usuarios, protegiendo mediante procedimientos eficaces su seguridad, salud e intereses económicos", "Los comerciantes minoristas exclusivamente", "Las empresas frente a la competencia desleal y los productores frente a las importaciones de terceros países", "Los productores agrarios"]'::jsonb,0,'Art. 51.1 CE','Garantizarán la defensa de los consumidores y usuarios mediante procedimientos eficaces.',null),
('aux-age:11-a99e5de9e8','aux-age',11,'Si el escrito de iniciación se formuló por dos o más interesados, el desistimiento o la renuncia:','["No está permitido una vez iniciado el procedimiento", "Requiere el acuerdo unánime de todos los que firmaron el escrito de iniciación", "Solo afectará a aquellos que la hubiesen formulado", "Afectará a todos los interesados, salvo que alguno inste la continuación en diez días"]'::jsonb,2,'Art. 94.2 Ley 39/2015','El desistimiento solo afecta a quien lo formula.',null),
('aux-age:11-deb24972d5','aux-age',11,'Es causa del recurso extraordinario de revisión:','["Que haya transcurrido el plazo para interponer el recurso de alzada sin haberlo hecho, por causa no imputable al interesado", "Que el interesado cambie de opinión", "Que el acto sea desfavorable y el interesado aporte cualquier documento nuevo, aunque no evidencie error alguno en la resolución", "Que aparezcan documentos de valor esencial para la resolución que evidencien el error de la resolución recurrida"]'::jsonb,3,'Art. 125.1 b) Ley 39/2015','Las causas son: error de hecho, documentos esenciales nuevos, documentos o testimonios falsos declarados en sentencia firme y conducta punible declarada en sentencia firme.',null),
('aux-age:11-501220791e','aux-age',11,'La declaración de lesividad de los actos favorables anulables tiene como finalidad:','["Sancionar al interesado que se benefició del acto", "Convertirlos en actos nulos de pleno derecho para poder revisarlos de oficio en cualquier momento", "Su posterior impugnación ante el orden jurisdiccional contencioso-administrativo", "Anularlos directamente en vía administrativa"]'::jsonb,2,'Art. 107.1 Ley 39/2015','La Administración declara la lesividad para impugnarlos después ante la jurisdicción contencioso-administrativa.',null),
('aux-age:11-e5f7be7280','aux-age',11,'Para los actos y gestiones de mero trámite, la representación:','["No está permitida", "Se presumirá", "Debe acreditarse ante notario", "Debe inscribirse en el registro de apoderamientos"]'::jsonb,1,'Art. 5.3 Ley 39/2015','En los actos de mero trámite se presume la representación.',null),
('aux-age:11-f5d6a8139c','aux-age',11,'Según el art. 130.1, las Administraciones Públicas revisarán periódicamente su normativa vigente para:','["Derogarla cada cuatro años y aprobar textos refundidos", "Remitirla al Tribunal Constitucional para que verifique su adecuación a la Constitución y a los Estatutos de Autonomía", "Adaptarla a los principios de buena regulación, sin necesidad de evaluar si ha conseguido sus objetivos", "Adaptarla a los principios de buena regulación y comprobar en qué medida han conseguido sus objetivos"]'::jsonb,3,'Art. 130.1 Ley 39/2015','El resultado de la evaluación se plasma en un informe que se hará público.',null),
('aux-age:1-49cd3ef756','aux-age',1,'En el control y la gestión de los centros sostenidos con fondos públicos intervienen:','["Solo la Administración educativa competente", "Los sindicatos más representativos y la Administración", "Solo el director del centro y el titular, en el caso de los centros concertados", "Los profesores, los padres y, en su caso, los alumnos"]'::jsonb,3,'Art. 27.7 CE','Intervienen los profesores, los padres y, en su caso, los alumnos, en los términos que la ley establezca.',null),
('aux-age:11-1ea692afbc','aux-age',11,'Son nulos de pleno derecho los actos:','["Dictados por órgano jerárquicamente incompetente", "Que tengan un contenido imposible", "Que no indiquen los recursos", "Que tengan un error material"]'::jsonb,1,'Art. 47.1 c) Ley 39/2015','El contenido imposible es causa de nulidad (art. 47.1 c).',null),
('aux-age:1-fd048d680d','aux-age',1,'Según el art. 19, los españoles tienen derecho a:','["Una vivienda pública en su lugar de residencia", "Cambiar de nacionalidad libremente y entrar y salir de España sin requisitos", "Viajar sin pasaporte a cualquier país y residir en el extranjero sin requisitos", "Elegir libremente su residencia y a circular por el territorio nacional"]'::jsonb,3,'Art. 19 CE','Tienen derecho a elegir libremente su residencia y a circular por el territorio nacional.',null),
('aux-age:14-623ab536f8','aux-age',14,'Las retribuciones básicas están integradas por:','["La productividad y las gratificaciones por servicios extraordinarios", "El sueldo asignado a cada subgrupo o grupo y los trienios", "El complemento de destino y el complemento específico", "El sueldo asignado a cada subgrupo, los trienios y el complemento de destino del puesto que se ocupe"]'::jsonb,1,'Art. 23 TREBEP','Los trienios consisten en una cantidad por cada tres años de servicio.',null),
('aux-age:14-c4060662c5','aux-age',14,'Los Delegados de Personal representan a los funcionarios en unidades electorales que cuenten con:','["Más de 50 funcionarios", "Menos de 6 funcionarios", "Entre 6 y 49 funcionarios", "Más de 250 funcionarios"]'::jsonb,2,'Art. 39.2 TREBEP','A partir de 50 funcionarios hay Juntas de Personal.',null)
